function builderActionButton(
  label,
  action,
  id,
  extraClass = "",
  iconName = "",
) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `button button-icon ${extraClass}`.trim();
  const automaticIcon = {
    "move-category-up": "up",
    "move-field-up": "up",
    "move-category-down": "down",
    "move-field-down": "down",
    "edit-category": "edit",
    "edit-field": "edit",
    "edit-condition": "edit",
    "delete-category": "trash",
    "delete-field": "trash",
    "delete-condition": "trash",
    "detach-global-category": "unlink",
    "detach-global-field": "unlink",
  }[action];
  button.append(actionIcon(iconName || automaticIcon || "edit"));
  button.dataset.builderAction = action;
  button.dataset.itemId = id;
  button.title = label;
  button.setAttribute("aria-label", label);
  return button;
}
function updateStickyHeaderOffset() {
  const headerHeight = elements.appHeader
    ? Math.ceil(elements.appHeader.getBoundingClientRect().height)
    : 0;

  document.documentElement.style.setProperty(
    "--app-header-height",
    `${headerHeight}px`,
  );
}

function installStickyHeaderTracking() {
  updateStickyHeaderOffset();

  if (elements.appHeader && "ResizeObserver" in window) {
    state.headerResizeObserver?.disconnect();
    state.headerResizeObserver = new ResizeObserver(() => {
      updateStickyHeaderOffset();
    });
    state.headerResizeObserver.observe(elements.appHeader);
  }

  window.addEventListener("resize", updateStickyHeaderOffset);
}

function scheduleViewportPaintRecovery(forcePaint = false) {
  if (state.viewportPaintFrame !== null) {
    window.cancelAnimationFrame(state.viewportPaintFrame);
  }

  state.viewportPaintFrame = window.requestAnimationFrame(() => {
    state.viewportPaintFrame = null;
    updateStickyHeaderOffset();

    if (!forcePaint || !elements.appHeader) {
      return;
    }

    if (state.viewportPaintResetFrame !== null) {
      window.cancelAnimationFrame(state.viewportPaintResetFrame);
    }

    // Move the existing compositor layer by an imperceptible amount for one
    // frame. This forces Chromium to repaint the header without changing its
    // size, position, or visible design.
    elements.appHeader.style.transform = "translate3d(0, 0, 0.0001px)";
    if (elements.page) {
      const scrollTop = elements.page.scrollTop;
      void elements.page.offsetHeight;
      elements.page.scrollTop = scrollTop;
    }

    state.viewportPaintResetFrame = window.requestAnimationFrame(() => {
      state.viewportPaintResetFrame = null;
      elements.appHeader.style.transform = "";
    });
  });
}

function installViewportPaintRecovery() {
  const recover = () => scheduleViewportPaintRecovery(true);

  window.addEventListener("focus", recover);
  window.addEventListener("pageshow", recover);
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) {
      recover();
    }
  });

  document.addEventListener(
    "keydown",
    (event) => {
      if (event.key === "Tab") {
        state.keyboardNavigationPending = true;
      }
    },
    true,
  );

  document.addEventListener(
    "focusin",
    (event) => {
      if (!state.keyboardNavigationPending) {
        return;
      }
      state.keyboardNavigationPending = false;

      const target = event.target;
      if (
        elements.page &&
        target instanceof HTMLElement &&
        elements.page.contains(target)
      ) {
        const pageRect = elements.page.getBoundingClientRect();
        const targetRect = target.getBoundingClientRect();
        if (
          targetRect.top < pageRect.top ||
          targetRect.bottom > pageRect.bottom
        ) {
          target.scrollIntoView({ block: "nearest", inline: "nearest" });
        }
      }
      scheduleViewportPaintRecovery(true);
    },
    true,
  );
}

function navigationSchema() {
  return state.mode === "builder" ? state.draftSchema : state.schema;
}

function navigationTarget(categoryId) {
  const prefix =
    state.mode === "builder"
      ? "builder-category"
      : state.mode === "readonly"
        ? "readonly-category"
        : "entry-category";

  return document.getElementById(`${prefix}-${categoryId}`);
}

function categoryTargetIsVisible(target) {
  return Boolean(target && !target.closest("[hidden]"));
}

function setActiveBuilderCategory(categoryId) {
  state.activeBuilderCategoryId = categoryId || null;

  elements.builderCategoryNavList
    .querySelectorAll("[data-builder-category-nav]")
    .forEach((button) => {
      button.classList.toggle(
        "category-nav-button-active",
        button.dataset.builderCategoryNav === categoryId,
      );
    });
}

function scrollToBuilderCategory(categoryId) {
  const target = navigationTarget(categoryId);

  if (!categoryTargetIsVisible(target)) {
    return;
  }

  if (state.mode === 'entry') expandEntryCategoryForControl(target);
  if (state.mode === 'builder') {
    const panel = target.closest('[data-main-category-panel]');
    if (panel) selectMainCategoryTab(panel.dataset.mainCategoryPanel, elements.builderCategories);
  }

  setActiveBuilderCategory(categoryId);

  target.scrollIntoView({
    behavior: "smooth",
    block: "start",
  });

  target.focus({
    preventScroll: true,
  });

  target.classList.remove("category-navigation-highlight");
  void target.offsetWidth;
  target.classList.add("category-navigation-highlight");

  window.setTimeout(() => {
    target.classList.remove("category-navigation-highlight");
  }, 1600);
}

function scrollToBuilderSection(targetId) {
  const target = document.getElementById(targetId);
  if (!target) {
    return;
  }
  const preview = target.closest('.builder-layout-preview');
  const panel = target.closest('[data-main-category-panel]');
  if (preview && panel) selectMainCategoryTab(panel.dataset.mainCategoryPanel, preview);
  target.scrollIntoView({ behavior: "smooth", block: "start" });
  target.focus({ preventScroll: true });
  target.classList.remove("category-navigation-highlight");
  void target.offsetWidth;
  target.classList.add("category-navigation-highlight");
}

function createNavigationButton(label, clickHandler, extraClass = "") {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `category-nav-button ${extraClass}`.trim();
  button.textContent = label;
  button.addEventListener("click", clickHandler);
  return button;
}

function createCategoryNavigationToggle(label, row, children) {
  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'category-nav-toggle';
  const update = (expanded) => {
    children.hidden = !expanded;
    row.setAttribute('aria-expanded', String(expanded));
    toggle.setAttribute('aria-expanded', String(expanded));
    toggle.setAttribute('aria-label', `${expanded ? 'طي' : 'توسيع'} ${label}`);
    toggle.textContent = expanded ? '−' : '+';
  };
  update(true);
  toggle.addEventListener('click', (event) => {
    event.stopPropagation();
    update(children.hidden);
  });
  row.addEventListener('click', (event) => {
    if (event.target === row) update(children.hidden);
  });
  return toggle;
}

function appendCategoryNavigationTree(container, schema) {
  const categories = schema?.categories || [];
  const categoryIds = new Set(categories.map((category) => category.id));
  const visited = new Set();

  const appendNode = (category, parent) => {
    if (!category || visited.has(category.id)) {
      return;
    }
    visited.add(category.id);

    const children = categoryChildren(category.id, schema);
    const node = document.createElement("div");
    node.className = "category-nav-node";
    node.dataset.categoryNavNode = category.id;

    const row = document.createElement("div");
    row.className = "category-nav-row";

    if (children.length) {
      const childList = document.createElement("div");
      childList.className = "category-nav-children";
      children.forEach((child) => appendNode(child, childList));
      row.append(createCategoryNavigationToggle(category.label, row, childList));

      const button = createNavigationButton(category.label, () => {
        scrollToBuilderCategory(category.id);
      });
      button.dataset.builderCategoryNav = category.id;
      row.append(button);
      node.append(row, childList);
    } else {
      const spacer = document.createElement("span");
      spacer.className = "category-nav-toggle-spacer";
      row.append(spacer);
      const button = createNavigationButton(category.label, () => {
        scrollToBuilderCategory(category.id);
      });
      button.dataset.builderCategoryNav = category.id;
      row.append(button);
      node.append(row);
    }

    parent.append(node);
  };

  categories
    .filter(
      (category) =>
        !category.parent_category_id ||
        !categoryIds.has(category.parent_category_id),
    )
    .forEach((category) => appendNode(category, container));
  categories.forEach((category) => appendNode(category, container));
}

function renderBuilderCategoryNavigator() {
  elements.builderCategoryNavList.replaceChildren();

  const schema = navigationSchema();
  const categories = schema?.categories || [];
  const builderMode = state.mode === "builder";

  if (builderMode && state.builderScope === "global") {
    elements.categoryNavTitle.textContent = "الحقول العامة";
    elements.builderCategoryNavList.setAttribute("aria-label", "التنقل بين التعريفات العامة");
    const appendTarget = (label, targetId, className = "builder-section-nav-button") => {
      const button = createNavigationButton(label, () => scrollToBuilderSection(targetId), className);
      elements.builderCategoryNavList.append(button);
    };
    const appendDefinitionNode = (tree, label, targetId, childItems = []) => {
      const node = document.createElement("div");
      node.className = "category-nav-node";
      const row = document.createElement("div");
      row.className = "category-nav-row";
      const toggle = document.createElement("span");
      toggle.className = "category-nav-toggle-spacer";
      const button = createNavigationButton(label, () => scrollToBuilderSection(targetId));
      row.append(toggle, button);
      node.append(row);
      if (childItems.length) {
        const children = document.createElement("div");
        children.className = "category-nav-children";
        childItems.forEach((child) => appendDefinitionNode(
          children,
          child.label,
          child.targetId,
          child.children || [],
        ));
        toggle.replaceWith(createCategoryNavigationToggle(label, row, children));
        node.append(children);
      }
      tree.append(node);
    };
    appendTarget("الفئات العامة", "global-category-definitions-heading");
    const categoryTree = document.createElement("div");
    categoryTree.className = "category-nav-tree builder-category-nav-tree";
    Object.values(state.globalDefinitions?.categories || {}).forEach((item) => {
      const definitionTree = globalCategoryTree(item.definition || {});
      const root = definitionTree.find((node) => !node.parent_key) || definitionTree[0];
      const childrenFor = (node) => [
        ...(node.fields || []).map((entry) => ({
          label: entry.definition?.label || entry.key,
          targetId: globalEmbeddedFieldTargetId(item.id, entry.key),
        })),
        ...definitionTree.filter((candidate) => candidate.parent_key === node.key).map((child) => ({
          label: child.definition?.label || "فئة عامة",
          targetId: `global-category-node-${item.id}-${child.key}`,
          children: childrenFor(child),
        })),
      ];
      appendDefinitionNode(
        categoryTree,
        root?.definition?.label || item.definition?.label || item.id,
        `global-definition-category-${item.id}`,
        root ? childrenFor(root) : [],
      );
    });
    if (categoryTree.childElementCount) elements.builderCategoryNavList.append(categoryTree);
    appendTarget("الحقول العامة المنفصلة", "global-standalone-panel");
    const fieldTree = document.createElement("div");
    fieldTree.className = "category-nav-tree builder-category-nav-tree";
    Object.values(state.globalDefinitions?.fields || {}).forEach((item) => appendDefinitionNode(fieldTree, item.definition?.label || item.id, `global-definition-field-${item.id}`));
    if (fieldTree.childElementCount) elements.builderCategoryNavList.append(fieldTree);
    appendTarget("شروط الظهور", "global-conditions-panel");
    return;
  }

  elements.categoryNavTitle.textContent = builderMode
    ? "أقسام المصمّم"
    : "فئات السجل";
  elements.builderSidebarAddCategoryButton.hidden = !builderMode;
  elements.builderSidebarAddFieldButton.hidden = !builderMode;
  elements.builderCategoryNavList.setAttribute(
    "aria-label",
    builderMode ? "فئات التطبيق" : "فئات السجل",
  );

  if (builderMode) {
    const builderSections = [
      ["ملخص المصمّم", "builder-intro-panel"],
      ["الفئات والحقول", "builder-categories-panel"],
    ];
    builderSections.forEach(([label, targetId]) => {
      const button = createNavigationButton(
        label,
        () => scrollToBuilderSection(targetId),
        "builder-section-nav-button",
      );
      elements.builderCategoryNavList.append(button);
    });

    if (categories.length) {
      const tree = document.createElement("div");
      tree.className = "category-nav-tree builder-category-nav-tree";
      appendCategoryNavigationTree(tree, schema);
      elements.builderCategoryNavList.append(tree);
    }

    const conditionsButton = createNavigationButton(
      "شروط الظهور",
      () => scrollToBuilderSection("builder-conditions-panel"),
      "builder-section-nav-button",
    );
    elements.builderCategoryNavList.append(conditionsButton);
    setActiveBuilderCategory(state.activeBuilderCategoryId);
    return;
  }

  if (!categories.length) {
    const empty = document.createElement("p");
    empty.className = "category-nav-empty";
    empty.textContent = "لا توجد فئات للتنقل بينها.";
    elements.builderCategoryNavList.append(empty);
    return;
  }

  const tree = document.createElement("div");
  tree.className = "category-nav-tree";
  appendCategoryNavigationTree(tree, schema);
  elements.builderCategoryNavList.append(tree);
  syncEntryCategoryNavigatorVisibility();
}

function syncEntryCategoryNavigatorVisibility() {
  if (!["entry", "readonly"].includes(state.mode)) {
    return;
  }

  let firstVisibleId = null;

  const nodes = [
    ...elements.builderCategoryNavList.querySelectorAll(
      "[data-category-nav-node]",
    ),
  ];

  nodes.forEach((node) => {
    const button = node.querySelector(":scope > .category-nav-row [data-builder-category-nav]");
      const categoryId = button.dataset.builderCategoryNav;
      const target = navigationTarget(categoryId);
      const visible = categoryTargetIsVisible(target);

      button.dataset.categoryTargetVisible = String(visible);
      button.disabled = !visible;

      if (visible && !firstVisibleId) {
        firstVisibleId = categoryId;
      }
  });

  [...nodes].reverse().forEach((node) => {
    const ownButton = node.querySelector(
      ":scope > .category-nav-row [data-builder-category-nav]",
    );
    const ownVisible = ownButton?.dataset.categoryTargetVisible === "true";
    const childVisible = [...node.querySelectorAll(":scope > .category-nav-children > [data-category-nav-node]")]
      .some((child) => !child.hidden);
    node.hidden = !ownVisible && !childVisible;
  });

  const activeButton = elements.builderCategoryNavList.querySelector(
    `[data-builder-category-nav="${attributeSafe(
      state.activeBuilderCategoryId || "",
    )}"]:not(:disabled)`,
  );

  if (!activeButton) {
    setActiveBuilderCategory(firstVisibleId);
  }
}

function observeBuilderCategories() {
  if (state.builderCategoryObserver) {
    state.builderCategoryObserver.disconnect();
    state.builderCategoryObserver = null;
  }

  if (!("IntersectionObserver" in window)) {
    return;
  }

  const selector =
    state.mode === "builder"
      ? ".builder-category"
      : state.mode === "readonly"
        ? "[data-readonly-category]"
        : "[data-entry-category]";

  const targets = [...document.querySelectorAll(selector)].filter(
    categoryTargetIsVisible,
  );

  if (!targets.length) {
    return;
  }

  state.builderCategoryObserver = new IntersectionObserver(
    (entries) => {
      const visible = entries
        .filter(
          (entry) =>
            entry.isIntersecting && categoryTargetIsVisible(entry.target),
        )
        .sort(
          (first, second) => second.intersectionRatio - first.intersectionRatio,
        );

      if (!visible.length) {
        return;
      }

      setActiveBuilderCategory(visible[0].target.dataset.categoryId);
    },
    {
      root: null,
      rootMargin: "-15% 0px -65% 0px",
      threshold: [0, 0.1, 0.3, 0.6, 1],
    },
  );

  targets.forEach((target) => {
    state.builderCategoryObserver.observe(target);
  });
}

function scheduleCategoryObservation() {
  window.clearTimeout(state.categoryObserverTimer);
  state.categoryObserverTimer = window.setTimeout(observeBuilderCategories, 40);
}

function refreshCategoryNavigation() {
  renderBuilderCategoryNavigator();
  scheduleCategoryObservation();
}

function renderBuilderCategories() {
  renderBuilderPreview();
}

function fieldQualifiedLabel(fieldId, schema = state.draftSchema) {
  const field = fieldById(fieldId, schema);
  const category = fieldCategory(fieldId, schema);
  return field && category
    ? `${category.label} ← ${field.label}`
    : "عنصر محذوف";
}

function targetQualifiedLabel(
  targetType,
  targetId,
  schema = state.draftSchema,
) {
  if (targetType === "category") {
    return `الفئة: ${categoryById(targetId, schema)?.label || "محذوفة"}`;
  }
  return `الحقل: ${fieldQualifiedLabel(targetId, schema)}`;
}

function conditionDisplayValue(condition) {
  if (["empty", "not_empty"].includes(condition.operator)) {
    return "";
  }

  const source = fieldById(condition.source_field_id, state.draftSchema);

  if (!source) {
    return String(condition.value || "");
  }

  if (source.type === "checkbox") {
    return checkboxDisplayMeaning(source, condition.value);
  }

  if (["select", "yes_no", "checkbox_group"].includes(source.type)) {
    return optionLabelForValue(source, condition.value);
  }

  return String(condition.value || "");
}

function conditionSummaryText(condition) {
  const sourceLabel = fieldQualifiedLabel(condition.source_field_id);

  const operator = OPERATOR_LABELS[condition.operator] || condition.operator;

  const value = conditionDisplayValue(condition);

  const valueText = ["empty", "not_empty"].includes(condition.operator)
    ? ""
    : ` «${value}»`;

  const negate = condition.negate ? "ليس صحيحًا أن " : "";

  return (
    `${negate}${sourceLabel} ${operator}${valueText}` +
    ` ← يؤثر في ${targetQualifiedLabel(condition.target_type, condition.target_id)}`
  );
}

function conditionsGrouped(rules) {
  const groups = new Map();

  rules.forEach((condition) => {
    const groupId =
      condition.group_id ||
      `legacy-${condition.target_type}-${condition.target_id}`;

    if (!groups.has(groupId)) {
      groups.set(groupId, []);
    }

    groups.get(groupId).push(condition);
  });

  return groups;
}
function createConditionRuleRow(condition) {
  const row = document.createElement("div");
  row.className = "condition-row";

  const expression = document.createElement("div");
  expression.className = "condition-expression";
  expression.textContent = conditionSummaryText(condition);

  const actions = document.createElement("div");
  actions.className = "builder-actions";

  const edit = builderActionButton(
    "تعديل الشرط",
    "edit-condition",
    condition.id,
    "",
    "edit",
  );

  const remove = builderActionButton(
    "حذف الشرط",
    "delete-condition",
    condition.id,
    "button-danger-quiet",
    "trash",
  );

  edit.addEventListener("click", (event) => {
    event.stopPropagation();
    openConditionDialog(condition.id);
  });

  remove.addEventListener("click", (event) => {
    event.stopPropagation();
    deleteCondition(condition.id);
  });

  actions.append(edit, remove);
  row.append(expression, actions);

  return row;
}

function appendConditionGroups(container, rules) {
  const groups = conditionsGrouped(rules);

  [...groups.values()].forEach((groupRules, groupIndex) => {
    if (groupIndex > 0) {
      const separator = document.createElement("div");

      separator.className = "condition-or-separator";
      separator.textContent = "أو — OR";

      container.append(separator);
    }

    const group = document.createElement("section");
    group.className = "condition-group-card";

    const heading = document.createElement("div");
    heading.className = "condition-group-heading";

    const title = document.createElement("strong");
    title.textContent = `المجموعة ${groupIndex + 1}`;

    const relation = document.createElement("span");
    relation.textContent = "جميع شروط هذه المجموعة: AND";

    heading.append(title, relation);
    group.append(heading);

    groupRules.forEach((condition) => {
      group.append(createConditionRuleRow(condition));
    });

    container.append(group);
  });
}

function renderBuilderConditions() {
  elements.builderConditions.replaceChildren();

  const conditions = state.draftSchema.conditions || [];

  elements.noConditionsMessage.hidden = conditions.length > 0;

  const targets = new Map();

  conditions.forEach((condition) => {
    const key = `${condition.target_type}:` + `${condition.target_id}`;

    if (!targets.has(key)) {
      targets.set(key, []);
    }

    targets.get(key).push(condition);
  });

  const orderedTargetKeys = [];

  for (const { category } of orderedCategoryTree(state.draftSchema)) {
    orderedTargetKeys.push(`category:${category.id}`);
    for (const field of category.fields) {
      orderedTargetKeys.push(`field:${field.id}`);
    }
  }

  for (const key of orderedTargetKeys) {
    const rules = targets.get(key);
    if (!rules) {
      continue;
    }

    rules.forEach((condition) => {
      const card = createConditionRuleRow(condition);
      card.setAttribute(
        "aria-label",
        targetQualifiedLabel(condition.target_type, condition.target_id),
      );
      elements.builderConditions.append(card);
    });
  }
}

function renderTargetConditionEditor(targetType, targetId, container) {
  container.replaceChildren();

  const rules = conditionsFor(targetType, targetId, state.draftSchema);

  if (!rules.length) {
    const empty = document.createElement("div");
    empty.className = "builder-empty";
    empty.textContent = "لا توجد شروط ظهور لهذا العنصر.";

    container.append(empty);
    return;
  }

  appendConditionGroups(container, rules);
}

function renderCategoryConditionEditor() {
  renderTargetConditionEditor(
    "category",
    state.editingCategoryId,
    elements.categoryConditionsList,
  );
}

function renderFieldConditionEditor() {
  renderTargetConditionEditor(
    "field",
    state.editingFieldId,
    elements.fieldConditionsList,
  );
}

function refreshConditionEditors() {
  renderBuilderConditions();

  if (elements.categoryDialog.open) {
    renderCategoryConditionEditor();
  }

  if (elements.fieldDialog.open) {
    renderFieldConditionEditor();
  }
}

function deleteCondition(conditionId) {
  state.draftSchema.conditions = state.draftSchema.conditions.filter(
    (condition) => condition.id !== conditionId,
  );

  markDirty();
  refreshConditionEditors();
}

function escapeHtml(value) {
  const node = document.createElement("span");
  node.textContent = String(value);
  return node.innerHTML;
}

function moveArrayItem(array, index, change) {
  const nextIndex = index + change;
  if (index < 0 || nextIndex < 0 || nextIndex >= array.length) {
    return false;
  }
  [array[index], array[nextIndex]] = [array[nextIndex], array[index]];
  return true;
}

function dataLossWarning(noun) {
  const count = state.schema?.stats?.record_count || 0;
  return count
    ? `يوجد ${count} سجل محفوظ. حذف ${noun} ثم حفظ التصميم سيحذف بياناته نهائيًا. هل تريد المتابعة؟`
    : `هل تريد حذف ${noun}؟`;
}

function removeReferencesToFields(fieldIds) {
  const ids = new Set(fieldIds);
  state.draftSchema.conditions = state.draftSchema.conditions.filter(
    (condition) =>
      !ids.has(condition.source_field_id) &&
      !(condition.target_type === "field" && ids.has(condition.target_id)),
  );
  state.draftSchema.categories.forEach((category) => {
    if (ids.has(category.anchor_field_id)) {
      category.anchor_field_id = null;
    }
    if (ids.has(category.parent_field_id)) {
      category.parent_field_id = null;
    }
    if (ids.has(category.card_title_field_id)) {
      category.card_title_field_id = null;
    }
    if (ids.has(category.card_sort?.field_id)) {
      category.card_sort.field_id = null;
      category.card_sort.mode = "manual";
    }
    category.fields.forEach((field) => {
      if (field.type === "file") {
        field.file_naming.parts = field.file_naming.parts.filter(
          (part) => !ids.has(part.field_id),
        );
      }
      if (ids.has(field.option_filter?.source_field_id)) {
        field.option_filter = null;
      }
      if (ids.has(field.validation?.compare_field_id)) {
        field.validation.compare_field_id = null;
        field.validation.compare_operator = null;
      }
      if (ids.has(field.auto_update?.source_field_id)) {
        field.auto_update = null;
      }
    });
  });
}

async function handleBuilderAction(button) {
  const action = button.dataset.builderAction;
  const itemId = button.dataset.itemId;
  const categoryId = button.dataset.categoryId;

  if (action === "move-category-up" || action === "move-category-down") {
    const index = state.draftSchema.categories.findIndex(
      (category) => category.id === itemId,
    );
    const category = state.draftSchema.categories[index];
    if (!category) return;
    const peers = builderPreviewCategoryPeers(category);
    const peerIndex = peers.findIndex((item) => item.id === itemId);
    const destination = peers[peerIndex + (action.endsWith('up') ? -1 : 1)];
    if (!destination) return;
    const destinationIndex = state.draftSchema.categories.findIndex((item) => item.id === destination.id);
    if (
      moveArrayItem(
        state.draftSchema.categories,
        index,
        destinationIndex - index,
      )
    ) {
      markDirty();
      renderBuilderCategories();
    }
    return;
  }
  if (action === "edit-category") {
    const category = categoryById(itemId);
    if (category?.global_ref) {
      if (!(await requestConfirmation("تعديل هذه الفئة من داخل التصميم سيفصل إعدادها عن التعريف العام.", {
        title: "فصل الفئة العامة",
        confirmLabel: "فصل وتعديل",
      }))) return;
    }
    openCategoryDialog(itemId, Boolean(category?.global_ref));
    return;
  }
  if (action === "publish-global-category") {
    void publishLocalDefinition("category", itemId);
    return;
  }
  if (action === "detach-global-category") {
    const category = categoryById(itemId);
    if (category && await requestConfirmation("فصل إعداد هذه الفئة عن التعريف العام؟", {
      title: "فصل الفئة العامة",
      confirmLabel: "فصل الارتباط",
    })) {
      category.global_ref = null;
      markDirty();
      renderBuilder();
    }
    return;
  }
  if (action === "delete-category") {
    const category = categoryById(itemId);
    if (
      !category ||
      !(await requestConfirmation(dataLossWarning(`الفئة "${category.label}"`), {
        title: "حذف الفئة",
        confirmLabel: "حذف الفئة",
      }))
    ) {
      return;
    }
    removeReferencesToFields(category.fields.map((field) => field.id));
    const relatedPersonModeSource = relatedPersonModeSourceId(itemId);
    state.draftSchema.conditions = state.draftSchema.conditions.filter(
      (condition) =>
        condition.source_field_id !== relatedPersonModeSource &&
        !(
          condition.target_type === "category" && condition.target_id === itemId
        ),
    );
    state.draftSchema.categories.forEach((candidate) => {
      if (candidate.parent_category_id === itemId) {
        candidate.parent_category_id = category.parent_category_id || null;
        candidate.parent_field_id = null;
      }
    });
    state.draftSchema.categories = state.draftSchema.categories.filter(
      (candidate) => candidate.id !== itemId,
    );
    markDirty();
    renderBuilder();
    return;
  }
  if (action === "add-field") {
    openFieldDialog(categoryId);
    return;
  }
  if (action === "edit-field") {
    const field = fieldById(itemId);
    if (field?.global_ref) {
      if (!(await requestConfirmation("تعديل هذا الحقل من داخل التصميم سيفصل إعداداته عن التعريف العام.", {
        title: "فصل الحقل العام",
        confirmLabel: "فصل وتعديل",
      }))) return;
    }
    openFieldDialog(categoryId, itemId, Boolean(field?.global_ref));
    return;
  }
  if (action === "publish-global-field") {
    void publishLocalDefinition("field", itemId);
    return;
  }
  if (action === "detach-global-field") {
    const field = fieldById(itemId);
    if (field && await requestConfirmation("فصل إعداد هذا الحقل عن التعريف العام؟", {
      title: "فصل الحقل العام",
      confirmLabel: "فصل الارتباط",
    })) {
      field.global_ref = null;
      markDirty();
      renderBuilder();
    }
    return;
  }
  if (action === "delete-field") {
    const category = categoryById(categoryId);
    const field = fieldById(itemId);
    if (
      !category ||
      !field ||
      !(await requestConfirmation(dataLossWarning(`الحقل "${field.label}"`), {
        title: "حذف الحقل",
        confirmLabel: "حذف الحقل",
      }))
    ) {
      return;
    }
    removeReferencesToFields([itemId]);
    category.fields = category.fields.filter(
      (candidate) => candidate.id !== itemId,
    );
    markDirty();
    renderBuilder();
    return;
  }
  if (action === "move-field-up" || action === "move-field-down") {
    const category = categoryById(categoryId);
    const index =
      category?.fields.findIndex((field) => field.id === itemId) ?? -1;
    if (
      category &&
      moveArrayItem(category.fields, index, action.endsWith("up") ? -1 : 1)
    ) {
      markDirty();
      renderBuilderCategories();
    }
    return;
  }
  if (action === "edit-condition") {
    openConditionDialog(itemId);
    return;
  }
  if (action === "delete-condition") {
    deleteCondition(itemId);
    return;
  }
}

function fillMainFieldSelect(select, selectedValue = "", emptyLabel = "") {
  select.replaceChildren();
  if (emptyLabel) {
    const empty = document.createElement("option");
    empty.value = "";
    empty.textContent = emptyLabel;
    select.append(empty);
  }
  for (const { category, field } of allFields().filter(
    ({ category, field }) =>
      category.kind === "main" &&
      field.type !== "file" &&
      !isSystemField(field),
  )) {
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = `${category.label} ← ${field.label}`;
    select.append(option);
  }
  select.value = selectedValue;
}

function appendPlacementOption(parent, value, label) {
  const option = document.createElement("option");

  option.value = value;
  option.textContent = label;

  parent.append(option);
}

function fillCategoryPlacementSelect(current = null) {
  elements.categoryPlacement.replaceChildren();

  const editor = state.globalEditor;
  const globalRoot = editor?.kind === "category" && (!editor.packageMode || current?.id === editor.rootCategoryId);
  const roots = globalRoot
    ? Object.entries(state.globalDefinitions?.categories || {}).map(([id, item]) => ({id, label:item.definition?.label || "فئة عامة"}))
    : (state.draftSchema?.categories || []).filter((category) => !category.parent_category_id);
  const currentId = globalRoot ? editor.globalRef : current?.id;
  const categories = roots.filter((category) => category.id !== currentId);

  const quickGroup = document.createElement("optgroup");

  quickGroup.label = "موضع سريع";

  appendPlacementOption(quickGroup, "start", "في بداية الفئات الرئيسية");
  appendPlacementOption(quickGroup, "end", "في نهاية الفئات الرئيسية");

  elements.categoryPlacement.append(quickGroup);

  if (categories.length) {
    const beforeGroup = document.createElement("optgroup");

    beforeGroup.label = "قبل فئة";

    categories.forEach((category) => {
      appendPlacementOption(
        beforeGroup,
        `before:${category.id}`,
        `قبل: ${category.label}`,
      );
    });

    elements.categoryPlacement.append(beforeGroup);
  }

  const index = roots.findIndex(category => category.id === currentId);
  elements.categoryPlacement.value = index >= 0 && roots[index + 1] ? `before:${roots[index + 1].id}` : "end";
}

function fillCategoryParentSelect(category = null) {
  elements.categoryParent.replaceChildren();

  appendPlacementOption(elements.categoryParent, "", "بلا فئة أم");

  const excluded = category
    ? categoryDescendantIds(category.id, state.draftSchema)
    : new Set();
  if (category) {
    excluded.add(category.id);
  }

  for (const { category: candidate, depth } of orderedCategoryTree(
    state.draftSchema,
  )) {
    if (excluded.has(candidate.id)) {
      continue;
    }
    const indent = "— ".repeat(depth);
    appendPlacementOption(
      elements.categoryParent,
      candidate.id,
      `${indent}${candidate.label}`,
    );
  }

  elements.categoryParent.value = category?.parent_category_id || "";
  elements.categoryHasParent.value = category?.parent_category_id ? "yes" : "no";
  updateCategoryParentFieldEditor(category?.parent_field_id || "");
}

function updateCategoryParentFieldEditor(selectedFieldId = "") {
  const hasParent = elements.categoryHasParent.value === "yes";
  elements.categoryParentWrapper.hidden = !hasParent;
  elements.categoryPlacementWrapper.hidden = hasParent;
  elements.categoryKind.disabled = false;
  if (!hasParent) elements.categoryParent.value = "";
  const parent = categoryById(elements.categoryParent.value);
  const enabled = hasParent && Boolean(parent);
  elements.categoryParentFieldWrapper.hidden = !enabled;
  elements.categoryParentField.replaceChildren();
  if (!enabled) {
    return;
  }
  appendBlankOption(elements.categoryParentField, "في نهاية الفئة الأم");
  (parent.fields || []).forEach((field) => {
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = field.label;
    elements.categoryParentField.append(option);
  });
  elements.categoryParentField.value = selectedFieldId;
}

function categoryInsertionIndex(placement) {
  const categories = state.draftSchema.categories;

  if (placement === "start") {
    return 0;
  }

  if (!placement || placement === "end") {
    return categories.length;
  }

  const separator = placement.indexOf(":");

  if (separator < 0) {
    return categories.length;
  }

  const mode = placement.slice(0, separator);

  const categoryId = placement.slice(separator + 1);

  const referenceIndex = categories.findIndex(
    (category) => category.id === categoryId,
  );

  if (referenceIndex < 0) {
    return categories.length;
  }

  return mode === "before" ? referenceIndex : referenceIndex + 1;
}

function fillCategoryCardOptions(category = null) {
  const fields = state.categoryFieldsDraft || category?.fields || [];
  const selectedTitle = category?.card_title_field_id || elements.categoryCardTitleField.value || "";
  const selectedSortField = category?.card_sort?.field_id || elements.categoryCardSortField.value || "";
  elements.categoryCardTitleField.replaceChildren();
  appendBlankOption(elements.categoryCardTitleField, "بطاقة 1، 2…");
  elements.categoryCardSortField.replaceChildren();
  appendBlankOption(elements.categoryCardSortField, "اختر حقلًا");
  fields.filter((field) => field.type !== "file" && !isSystemField(field)).forEach((field) => {
    const titleOption = document.createElement("option");
    titleOption.value = field.id;
    titleOption.textContent = field.label;
    elements.categoryCardTitleField.append(titleOption);
    elements.categoryCardSortField.append(titleOption.cloneNode(true));
  });
  elements.categoryCardTitleField.value = selectedTitle;
  elements.categoryCardSortField.value = selectedSortField;
  elements.categoryCardNamePrefixWrapper.hidden = Boolean(elements.categoryCardTitleField.value);
  updateCategoryCardSortEditor();
}

function updateCategoryCardSortEditor() {
  const mode = elements.categoryCardSortMode.value;
  elements.categoryCardSortFieldWrapper.hidden = mode !== "field";
}

function renderCategoryImportFields() {
  elements.categoryImportFields.replaceChildren();
  const source = state.categoryImportSources?.get(elements.categoryImportSource.value);
  (source?.fields || []).forEach((field) => {
    const label = document.createElement("label");
    label.className = "check-field";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.dataset.categoryImportField = field.id;
    input.checked = true;
    const text = document.createElement("span");
    text.textContent = field.label;
    label.append(input, text);
    elements.categoryImportFields.append(label);
  });
}

function fillCategoryImportSources() {
  elements.categoryImportSource.replaceChildren();
  appendBlankOption(elements.categoryImportSource, "اختر فئة");
  state.categoryImportSources = new Map();
  state.draftSchema.categories.forEach((category) => {
    if (category.id === state.editingCategoryId) return;
    const option = document.createElement("option");
    option.value = `local:${category.id}`;
    option.textContent = category.label;
    state.categoryImportSources.set(option.value, category);
    elements.categoryImportSource.append(option);
  });
  const general = Object.entries(state.globalDefinitions?.categories || {});
  if (general.length) {
    const group = document.createElement("optgroup");
    group.label = "الفئات العامة";
    general.forEach(([globalRef, item]) => {
      const tree = Array.isArray(item.definition?.category_tree)
        ? item.definition.category_tree
        : [];
      const root = tree.find((node) => !node.parent_key) || tree[0];
      const source = {
        ...(deepClone(root?.definition || item.definition || {})),
        fields: deepClone(
          root?.fields?.map((entry) => ({
            ...(entry.definition || {}),
            id: entry.key,
            global_tree_ref: globalRef,
            global_tree_key: entry.key,
          })) || (item.definition?.fields || []).map((field, index) => ({
            ...field,
            id: `legacy-${index + 1}`,
            global_tree_ref: globalRef,
            global_tree_key: `legacy-${index + 1}`,
          })),
        ),
        global_ref: globalRef,
      };
      const key = `global:${globalRef}`;
      state.categoryImportSources.set(key, source);
      group.append(new Option(source.label || item.id, key));
    });
    elements.categoryImportSource.append(group);
  }
  renderCategoryImportFields();
}

function applyCategoryImportSelection() {
  const source = state.categoryImportSources?.get(elements.categoryImportSource.value);
  if (!source) {
    showToast("اختر الفئة المصدر أولًا.", "error");
    return;
  }
  const selected = new Set(
    [...elements.categoryImportFields.querySelectorAll("[data-category-import-field]:checked")]
      .map((input) => input.dataset.categoryImportField),
  );
  if (!selected.size) {
    showToast("اختر حقلًا واحدًا على الأقل.", "error");
    return;
  }
  const existingLabels = new Set(
    state.categoryFieldsDraft.map((field) => field.label.trim().toLocaleLowerCase()),
  );
  const candidates = source.fields.filter(
    (field) => selected.has(field.id) && !existingLabels.has(field.label.trim().toLocaleLowerCase()),
  );
  const fieldIdMap = new Map(
    candidates.map((field) => [field.id, randomDefinitionId("fld")]),
  );
  const imported = candidates.map((field) => {
    const copy = deepClone(field);
    copy.id = fieldIdMap.get(field.id);
    copy.global_ref = null;
    copy.global_tree_ref = null;
    copy.global_tree_key = null;
    copy.options = (copy.options || []).map((option) => ({
      ...option,
      id: randomDefinitionId("opt"),
    }));
    copy.option_filter = null;
    copy.auto_update = null;
    copy.related_person_source_field_id = null;
    copy.related_person_source_checkbox_id = null;
    delete copy.related_person_source_marker_id;
    if (copy.validation) {
      copy.validation.compare_field_id = null;
      copy.validation.compare_operator = null;
    }
    if (copy.file_naming?.parts) {
      copy.file_naming.parts = copy.file_naming.parts
        .filter((part) => fieldIdMap.has(part.field_id))
        .map((part) => ({
          field_id: fieldIdMap.get(part.field_id),
          prefix: part.prefix || "",
          suffix: part.suffix || "",
        }));
      if (copy.file_naming.mode === "template" && !copy.file_naming.parts.length) {
        copy.file_naming.mode = "original";
      }
    }
    return copy;
  });
  state.categoryFieldsDraft.push(...imported);
  if (!categoryById(state.editingCategoryId)) {
    elements.categoryLabel.value ||= `${source.label} — نسخة`;
    elements.categoryKind.value = source.kind;
    elements.categoryDescription.value ||= source.description || "";
    elements.categoryAddLabel.value ||= source.add_label || "";
    elements.categoryAutoStart.checked = Boolean(source.auto_start);
    elements.categoryRelatedPerson.checked = Boolean(source.related_person_enabled);
    fillCategoryCardOptions();
    elements.categoryCardTitleField.value = fieldIdMap.get(source.card_title_field_id) || "";
    elements.categoryCardNamePrefix.value ||= source.card_name_prefix || "";
    elements.categoryCardSortMode.value = ["title", "field"].includes(source.card_sort?.mode) ? source.card_sort.mode : "manual";
    elements.categoryCardSortField.value = fieldIdMap.get(source.card_sort?.field_id) || "";
    elements.categoryCardSortDirection.value = source.card_sort?.direction || "asc";
    updateCategoryDialogType();
  }
  fillCategoryCardOptions();
  showToast(`تمت إضافة ${imported.length} حقول من الفئة المصدر.`);
}

function openCategoryDialog(categoryId = null, detachGlobalOnSave = false) {
  if (elements.globalCategoryConnectChoice) elements.globalCategoryConnectChoice.hidden = true;
  const category = categoryId ? categoryById(categoryId) : null;
  state.editingCategoryDetachGlobal = Boolean(
    category?.global_ref && detachGlobalOnSave,
  );
  const creatingCategory = !category;
  elements.categoryPlacementWrapper.hidden = false;
  fillCategoryPlacementSelect(category);
  state.editingCategoryId = category?.id || randomDefinitionId("cat");
  state.categoryDialogCommitted = false;
  state.categoryConditionsSnapshot = deepClone(state.draftSchema.conditions);
  state.categoryDirtyBeforeOpen = state.dirty;
  elements.categoryDialogTitle.textContent = category
    ? "تعديل فئة"
    : "إضافة فئة";
  elements.categoryLabel.value = category?.label || "";
  elements.categoryKind.value = category?.kind || "main";
  fillCategoryParentSelect(category);
  elements.categoryDescription.value = category?.description || "";
  elements.categoryAddLabel.value = category?.add_label || "";
  elements.categoryAutoStart.checked = Boolean(category?.auto_start);
  elements.categoryRelatedPerson.checked = Boolean(
    category?.related_person_enabled,
  );
  state.categoryFieldsDraft = deepClone(category?.fields || []);
  elements.categoryCardSortMode.value = category?.card_sort?.mode || "manual";
  elements.categoryCardSortDirection.value = category?.card_sort?.direction || "asc";
  elements.categoryCardNamePrefix.value = category?.card_name_prefix || "";
  fillCategoryCardOptions(category);
  fillCategoryImportSources();
  fillMainFieldSelect(
    elements.categoryAnchor,
    category?.anchor_field_id || "",
    "في نهاية النموذج",
  );
  updateCategoryDialogType();
  renderCategoryConditionEditor();
  elements.categoryDialog.showModal();
  elements.categoryLabel.focus();
}

function updateCategoryDialogType() {
  const repeatable = elements.categoryKind.value === "repeatable";
  elements.categoryRepeatableOptions.hidden = !repeatable;
  updateCategoryParentFieldEditor(elements.categoryParentField.value);
  elements.categoryCardNamePrefixWrapper.hidden = Boolean(elements.categoryCardTitleField.value);
}

function saveCategoryFromDialog() {
  const label = elements.categoryLabel.value.trim();
  if (!label) {
    showToast("اسم الفئة مطلوب.", "error");
    elements.categoryLabel.focus();
    return;
  }
  const duplicate = state.draftSchema.categories.some(
    (category) =>
      category.id !== state.editingCategoryId &&
      category.label.trim().toLocaleLowerCase() === label.toLocaleLowerCase(),
  );
  if (duplicate) {
    showToast("اسم الفئة مستخدم مسبقًا.", "error");
    return;
  }

  const existing = state.editingCategoryId
    ? categoryById(state.editingCategoryId)
    : null;
  const kind = elements.categoryKind.value;
  // General editors use a temporary schema containing new placeholder categories.
  // Only a persisted category in the active schema can have existing records.
  const persisted = !state.globalEditor && state.editingCategoryId
    ? categoryById(state.editingCategoryId, state.schema)
    : null;
  if (
    persisted &&
    persisted.kind !== kind &&
    (state.schema?.stats?.record_count || 0) > 0
  ) {
    showToast("لا يمكن تغيير نوع فئة بعد وجود سجلات.", "error");
    return;
  }
  if (elements.categoryHasParent.value === "yes" && !elements.categoryParent.value) {
    showToast("اختر الفئة الأم.", "error");
    elements.categoryParent.focus();
    return;
  }
  const category = existing || {
    id: state.editingCategoryId,
    fields: [],
  };
  if (existing && state.editingCategoryDetachGlobal) {
    category.global_ref = null;
  }
  category.label = label;
  category.description = elements.categoryDescription.value.trim();
  category.kind = kind;
  category.parent_category_id = elements.categoryHasParent.value === "yes"
    ? elements.categoryParent.value || null
    : null;
  category.parent_field_id = category.parent_category_id
    ? elements.categoryParentField.value || null
    : null;
  category.add_label =
    elements.categoryAddLabel.value.trim() || `إضافة ${label}`;
  category.auto_start =
    kind === "repeatable" && elements.categoryAutoStart.checked;
  category.related_person_enabled =
    kind === "repeatable" && elements.categoryRelatedPerson.checked;
  category.anchor_field_id = null;
  category.fields = deepClone(state.categoryFieldsDraft || category.fields || []);
  category.card_title_field_id =
    kind === "repeatable" ? elements.categoryCardTitleField.value || null : null;
  category.card_name_prefix =
    kind === "repeatable" && !category.card_title_field_id
      ? elements.categoryCardNamePrefix.value.trim().slice(0, 80)
      : "";
  category.card_sort = kind === "repeatable"
    ? {
        mode: elements.categoryCardSortMode.value,
        field_id: elements.categoryCardSortField.value || null,
        direction: elements.categoryCardSortDirection.value,
      }
    : { mode: "manual", direction: "asc" };
  if (!category.related_person_enabled) {
    const modeSourceId = relatedPersonModeSourceId(category.id);
    state.draftSchema.conditions = state.draftSchema.conditions.filter(
      (condition) => condition.source_field_id !== modeSourceId,
    );
    category.fields.forEach((field) => {
      delete field.related_person_source_field_id;
    });
  }
  const creatingCategory = !existing;

  if (creatingCategory || !category.parent_category_id) {
    if (existing) state.draftSchema.categories.splice(state.draftSchema.categories.indexOf(existing), 1);
    const insertionIndex = categoryInsertionIndex(
      elements.categoryPlacement.value,
    );

    state.draftSchema.categories.splice(insertionIndex, 0, category);
  }
  state.categoryDialogCommitted = true;

  if (state.globalEditor?.kind === "category") {
    void commitGlobalDefinitionFromEditor("category", category);
    elements.categoryDialog.close();
    return;
  }

  markDirty();
  renderBuilder();
  elements.categoryDialog.close();

  if (creatingCategory) {
    window.setTimeout(() => {
      scrollToBuilderCategory(category.id);
    }, 0);
  }
}

function availableFileNamingFields(categoryId) {
  return allFields().filter(
    ({ category, field }) =>
      field.type !== "file" &&
      !isSystemField(field) &&
      (category.kind === "main" || category.id === categoryId),
  ).sort((first, second) => {
    const firstLocal = first.category.id === categoryId ? 0 : 1;
    const secondLocal = second.category.id === categoryId ? 0 : 1;
    return firstLocal - secondLocal;
  });
}

function fillFileNamingFieldSelect() {
  elements.filePartField.replaceChildren();
  for (const { category, field } of availableFileNamingFields(
    state.editingFieldCategoryId,
  )) {
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = `${category.label} ← ${field.label}`;
    elements.filePartField.append(option);
  }
}

function reconcileFieldOptions() {
  const labels = elements.fieldOptions.value
    .split(/\r?\n/)
    .map((value) => value.trim())
    .filter((value, index, array) => value && array.indexOf(value) === index);
  const previous = state.fieldOptionsDraft || [];
  const used = new Set();
  state.fieldOptionsDraft = labels.map((label, index) => {
    let option = previous.find(
      (candidate) => candidate.label === label && !used.has(candidate.id),
    );
    if (!option && previous[index] && !used.has(previous[index].id)) {
      option = previous[index];
    }
    const result = option
      ? { ...option, label, active: option.active !== false }
      : { id: randomDefinitionId("opt"), label, active: true };
    used.add(result.id);
    return result;
  });
  return state.fieldOptionsDraft;
}

function compatibleOptionFilterSources(categoryId, fieldId) {
  return allFields().filter(
    ({ category, field }) =>
      field.id !== fieldId &&
      ["select", "yes_no", "checkbox"].includes(field.type) &&
      (category.kind === "main" || category.id === categoryId),
  );
}

function fillOptionFilterSource() {
  const selected = state.optionFilterDraft?.source_field_id || "";
  elements.optionFilterSource.replaceChildren();
  const empty = document.createElement("option");
  empty.value = "";
  empty.textContent = "بدون تصفية";
  elements.optionFilterSource.append(empty);
  for (const { category, field } of compatibleOptionFilterSources(
    state.editingFieldCategoryId,
    state.editingFieldId,
  )) {
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = `${category.label} ← ${field.label}`;
    elements.optionFilterSource.append(option);
  }
  elements.optionFilterSource.value = selected;
  if (elements.optionFilterSource.value !== selected) {
    elements.optionFilterSource.value = "";
    state.optionFilterDraft = null;
  }
}

function parseOptionLines(value) {
  const result = [];
  const seen = new Set();

  String(value || "")
    .split(/\r?\n/)
    .map((label) => label.trim())
    .filter(Boolean)
    .forEach((label) => {
      const key = label.toLocaleLowerCase();

      if (!seen.has(key)) {
        seen.add(key);
        result.push(label);
      }
    });

  return result;
}
function syncTargetOptionsFromFilterText() {
  const labels = [];
  const seen = new Set();

  elements.optionFilterMatrix
    .querySelectorAll("textarea[data-source-token]")
    .forEach((textarea) => {
      parseOptionLines(textarea.value).forEach((label) => {
        const key = label.toLocaleLowerCase();

        if (!seen.has(key)) {
          seen.add(key);
          labels.push(label);
        }
      });
    });

  const previous = state.fieldOptionsDraft || [];
  const used = new Set();

  state.fieldOptionsDraft = labels.map((label, index) => {
    const key = label.toLocaleLowerCase();

    let option = previous.find(
      (candidate) =>
        candidate.label.toLocaleLowerCase() === key && !used.has(candidate.id),
    );

    if (!option && previous[index] && !used.has(previous[index].id)) {
      option = previous[index];
    }

    const result = option
      ? {
          ...option,
          label,
          active: option.active !== false,
        }
      : {
          id: randomDefinitionId("opt"),
          label,
          active: true,
        };

    used.add(result.id);
    return result;
  });

  elements.fieldOptions.value = state.fieldOptionsDraft
    .map((option) => option.label)
    .join("\n");
}

function renderOptionFilterMatrix() {
  elements.optionFilterMatrix.replaceChildren();

  const sourceId = elements.optionFilterSource.value;

  if (!sourceId) {
    elements.optionFilterMatrix.hidden = true;
    return;
  }

  elements.optionFilterMatrix.hidden = false;

  const source = fieldById(sourceId);

  if (!source) {
    elements.optionFilterMatrix.textContent = "الحقل المتحكم غير موجود.";
    return;
  }

  const sourceTokens = optionSourceTokens(source);

  if (!sourceTokens.length) {
    elements.optionFilterMatrix.textContent = "أضف خيارات للحقل المتحكم أولًا.";
    return;
  }

  const mappings = state.optionFilterDraft?.mappings || {};

  const targetById = new Map(
    (state.fieldOptionsDraft || []).map((option) => [option.id, option]),
  );

  const note = document.createElement("p");
  note.className = "dialog-note";
  note.textContent =
    "اكتب خيارات الحقل الحالي لكل قيمة من الحقل المتحكم، خيارًا واحدًا في كل سطر.";

  elements.optionFilterMatrix.append(note);

  for (const sourceOption of sourceTokens) {
    const row = document.createElement("div");
    row.className = "option-filter-row";

    const title = document.createElement("strong");
    title.textContent = sourceOption.label;

    const textarea = document.createElement("textarea");
    textarea.className = "control option-filter-textarea";

    textarea.rows = 4;
    textarea.dataset.sourceToken = sourceOption.id;
    textarea.placeholder = "اكتب خيارًا واحدًا في كل سطر";

    textarea.value = (mappings[sourceOption.id] || [])
      .map((optionId) => targetById.get(optionId)?.label)
      .filter(Boolean)
      .join("\n");

    textarea.addEventListener("input", syncTargetOptionsFromFilterText);

    row.append(title, textarea);
    elements.optionFilterMatrix.append(row);
  }
}
function collectOptionFilter() {
  const sourceId = elements.optionFilterSource.value;

  if (!sourceId) {
    return null;
  }

  syncTargetOptionsFromFilterText();

  const optionByLabel = new Map(
    state.fieldOptionsDraft.map((option) => [
      option.label.toLocaleLowerCase(),
      option,
    ]),
  );

  const mappings = {};

  elements.optionFilterMatrix
    .querySelectorAll("textarea[data-source-token]")
    .forEach((textarea) => {
      const token = textarea.dataset.sourceToken;

      mappings[token] = parseOptionLines(textarea.value)
        .map((label) => optionByLabel.get(label.toLocaleLowerCase())?.id)
        .filter(Boolean);
    });

  return {
    source_field_id: sourceId,
    mappings,
    unmatched: "none",
  };
}

function fillDateComparisonFields(field) {
  const selected = field?.validation?.compare_field_id || "";
  elements.validationCompareField.replaceChildren();
  const empty = document.createElement("option");
  empty.value = "";
  empty.textContent = "بدون مقارنة";
  elements.validationCompareField.append(empty);
  const category = categoryById(state.editingFieldCategoryId);
  for (const {
    category: sourceCategory,
    field: candidate,
  } of allFields().filter(
    ({ category: sourceCategory, field: candidate }) =>
      candidate.id !== state.editingFieldId &&
      candidate.type === elements.fieldType.value &&
      (sourceCategory.kind === "main" || sourceCategory.id === category?.id),
  )) {
    const option = document.createElement("option");
    option.value = candidate.id;
    option.textContent = `${sourceCategory.label} ← ${candidate.label}`;
    elements.validationCompareField.append(option);
  }
  elements.validationCompareField.value = selected;
}

function loadValidation(field) {
  const validation = field?.validation || {};
  elements.validationMinLength.value = validation.min_length ?? "";
  elements.validationMaxLength.value = validation.max_length ?? "";
  elements.validationPattern.value = validation.pattern || "";
  elements.validationMinNumber.value = validation.min ?? "";
  elements.validationMaxNumber.value = validation.max ?? "";
  elements.validationIntegerOnly.checked = Boolean(validation.integer_only);
  elements.validationMinDate.value = validation.min_date || "";
  elements.validationMaxDate.value = validation.max_date || "";
  elements.validationCompareOperator.value =
    validation.compare_operator || "after";
  fillDateComparisonFields(field);
}

function selectedNumberSpecialCharacters() {
  return [
    ...elements.numberBehaviorEditor.querySelectorAll(
      "[data-number-special]:checked",
    ),
  ].map((control) => control.dataset.numberSpecial).join("");
}

function loadNumberBehavior(field) {
  const behavior = field?.number_behavior || {};
  elements.numberFormatThousands.checked = Boolean(
    behavior.format_thousands,
  );
  elements.numberPreserveLeadingZeros.checked = Boolean(
    behavior.preserve_leading_zeros,
  );
  const allowed = new Set(behavior.allowed_special_characters || "");
  elements.numberBehaviorEditor
    .querySelectorAll("[data-number-special]")
    .forEach((control) => {
      control.checked = allowed.has(control.dataset.numberSpecial);
    });
  updateNumberStorageNote();
}

function updateNumberStorageNote() {
  const exactText =
    elements.numberPreserveLeadingZeros.checked ||
    selectedNumberSpecialCharacters().length > 0;
  elements.numberStorageNote.textContent = exactText
    ? "سيُحفظ هذا الحقل كنص في Excel لحماية الأصفار والرموز. لن تُطبق عليه العمليات الحسابية."
    : "سيُحفظ هذا الحقل كرقم حقيقي في Excel ويمكن التحقق من حدوده.";
  elements.numberValidationFields.hidden =
    elements.fieldType.value !== "number" || exactText;
}

function collectNumberBehavior(type) {
  if (type !== "number") {
    return null;
  }
  const allowed = selectedNumberSpecialCharacters();
  const preserve = elements.numberPreserveLeadingZeros.checked;
  return {
    storage_mode: preserve || allowed ? "text" : "numeric",
    format_thousands: elements.numberFormatThousands.checked,
    preserve_leading_zeros: preserve,
    allowed_special_characters: allowed,
  };
}

function optionalNumber(input) {
  return input.value.trim() === "" ? null : Number(input.value);
}

function collectValidation(type) {
  if (["text", "textarea", "user_name"].includes(type)) {
    return {
      min_length: optionalNumber(elements.validationMinLength),
      max_length: optionalNumber(elements.validationMaxLength),
      pattern: elements.validationPattern.value.trim(),
    };
  }
  if (type === "number") {
    if (
      elements.numberPreserveLeadingZeros.checked ||
      selectedNumberSpecialCharacters().length
    ) {
      return {};
    }
    return {
      min: optionalNumber(elements.validationMinNumber),
      max: optionalNumber(elements.validationMaxNumber),
      integer_only: elements.validationIntegerOnly.checked,
    };
  }
  if (type.startsWith("date_")) {
    return {
      min_date: elements.validationMinDate.value.trim(),
      max_date: elements.validationMaxDate.value.trim(),
      compare_field_id: elements.validationCompareField.value || null,
      compare_operator: elements.validationCompareField.value
        ? elements.validationCompareOperator.value
        : null,
    };
  }
  return {};
}

function fillRelatedPersonSourceFields(selectedId = "") {
  const type = selectedBuilderFieldType();
  const selectedCheckbox = elements.relatedPersonSourceCheckbox.value;
  const selectedCheckboxCategory = selectedCheckbox ? fieldCategory(selectedCheckbox) : null;
  elements.relatedPersonSourceField.replaceChildren();
  appendBlankOption(
    elements.relatedPersonSourceField,
    "لا تنسخ قيمة تلقائيًا",
  );
  const candidates = allFields().filter(
    ({ category: candidateCategory, field: candidateField }) =>
      candidateField.type !== "file" &&
      !isSystemField(candidateField) &&
      (selectedCheckboxCategory
        ? candidateCategory.id === selectedCheckboxCategory.id
        : candidateCategory.kind === "main"),
  );
  const groups = new Map();
  candidates.forEach(({ category, field }) => {
    if (!groups.has(category.id)) {
      const group = document.createElement("optgroup");
      group.label = category.label;
      groups.set(category.id, group);
      elements.relatedPersonSourceField.append(group);
    }
    const option = document.createElement("option");
    option.value = field.id;
    option.disabled = field.type !== type;
    option.textContent = field.type === type
      ? field.label
      : `${field.label} — نوع غير متوافق`;
    groups.get(category.id).append(option);
  });
  elements.relatedPersonSourceField.value = selectedId;
}

function fillRelatedPersonSourceCheckboxes(selected = "") {
  elements.relatedPersonSourceCheckboxWrapper.hidden = false;
  elements.relatedPersonSourceCheckbox.replaceChildren();
  appendBlankOption(elements.relatedPersonSourceCheckbox, "الحقول في الفئات الرئيسية");
  const groups = new Map();
  allFields().filter(({ category, field }) => (
    category.kind === "repeatable" &&
    field.type === "checkbox" &&
    field.unique_checked_across_cards === true
  )).forEach(({ category, field }) => {
    if (!groups.has(category.id)) {
      const group = document.createElement("optgroup");
      group.label = category.label;
      groups.set(category.id, group);
      elements.relatedPersonSourceCheckbox.append(group);
    }
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = `البطاقة التي فيها «${field.label}» محدد`;
    groups.get(category.id).append(option);
  });
  elements.relatedPersonSourceCheckbox.value = selected;
}

function fillAutoUpdateEditor(rule = null) {
  elements.fieldAutoSource.replaceChildren();
  appendBlankOption(elements.fieldAutoSource, "بدون تحديث تلقائي");
  allFields().filter(({ category, field }) =>
    field.id !== state.editingFieldId &&
    field.type !== "file" &&
    !isSystemField(field)
  ).forEach(({ category, field }) => {
    const option = document.createElement("option");
    option.value = field.id;
    option.textContent = `${category.label} ← ${field.label}`;
    elements.fieldAutoSource.append(option);
  });
  elements.fieldAutoSource.value = rule?.source_field_id || "";
  fillAutoUpdateOperators(rule?.operator || "");
  elements.fieldAutoValue.value = rule?.value || "";
  elements.fieldAutoAction.value = rule?.action || "fixed";
  elements.fieldAutoResult.value = rule?.result_value || "";
  updateAutoUpdateEditor();
}

function fillAutoUpdateOperators(selected = "") {
  const source = fieldById(elements.fieldAutoSource.value);
  const operators = CONDITION_OPERATORS_BY_TYPE[source?.type] || [];
  elements.fieldAutoOperator.replaceChildren();
  operators.forEach((operator) => {
    const option = document.createElement("option");
    option.value = operator;
    option.textContent = OPERATOR_LABELS[operator] || operator;
    elements.fieldAutoOperator.append(option);
  });
  if (operators.includes(selected)) elements.fieldAutoOperator.value = selected;
}

function updateAutoUpdateEditor() {
  const enabled = Boolean(elements.fieldAutoSource.value);
  elements.fieldAutoOperator.disabled = !enabled;
  const noValue = ["empty", "not_empty"].includes(elements.fieldAutoOperator.value);
  elements.fieldAutoValueWrapper.hidden = !enabled || noValue;
  elements.fieldAutoAction.disabled = !enabled;
  elements.fieldAutoResultWrapper.hidden = !enabled || elements.fieldAutoAction.value !== "fixed";
}

function collectAutoUpdateRule(type) {
  if (!elements.fieldAutoSource.value || SYSTEM_FIELD_TYPES.has(type)) return null;
  return {
    source_field_id: elements.fieldAutoSource.value,
    operator: elements.fieldAutoOperator.value,
    value: ["empty", "not_empty"].includes(elements.fieldAutoOperator.value)
      ? ""
      : elements.fieldAutoValue.value,
    action: elements.fieldAutoAction.value,
    result_value: elements.fieldAutoResult.value,
  };
}

function fillFieldPlacementSelect(select, fields, currentId = null, selected = null) {
  select.replaceChildren(new Option("في بداية الفئة", "start"), new Option("في نهاية الفئة", "end"));
  fields.filter(field => field.id !== currentId).forEach((field, index) => {
    select.append(new Option(field.label || `مساحة فارغة ${index + 1}`, field.id));
  });
  const index = fields.findIndex(field => field.id === currentId);
  select.value = selected ?? (index >= 0 ? (index ? fields[index - 1].id : "start") : "end");
  if (!select.value) select.value = "end";
}

function refreshNewFieldPlacement() {
  const selected = elements.newFieldCategory.value;
  let fields = [];
  if (state.newFieldCategoryContext === "global") {
    if (selected === "__standalone__") {
      fields = Object.entries(state.globalDefinitions?.fields || {}).map(([id, item]) => ({...item.definition, id}));
    } else {
      const [ref, key] = selected.split("::");
      const node = globalCategoryTree(state.globalDefinitions?.categories?.[ref]?.definition || {}).find(node => node.key === key);
      fields = (node?.fields || []).map(field => ({...field.definition, id: field.key}));
    }
  } else fields = categoryById(selected)?.fields || [];
  fillFieldPlacementSelect(elements.newFieldAfter, fields);
}

function openNewFieldCategoryDialog(scope = state.builderScope) {
  elements.newFieldCategory.replaceChildren();
  state.newFieldCategoryContext = scope === "global" ? "global" : "schema";
  if (state.newFieldCategoryContext === "global") {
    elements.newFieldCategory.append(new Option("حقل عام منفصل", "__standalone__"));
    Object.entries(state.globalDefinitions?.categories || {}).forEach(([globalRef, item]) => {
      const definition = item?.definition || {};
      globalCategoryTree(definition).forEach((node) => {
        const rootLabel = definition.label || "فئة عامة";
        const nodeLabel = node.definition?.label || rootLabel;
        const label = node.parent_key ? `${rootLabel} — ${nodeLabel}` : rootLabel;
        elements.newFieldCategory.append(new Option(label, `${globalRef}::${node.key}`));
      });
    });
    refreshNewFieldPlacement();
    elements.fieldCategoryDialog.showModal();
    elements.newFieldCategory.focus();
    return;
  }
  (state.draftSchema?.categories || []).forEach((category) => {
    elements.newFieldCategory.append(new Option(category.label, category.id));
  });
  if (!elements.newFieldCategory.options.length) {
    showToast("أضف فئة أولًا ثم أضف الحقول إليها.", "error");
    return;
  }
  refreshNewFieldPlacement();
  elements.fieldCategoryDialog.showModal();
  elements.newFieldCategory.focus();
}

function confirmNewFieldCategory() {
  const categoryId = elements.newFieldCategory.value;
  if (state.newFieldCategoryContext === "global") {
    elements.fieldCategoryDialog.close();
    if (categoryId === "__standalone__") {
      openGlobalDefinitionEditor("field", "", {placement:elements.newFieldAfter.value});
      return;
    }
    const [globalRef, nodeKey] = categoryId.split("::");
    if (globalRef && nodeKey) {
      openGlobalCategoryPackageEditor("field", globalRef, { nodeKey, newField: true, afterFieldKey: elements.newFieldAfter.value });
    }
    return;
  }
  if (!categoryById(categoryId)) return;
  elements.fieldCategoryDialog.close();
  openFieldDialog(categoryId, null, false, elements.newFieldAfter.value);
}

function fieldDialogTypeState(field = null) {
  const concrete = field?.type || "text";
  if (["text", "textarea"].includes(concrete)) {
    return { ui: "text", textMode: concrete === "textarea" ? "long" : "short" };
  }
  if (["select", "yes_no"].includes(concrete)) {
    return { ui: "select", listMode: concrete === "yes_no" ? "yes_no" : "custom" };
  }
  if (["date_gregorian", "date_hijri", "date_persian", "system_created_at", "system_updated_at"].includes(concrete)) {
    let dateMode = {
      date_gregorian: "manual_gregorian",
      date_hijri: "manual_hijri",
      date_persian: "manual_persian",
      system_created_at: "automatic_created",
      system_updated_at: "automatic_saved",
    }[concrete];
    if (concrete === "date_gregorian" && field?.date_value_mode === "on_checkbox") dateMode = "automatic_checkbox";
    return { ui: "date", dateMode };
  }
  return { ui: concrete };
}

function selectedBuilderFieldType() {
  const ui = elements.fieldType.value;
  if (ui === "text") return elements.fieldTextMode.value === "long" ? "textarea" : "text";
  if (ui === "select") return elements.fieldListMode.value === "yes_no" ? "yes_no" : "select";
  if (ui === "date") {
    return {
      manual_gregorian: "date_gregorian",
      manual_hijri: "date_hijri",
      manual_persian: "date_persian",
      automatic_created: "system_created_at",
      automatic_saved: "system_updated_at",
      automatic_checkbox: "date_gregorian",
    }[elements.fieldDateMode.value] || "date_gregorian";
  }
  return ui;
}

function fillMainCheckboxSelect(select, selected = "") {
  select.replaceChildren(new Option("اختر مربع اختيار", ""));
  allFields().filter(({ category, field }) => category.kind === "main" && field.type === "checkbox").forEach(({ category, field }) => {
    select.append(new Option(`${category.label} ← ${field.label}`, field.id));
  });
  select.value = selected;
}

function openFieldDialog(categoryId, fieldId = null, detachGlobalOnSave = false, placement = null) {
  if (elements.globalFieldConnectChoice) elements.globalFieldConnectChoice.hidden = true;
  state.editingFieldCategoryId = categoryId;

  const category = categoryById(categoryId);
  const field = fieldId ? fieldById(fieldId) : null;
  state.editingFieldDetachGlobal = Boolean(field?.global_ref && detachGlobalOnSave);

  state.editingFieldId = field?.id || randomDefinitionId("fld");

  state.fieldDialogCommitted = false;
  state.fieldConditionsSnapshot = deepClone(state.draftSchema.conditions);
  state.fieldDirtyBeforeOpen = state.dirty;
  if (!category) {
    return;
  }
  elements.fieldDialogTitle.textContent = field
    ? `تعديل حقل — ${category.label}`
    : `إضافة حقل — ${category.label}`;
  elements.fieldCategoryName.replaceChildren(...state.draftSchema.categories.map(item => new Option(item.label, item.id)));
  elements.fieldCategoryName.value = category.id;
  elements.fieldCategoryName.disabled = Boolean(state.globalEditor && !state.globalEditor.packageMode);
  elements.fieldCategoryName.onchange = () => {
    const target = categoryById(elements.fieldCategoryName.value);
    if (!target) return;
    const original = fieldId ? fieldCategory(fieldId) : null;
    const storedOriginal = fieldId ? fieldCategory(fieldId, state.schema) : null;
    const protectedMove = !state.globalEditor && storedOriginal && original?.id !== target.id &&
      (state.schema?.stats?.record_count || 0) > 0 && (storedOriginal.kind !== 'main' || target.kind !== 'main');
    if (protectedMove) {
      elements.fieldCategoryName.value = state.editingFieldCategoryId;
      showToast('نقل الحقول بين البطاقات أو بينها وبين الفئات الرئيسية بعد وجود سجلات يحتاج إلى تحديد كيفية توزيع القيم. يمكنك نقل الحقل بين الفئات الرئيسية مع الحفاظ على قيمه.', 'error');
      return;
    }
    state.editingFieldCategoryId = target.id;
    fillFieldPlacementSelect(elements.fieldAfter, target.fields || [], fieldId, original?.id === target.id ? null : 'end');
    elements.fieldDialogTitle.textContent = `${field ? 'تعديل حقل' : 'إضافة حقل'} — ${target.label}`;
    updateFieldDialogType();
  };
  fillFieldPlacementSelect(elements.fieldAfter, category.fields || [], field?.id, placement);
  elements.fieldStartNewLine.checked = Boolean(field?.start_new_line);
  elements.fieldCheckboxTrueLabel.value = field?.checkbox_true_label || "";
  elements.fieldCheckboxFalseLabel.value = field?.checkbox_false_label || "";
  elements.fieldLabel.value = field?.label || "";
  elements.fieldType.querySelector("[data-legacy-field-type]")?.remove();
  if (field?.type === "checkbox_group") {
    const legacy = new Option("مجموعة مربعات اختيار — نوع قديم", "checkbox_group");
    legacy.hidden = true;
    legacy.dataset.legacyFieldType = "";
    elements.fieldType.append(legacy);
  }
  const typeState = fieldDialogTypeState(field);
  elements.fieldType.value = typeState.ui;
  elements.fieldTextMode.value = typeState.textMode || "short";
  elements.fieldListMode.value = typeState.listMode || "custom";
  elements.fieldDateMode.value = typeState.dateMode || "manual_gregorian";
  fillMainCheckboxSelect(elements.fieldDateTrigger, field?.date_trigger_field_id || "");
  elements.fieldPlaceholder.value = field?.placeholder || "";
  elements.fieldWidth.value = ({ normal: "1", wide: "4", long: "4" }[field?.width] || field?.width || "1");
  state.fieldOptionsDraft = deepClone(field?.options || []);
  elements.fieldOptions.value = state.fieldOptionsDraft
    .map((option) => option.label)
    .join("\n");
  elements.fieldRequired.checked = Boolean(field?.required);
  elements.fieldUnique.checked = Boolean(field?.unique);
  elements.fieldSearchable.checked = Boolean(field?.searchable);
  elements.fieldSearchMatch.value = field?.search_match || "contains";
  elements.fieldShowResult.checked = Boolean(field?.show_in_results);
  elements.fieldResultTitle.checked = Boolean(field?.result_title);
  elements.fieldUserEditable.checked = field?.user_editable !== false;
  elements.fieldUserValueMode.value = field?.user_value_mode || "created_by";
  fillMainCheckboxSelect(elements.fieldUserTrigger, field?.user_trigger_field_id || "");
  elements.fieldUniqueCardCheckbox.checked = Boolean(field?.unique_checked_across_cards);
  fillRelatedPersonSourceCheckboxes(field?.related_person_source_checkbox_id || field?.related_person_source_marker_id || "");
  fillRelatedPersonSourceFields(field?.related_person_source_field_id || "");
  fillAutoUpdateEditor(field?.auto_update || null);
  elements.fileNamingMode.value = field?.file_naming?.mode || "original";
  elements.fileProfileImage.checked = ["profile", "card"].includes(field?.image_display);
  state.filePartsDraft = deepClone(field?.file_naming?.parts || []);
  state.optionFilterDraft = deepClone(field?.option_filter || null);
  fillFileNamingFieldSelect();
  fillOptionFilterSource();
  loadValidation(field);
  loadNumberBehavior(field);
  updateFieldDialogType();
  renderOptionFilterMatrix();
  renderFileParts();
  renderFieldConditionEditor();
  renderFieldConfigurationSources();
  elements.fieldDialog.showModal();
  elements.fieldLabel.focus();
}

function updateFieldDialogType() {
  const uiType = elements.fieldType.value;
  const type = selectedBuilderFieldType();
  const isFile = type === "file";
  const spacer = type === 'spacer';
  elements.fieldCheckboxMeanings.hidden = type !== 'checkbox';
  const systemField = SYSTEM_FIELD_TYPES.has(type) || spacer;
  elements.fieldLabel.closest('.field').hidden = spacer;
  const hasOptions = type === "select";
  const searchable = !isFile && !spacer;
  const textType = ["text", "textarea", "user_name"].includes(type);
  const numberType = type === "number";
  const dateType = type.startsWith("date_");
  elements.fieldTextModeWrapper.hidden = uiType !== "text";
  elements.fieldListModeWrapper.hidden = uiType !== "select";
  elements.fieldDateModeWrapper.hidden = uiType !== "date";
  elements.fieldDateTriggerWrapper.hidden = uiType !== "date" || elements.fieldDateMode.value !== "automatic_checkbox";
  elements.fieldUserTriggerWrapper.hidden = type !== "user_name" || elements.fieldUserValueMode.value !== "current_on_checkbox";
  const repeatableCheckbox = type === "checkbox" && categoryById(state.editingFieldCategoryId)?.kind === "repeatable";
  elements.fieldUniqueCardCheckboxWrapper.hidden = !repeatableCheckbox;
  const relatedPersonEligible = Boolean(
      categoryById(state.editingFieldCategoryId)?.kind === "repeatable" &&
      categoryById(state.editingFieldCategoryId)?.related_person_enabled &&
      !isFile &&
      !systemField,
  );
  const hasOptionFilterSource = Boolean(elements.optionFilterSource.value);
  elements.fieldOptionsWrapper.hidden = !hasOptions || hasOptionFilterSource;
  elements.optionFilterEditor.hidden = !hasOptions;
  elements.fieldPlaceholder.closest(".field").hidden = systemField;
  elements.fieldRequired.closest(".check-field").hidden = systemField;
  if (type === "user_name" && ["current_on_save", "current_on_checkbox"].includes(elements.fieldUserValueMode.value)) {
    elements.fieldRequired.checked = false;
    elements.fieldRequired.closest(".check-field").hidden = true;
  }
  elements.fieldSearchableWrapper.hidden = isFile || spacer;
  elements.fieldUniqueWrapper.hidden =
    isFile || type === "checkbox" || systemField;
  elements.fieldSearchMatchWrapper.hidden =
    !searchable || !elements.fieldSearchable.checked;
  elements.fieldResultWrapper.hidden = isFile || spacer;
  elements.fieldTitleWrapper.hidden =
    isFile ||
    systemField ||
    categoryById(state.editingFieldCategoryId)?.kind !== "main" ||
    !elements.fieldShowResult.checked;
  elements.relatedPersonFieldEditor.hidden = !relatedPersonEligible;
  if (relatedPersonEligible) {
    const selectedSource = elements.relatedPersonSourceField.value;
    const selectedCheckbox = elements.relatedPersonSourceCheckbox.value;
    fillRelatedPersonSourceCheckboxes(selectedCheckbox);
    fillRelatedPersonSourceFields(selectedSource);
  } else {
    elements.relatedPersonSourceField.value = "";
  }
  elements.fileNamingEditor.hidden = !isFile;
  const profileImageEligible = isFile;
  elements.fileProfileImageWrapper.hidden = !profileImageEligible;
  if (!profileImageEligible) {
    elements.fileProfileImage.checked = false;
  }
  if (isFile) {
    const repeated = categoryById(state.editingFieldCategoryId)?.kind === "repeatable";
    elements.fileProfileImageWrapper.querySelector("span").textContent = repeated
      ? "عرض الصورة في يسار بطاقة الفئة المتكررة"
      : "عرض هذا المرفق كصورة شخصية في يسار فئة المعلومات الرئيسية";
  }
  elements.fileTemplateEditor.hidden =
    !isFile || elements.fileNamingMode.value !== "template";
  elements.fieldConditionsList.closest(".dialog-subsection").hidden =
    SYSTEM_FIELD_TYPES.has(type);
  elements.fieldValidationEditor.hidden =
    systemField || !(textType || numberType || dateType);
  elements.fieldUserEditableWrapper.hidden = type !== "user_name";
  elements.fieldUserValueModeWrapper.hidden = type !== "user_name";
  elements.fieldAutoUpdateEditor.hidden = systemField;
  elements.numberBehaviorEditor.hidden = !numberType;
  elements.textValidationFields.hidden = !textType;
  elements.numberValidationFields.hidden = !numberType;
  elements.dateValidationFields.hidden = !dateType;
  if (isFile || systemField) {
    elements.fieldRequired.checked = false;
    if (isFile) elements.fieldSearchable.checked = false;
    if (isFile) elements.fieldShowResult.checked = false;
    elements.fieldResultTitle.checked = false;
    elements.fieldUnique.checked = false;
  }
  if (["yes_no", "select", "checkbox", "checkbox_group"].includes(type)) {
    elements.fieldSearchMatch.value = "exact";
  }
  if (dateType) {
    fillDateComparisonFields(fieldById(state.editingFieldId));
  }
  if (hasOptions) {
    fillOptionFilterSource();
    renderOptionFilterMatrix();
  }
  if (numberType) {
    updateNumberStorageNote();
  }
}

function renderFileParts() {
  elements.filePartsList.replaceChildren();
  state.filePartsDraft.forEach((part, index) => {
    const row = document.createElement("div");
    row.className = "file-part-row";
    const preview = document.createElement("span");
    preview.className = "file-part-preview";
    const field = fieldById(part.field_id);
    const prefix = part.prefix || "";
    const suffix = part.suffix || "";
    preview.textContent =
      `${JSON.stringify(prefix)} + ` +
      `{${field?.label || "حقل محذوف"}} + ` +
      `${JSON.stringify(suffix)}`;
    const actions = document.createElement("div");
    actions.className = "builder-actions";
    const up = builderActionButton(
      "نقل إلى أعلى",
      "file-part-up",
      String(index),
      "",
      "up",
    );
    const down = builderActionButton(
      "نقل إلى أسفل",
      "file-part-down",
      String(index),
      "",
      "down",
    );
    const remove = builderActionButton(
      "حذف الجزء",
      "file-part-delete",
      String(index),
      "button-danger-quiet",
      "trash",
    );
    up.disabled = index === 0;
    down.disabled = index === state.filePartsDraft.length - 1;
    actions.append(up, down, remove);
    row.append(preview, actions);
    elements.filePartsList.append(row);
  });
  if (!state.filePartsDraft.length) {
    const empty = document.createElement("div");
    empty.className = "builder-empty";
    empty.textContent = "أضف الحقول التي تكوّن اسم الملف بالترتيب المطلوب.";
    elements.filePartsList.append(empty);
  }
}

function addFilePart() {
  if (!elements.filePartField.value) {
    showToast("لا يوجد حقل متاح لتسمية الملف.", "error");
    return;
  }

  state.filePartsDraft.push({
    field_id: elements.filePartField.value,
    prefix: elements.filePartPrefix.value,
    suffix: elements.filePartSuffix.value,
  });

  elements.filePartPrefix.value = "";
  elements.filePartSuffix.value = "";

  renderFileParts();
}

function handleFilePartAction(button) {
  const index = Number(button.dataset.itemId);
  const action = button.dataset.builderAction;
  if (action === "file-part-delete") {
    state.filePartsDraft.splice(index, 1);
  } else if (action === "file-part-up") {
    moveArrayItem(state.filePartsDraft, index, -1);
  } else if (action === "file-part-down") {
    moveArrayItem(state.filePartsDraft, index, 1);
  }
  renderFileParts();
}

async function saveFieldFromDialog() {
  const category = categoryById(state.editingFieldCategoryId);
  if (!category) {
    return;
  }
  const type = selectedBuilderFieldType();
  const spacer = type === 'spacer';
  const label = spacer ? '' : elements.fieldLabel.value.trim();
  if (!label && !spacer) {
    showToast("اسم الحقل مطلوب.", "error");
    elements.fieldLabel.focus();
    return;
  }
  if (
    !spacer && category.fields.some(
      (field) =>
        field.id !== state.editingFieldId &&
        field.label.trim().toLocaleLowerCase() === label.toLocaleLowerCase(),
    )
  ) {
    showToast("اسم الحقل مستخدم داخل هذه الفئة.", "error");
    return;
  }

  const systemField = SYSTEM_FIELD_TYPES.has(type);
  if (systemField && category.kind !== "main") {
    showToast("حقول معرّف السجل وتواريخه تضاف إلى فئة رئيسية فقط.", "error");
    return;
  }
  if (
    systemField &&
    allFields().some(
      ({ field }) => field.id !== state.editingFieldId && field.type === type,
    )
  ) {
    showToast("يوجد حقل آخر من نوع بيانات السجل نفسه.", "error");
    return;
  }
  let options = [];
  let optionFilter = null;
  if (type === "yes_no") {
    const previous = state.fieldOptionsDraft || [];
    options = ["نعم", "لا"].map(
      (optionLabel) =>
        previous.find((candidate) => candidate.label === optionLabel) || {
          id: randomDefinitionId("opt"),
          label: optionLabel,
          active: true,
        },
    );
  } else if (["select", "checkbox_group"].includes(type)) {
    if (elements.optionFilterSource.value) {
      optionFilter = collectOptionFilter();
      options = deepClone(state.fieldOptionsDraft);
    } else {
      options = reconcileFieldOptions();
    }
  }
  if (["select", "checkbox_group"].includes(type) && !options.length) {
    showToast("أضف خيارًا واحدًا على الأقل للحقل.", "error");
    return;
  }
  if (
    !elements.relatedPersonFieldEditor.hidden &&
    elements.relatedPersonSourceField.value &&
    fieldCategory(elements.relatedPersonSourceField.value)?.kind === "repeatable" &&
    !elements.relatedPersonSourceCheckbox.value
  ) {
    showToast("اختر مربع الاختيار الفريد الذي يحدد بطاقة المصدر.", "error");
    return;
  }
  if (
    type === "user_name" &&
    elements.fieldUserValueMode.value === "current_on_checkbox" &&
    !elements.fieldUserTrigger.value
  ) {
    showToast("اختر مربع الاختيار الذي يحدّث اسم المستخدم.", "error");
    return;
  }
  if (
    elements.fieldType.value === "date" &&
    elements.fieldDateMode.value === "automatic_checkbox" &&
    !elements.fieldDateTrigger.value
  ) {
    showToast("اختر مربع الاختيار الذي يحدّث التاريخ.", "error");
    return;
  }
  if (
    type === "file" &&
    elements.fileNamingMode.value === "template" &&
    !state.filePartsDraft.length
  ) {
    showToast("أضف جزءًا واحدًا على الأقل لصيغة اسم الملف.", "error");
    return;
  }
  if (
    type === "file" &&
    elements.fileProfileImage.checked &&
    category.kind === "main" &&
    allFields().some(
      ({ field }) =>
        field.id !== state.editingFieldId &&
        field.image_display === "profile",
    )
  ) {
    showToast("يوجد حقل آخر محدد بوصفه الصورة الشخصية.", "error");
    return;
  }

  const validation = collectValidation(type);
  if (
    validation.min_length != null &&
    validation.max_length != null &&
    validation.min_length > validation.max_length
  ) {
    showToast("الحد الأدنى لطول النص أكبر من الحد الأعلى.", "error");
    return;
  }
  if (
    validation.min != null &&
    validation.max != null &&
    validation.min > validation.max
  ) {
    showToast("الحد الأدنى للرقم أكبر من الحد الأعلى.", "error");
    return;
  }
  if (
    validation.min_date &&
    validation.max_date &&
    validation.min_date > validation.max_date
  ) {
    showToast("أقدم تاريخ مسموح يأتي بعد أحدث تاريخ مسموح.", "error");
    return;
  }
  if (validation.pattern) {
    try {
      new RegExp(validation.pattern);
    } catch (_error) {
      showToast("نمط التحقق النصي غير صالح.", "error");
      return;
    }
  }

  const existing = state.editingFieldId
    ? fieldById(state.editingFieldId)
    : null;
  const wasDataField = existing && existing.type !== 'spacer';
  if (
    existing &&
    existing.type !== type &&
    (state.schema?.stats?.record_count || 0) > 0 &&
    (existing.type === "file" || type === "file" || type === 'spacer') &&
    !(await requestConfirmation(
      "تغيير الحقل من ملف أو إليه، أو إلى مساحة فارغة، سيمسح قيمه الحالية عند حفظ التصميم.",
      { title: "تغيير نوع الحقل", confirmLabel: "تغيير النوع" },
    ))
  ) {
    return;
  }

  const field = existing || {
    id: state.editingFieldId,
  };
  if (existing && state.editingFieldDetachGlobal) {
    field.global_ref = null;
  }
  field.label = label;
  field.type = type;
  field.required =
    !systemField &&
    !(type === "user_name" && ["current_on_save", "current_on_checkbox"].includes(elements.fieldUserValueMode.value)) &&
    elements.fieldRequired.checked;
  field.placeholder = systemField
    ? ""
    : elements.fieldPlaceholder.value.trim();
  field.width = elements.fieldWidth.value;
  field.start_new_line = elements.fieldStartNewLine.checked;
  field.checkbox_true_label = type === "checkbox" ? elements.fieldCheckboxTrueLabel.value.trim() : "";
  field.checkbox_false_label = type === "checkbox" ? elements.fieldCheckboxFalseLabel.value.trim() : "";
  field.options = options;
  field.searchable =
    type !== "file" && elements.fieldSearchable.checked;
  field.search_match = elements.fieldSearchMatch.value;
  field.show_in_results =
    type !== "file" && elements.fieldShowResult.checked;
  field.result_title =
    category.kind === "main" &&
    field.show_in_results &&
    elements.fieldResultTitle.checked;
  field.unique =
    type !== "file" &&
    type !== "checkbox" &&
    !systemField &&
    elements.fieldUnique.checked;
  field.validation = systemField ? {} : validation;
  field.user_editable = type === "user_name" ? elements.fieldUserEditable.checked : true;
  field.user_value_mode = type === "user_name"
    ? elements.fieldUserValueMode.value
    : "created_by";
  field.user_trigger_field_id = type === "user_name" && elements.fieldUserValueMode.value === "current_on_checkbox"
    ? elements.fieldUserTrigger.value || null
    : null;
  field.date_value_mode = type === "date_gregorian" && elements.fieldType.value === "date" && elements.fieldDateMode.value === "automatic_checkbox"
    ? "on_checkbox"
    : "manual";
  field.date_trigger_field_id = field.date_value_mode === "on_checkbox"
    ? elements.fieldDateTrigger.value || null
    : null;
  field.unique_checked_across_cards = type === "checkbox" && category.kind === "repeatable"
    ? elements.fieldUniqueCardCheckbox.checked
    : false;
  field.auto_update = collectAutoUpdateRule(type);
  if (type === "number") {
    field.number_behavior = collectNumberBehavior(type);
  } else {
    delete field.number_behavior;
  }
  field.option_filter = ["select", "checkbox_group"].includes(type)
    ? optionFilter
    : null;
  field.related_person_source_field_id =
    category.kind === "repeatable" && category.related_person_enabled
      ? elements.relatedPersonSourceField.value || null
      : null;
  field.related_person_source_checkbox_id =
    category.kind === "repeatable" && category.related_person_enabled
      ? elements.relatedPersonSourceCheckbox.value || null
      : null;
  delete field.related_person_source_marker_id;

  if (type === "file") {
    field.image_display = elements.fileProfileImage.checked
      ? (category.kind === "repeatable" ? "card" : "profile")
      : null;
    field.file_naming = {
      mode: elements.fileNamingMode.value,
      parts: deepClone(state.filePartsDraft),
    };
  } else {
    delete field.image_display;
    delete field.file_naming;
  }
  if (existing) {
    const originalCategory = fieldCategory(existing.id);
    const oldIndex = originalCategory?.fields.findIndex(item => item.id === existing.id) ?? -1;
    if (oldIndex >= 0) originalCategory.fields.splice(oldIndex, 1);
  }
  const placement = elements.fieldAfter.value;
  const afterIndex = category.fields.findIndex(candidate => candidate.id === placement);
  const insertionIndex = placement === "start" ? 0 : afterIndex >= 0 ? afterIndex + 1 : category.fields.length;
  category.fields.splice(insertionIndex, 0, field);
  if (spacer) {
    if (wasDataField) {
      const appearance = state.draftSchema.conditions.filter(rule => rule.target_type === "field" && rule.target_id === field.id && rule.source_field_id !== field.id);
      removeReferencesToFields([field.id]);
      state.draftSchema.conditions.push(...appearance);
    }
    Object.assign(field, {label:'', required:false, unique:false, placeholder:'', options:[], searchable:false, show_in_results:false, result_title:false, validation:{}, option_filter:null, auto_update:null, related_person_source_field_id:null, related_person_source_checkbox_id:null});
  }
  if (state.globalEditor?.kind === "field") {
    state.fieldDialogCommitted = true;
    void commitGlobalDefinitionFromEditor("field", field);
    elements.fieldDialog.close();
    return;
  }
  markDirty();
  renderBuilder();
  state.fieldDialogCommitted = true;
  elements.fieldDialog.close();
}

function conditionTargetCategory(targetType, targetId) {
  if (targetType === "category") {
    const existing = categoryById(targetId);

    if (existing) {
      return existing;
    }

    if (state.editingCategoryId === targetId) {
      return {
        id: targetId,
        kind: elements.categoryKind.value,
      };
    }

    return null;
  }

  const existing = fieldCategory(targetId);

  if (existing) {
    return existing;
  }

  if (state.editingFieldId === targetId) {
    return categoryById(state.editingFieldCategoryId);
  }

  return null;
}

function fillConditionSources(targetType, targetId, selected = "") {
  elements.conditionSource.replaceChildren();

  const targetCategory = conditionTargetCategory(targetType, targetId);

  if (targetType === "field") {
    const relatedPersonMode = relatedPersonModeField(targetCategory);
    if (relatedPersonMode) {
      const option = document.createElement("option");
      option.value = relatedPersonMode.id;
      option.textContent = `${targetCategory.label} ← ${relatedPersonMode.label}`;
      elements.conditionSource.append(option);
    }
  }

  for (const { category, field } of allFields()) {
    const allowed =
      field.id !== targetId &&
      !isSystemField(field) &&
      (category.kind === "main" || category.id === targetCategory?.id);

    if (!allowed) {
      continue;
    }

    const option = document.createElement("option");

    option.value = field.id;
    option.textContent = `${category.label} ← ${field.label}`;

    elements.conditionSource.append(option);
  }

  if (selected) {
    elements.conditionSource.value = selected;
  }
}

function fillConditionOperators(selected = "") {
  elements.conditionOperator.replaceChildren();

  const source = fieldById(elements.conditionSource.value);

  const operators = CONDITION_OPERATORS_BY_TYPE[source?.type] || [];

  operators.forEach((operator) => {
    const option = document.createElement("option");

    option.value = operator;
    option.textContent = OPERATOR_LABELS[operator] || operator;

    elements.conditionOperator.append(option);
  });

  if (selected && operators.includes(selected)) {
    elements.conditionOperator.value = selected;
  }
}

function fillConditionGroups(targetType, targetId, selected = "") {
  elements.conditionGroup.replaceChildren();

  const rules = conditionsFor(targetType, targetId, state.draftSchema);

  const groupIds = [
    ...new Set(
      rules.map(
        (condition) => condition.group_id || `legacy-${targetType}-${targetId}`,
      ),
    ),
  ];

  groupIds.forEach((groupId, index) => {
    const option = document.createElement("option");

    option.value = groupId;
    option.textContent = `المجموعة ${index + 1} — AND`;

    elements.conditionGroup.append(option);
  });

  const newGroup = document.createElement("option");

  newGroup.value = "__new_group__";
  newGroup.textContent = "مجموعة بديلة جديدة — OR";

  elements.conditionGroup.append(newGroup);

  if (selected && groupIds.includes(selected)) {
    elements.conditionGroup.value = selected;
  } else if (groupIds.length) {
    elements.conditionGroup.value = groupIds[0];
  } else {
    elements.conditionGroup.value = "__new_group__";
  }
}
function createConditionCalendarControl(type, initialValue = "") {
  const root = document.createElement("div");
  root.className = "calendar-control";

  const hidden = document.createElement("input");
  hidden.type = "hidden";
  hidden.dataset.conditionValue = "";

  const year = document.createElement("select");
  year.className = "control";

  const month = document.createElement("select");
  month.className = "control";

  const day = document.createElement("select");
  day.className = "control";

  appendBlankOption(year, "السنة");
  appendBlankOption(month, "الشهر");
  appendBlankOption(day, "اليوم");

  const [firstYear, lastYear] = calendarYearRange(type);

  for (let value = firstYear; value <= lastYear; value += 1) {
    const option = document.createElement("option");

    option.value = String(value);
    option.textContent = String(value);
    year.append(option);
  }

  CALENDAR_MONTH_NAMES[type].forEach((name, index) => {
    const option = document.createElement("option");

    option.value = String(index + 1).padStart(2, "0");
    option.textContent = name;

    month.append(option);
  });

  function synchronizeDays() {
    const previousDay = day.value;
    populateCalendarDays(
      day,
      maximumSelectableCalendarDay(type, year.value, month.value),
      previousDay,
    );

    hidden.value =
      year.value && month.value && day.value
        ? `${year.value}-${month.value}-${day.value}`
        : "";
  }

  installSelectAutoAdvance(day, {
    onChange: synchronizeDays,
    advance: () => month.focus(),
    requiredDigits: 2,
  });

  installSelectAutoAdvance(month, {
    onChange: synchronizeDays,
    advance: () => year.focus(),
    requiredDigits: 2,
  });

  installSelectAutoAdvance(year, {
    onChange: synchronizeDays,
    advance: () => elements.confirmConditionButton.focus(),
    requiredDigits: 4,
  });

  root.append(hidden, day, month, year);

  const [initialYear, initialMonth, initialDay] = String(
    initialValue || "",
  ).split("-");

  year.value = initialYear || "";
  month.value = initialMonth || "";

  synchronizeDays();

  day.value = initialDay || "";
  synchronizeDays();

  return root;
}

function currentConditionValue() {
  return (
    elements.conditionValueControl.querySelector("[data-condition-value]")
      ?.value || ""
  );
}

function renderConditionValueControl(initialValue = "") {
  elements.conditionValueControl.replaceChildren();

  const source = fieldById(elements.conditionSource.value);

  const operator = elements.conditionOperator.value;

  const requiresValue = !["empty", "not_empty"].includes(operator);

  elements.conditionValueWrapper.hidden = !requiresValue;

  if (!requiresValue || !source) {
    return;
  }

  if (["date_gregorian", "date_hijri", "date_persian"].includes(source.type)) {
    elements.conditionValueControl.append(
      createConditionCalendarControl(source.type, initialValue),
    );

    return;
  }

  let control;

  if (source.type === "checkbox") {
    control = document.createElement("select");
    control.className = "control";

    const checked = document.createElement("option");

    checked.value = "true";
    checked.textContent = checkboxDisplayMeaning(source, true);

    const unchecked = document.createElement("option");

    unchecked.value = "false";
    unchecked.textContent = checkboxDisplayMeaning(source, false);

    control.append(checked, unchecked);
  } else if (["select", "yes_no", "checkbox_group"].includes(source.type)) {
    control = document.createElement("select");
    control.className = "control";

    appendBlankOption(control, "— اختر —");

    (source.options || []).forEach((sourceOption) => {
      const option = document.createElement("option");

      option.value = sourceOption.id;
      option.textContent =
        sourceOption.active === false
          ? `${sourceOption.label} — غير نشط`
          : sourceOption.label;

      control.append(option);
    });
  } else {
    control = document.createElement("input");
    control.className = "control";

    if (source.type === "number") {
      control.type = "number";
      control.step = "any";
    } else {
      control.type = "text";
    }
  }

  control.dataset.conditionValue = "";

  if (["select", "yes_no", "checkbox_group"].includes(source.type)) {
    control.value = optionIdForValue(source, initialValue);
  } else {
    control.value = initialValue || "";
  }

  elements.conditionValueControl.append(control);
}
function openConditionDialog(
  conditionId = null,
  targetType = null,
  targetId = null,
) {
  const condition = conditionId
    ? state.draftSchema.conditions.find((item) => item.id === conditionId)
    : null;

  if (condition) {
    targetType = condition.target_type;
    targetId = condition.target_id;
  }

  if (!targetType || !targetId) {
    showToast("افتح الفئة أو الحقل الذي تريد إضافة الشرط إليه.", "error");
    return;
  }

  state.editingConditionId = conditionId;
  state.conditionTargetType = targetType;
  state.conditionTargetId = targetId;

  elements.conditionDialogTitle.textContent = condition
    ? "تعديل شرط ظهور"
    : "إضافة شرط ظهور";

  elements.conditionTargetLabel.textContent = editableTargetLabel(
    targetType,
    targetId,
  );

  fillConditionSources(targetType, targetId, condition?.source_field_id || "");

  if (!elements.conditionSource.options.length) {
    showToast("لا يوجد حقل متاح للتحكم في ظهور هذا العنصر.", "error");
    return;
  }

  fillConditionOperators(condition?.operator || "");

  fillConditionGroups(targetType, targetId, condition?.group_id || "");

  elements.conditionNegate.checked = Boolean(condition?.negate);

  renderConditionValueControl(condition?.value || "");

  elements.conditionDialog.showModal();
}

function saveConditionFromDialog() {
  const targetType = state.conditionTargetType;

  const targetId = state.conditionTargetId;

  const sourceId = elements.conditionSource.value;

  const operator = elements.conditionOperator.value;

  if (!targetType || !targetId || !sourceId || !operator) {
    showToast("بيانات شرط الظهور غير مكتملة.", "error");
    return;
  }

  const requiresValue = !["empty", "not_empty"].includes(operator);

  const value = requiresValue ? currentConditionValue() : "";

  if (requiresValue && String(value).trim() === "") {
    showToast("اختر أو أدخل قيمة الشرط.", "error");
    return;
  }

  const existing = state.editingConditionId
    ? state.draftSchema.conditions.find(
        (condition) => condition.id === state.editingConditionId,
      )
    : null;

  const condition = existing || {
    id: randomDefinitionId("cond"),
  };

  let groupId = elements.conditionGroup.value;

  if (groupId === "__new_group__") {
    groupId = randomDefinitionId("grp");
  }

  condition.target_type = targetType;
  condition.target_id = targetId;
  condition.source_field_id = sourceId;
  condition.operator = operator;
  condition.value = value;
  condition.group_id = groupId;
  condition.negate = elements.conditionNegate.checked;

  if (!existing) {
    state.draftSchema.conditions.push(condition);
  }

  if (targetType === "category") {
    const targetCategory = categoryById(targetId);

    const sourceCategory = fieldCategory(sourceId);

    if (
      targetCategory?.kind === "repeatable" &&
      !targetCategory.anchor_field_id &&
      sourceCategory?.kind === "main"
    ) {
      targetCategory.anchor_field_id = sourceId;
    }
  }

  if (state.globalEditor?.packageMode && state.globalEditor.kind === "condition") {
    const editor = state.globalEditor;
    void commitGlobalCategoryPackageFromEditor(
      "condition",
      { label: existing ? "تعديل شرط ظهور" : "إضافة شرط ظهور" },
      editor,
    );
    elements.conditionDialog.close();
    return;
  }

  markDirty();
  refreshConditionEditors();
  elements.conditionDialog.close();
}

function setSchemaSaving(saving) {
  state.savingSchema = saving;
  elements.saveSchemaButton.disabled = saving;
  elements.discardSchemaButton.disabled = saving;
  elements.backupButton.disabled = saving || state.backingUp;
  elements.schemaSpinner.hidden = !saving;
  elements.saveSchemaText.textContent = saving
    ? "جاري حفظ التصميم…"
    : "حفظ تصميم التطبيق";
}

async function saveSchema(options = {}) {
  const automatic = options.automatic === true;

  if (state.savingSchema || !state.draftSchema) {
    return false;
  }

  const previousSchema = deepClone(state.schema || { categories: [] });
  setSchemaSaving(true);

  try {
    const response = await fetch("/api/schema", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(state.draftSchema),
    });

    const schema = await responseJson(response);
    const changes = describeBuilderChanges(previousSchema, schema);

    applyLoadedSchema(schema, {
      resetRecord: !automatic,
      preservePage: true,
      builderSave: true,
    });

    if (automatic) {
      const time = new Date().toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });

      elements.builderSaveState.dataset.dirty = "false";
      elements.builderSaveState.textContent = `حُفظ التصميم تلقائيًا عند ${time}.`;
    } else {
      showToast(schema.workbook_sync_pending
        ? "تم حفظ التصميم، ويجري تحديث ملف Excel في الخلفية."
        : "تم حفظ تصميم التطبيق وتحديث ملف Excel.");
    }

    rememberBuilderHistory(
      state.activeSchemaId,
      schema.schema_name || state.schema?.schema_name || "التصميم",
      changes,
      automatic,
    );

    return true;
  } catch (error) {
    reportClientError(automatic ? "schema-autosave" : "schema-save", error);
    if (automatic) {
      state.dirty = true;

      elements.builderSaveState.dataset.dirty = "true";
      elements.builderSaveState.textContent = `تعذّر الحفظ التلقائي: ${error.message}`;
    } else {
      showToast(error.message, "error");
    }

    return false;
  } finally {
    setSchemaSaving(false);
  }
}
async function autosaveBuilder() {
  if (
    state.closing ||
    state.mode !== "builder" ||
    state.builderScope !== "schema" ||
    !state.dirty ||
    state.savingSchema ||
    !state.draftSchema
  ) {
    return;
  }

  await saveSchema({
    automatic: true,
  });
}

async function createBackup() {
  if (state.backingUp || state.savingSchema) {
    return;
  }
  state.backingUp = true;
  elements.backupButton.disabled = true;
  try {
    const response = await fetch("/api/backup", { method: "POST" });
    const result = await responseJson(response);
    const download = document.createElement("a");
    download.href = result.download_url;
    download.download = result.filename;
    document.body.append(download);
    download.click();
    download.remove();
    showToast(`تم إنشاء النسخة الاحتياطية: ${result.filename}`);
  } catch (error) {
    reportClientError("backup-create", error);

    showToast(error.message, "error");
  } finally {
    state.backingUp = false;
    elements.backupButton.disabled = state.savingSchema;
  }
}

async function discardSchemaChanges() {
  if (!state.dirty) {
    return;
  }
  if (!(await requestConfirmation("هل تريد تجاهل جميع تغييرات التصميم غير المحفوظة؟", {
    title: "تجاهل تغييرات التصميم",
    confirmLabel: "تجاهل التغييرات",
  }))) {
    return;
  }
  state.draftSchema = deepClone(state.schema);
  markClean();
  renderBuilder();
}

/* pages/builder/preview.js */
// A render context lets schema and general definitions share the same layout
// without replacing the live schema/draft or connecting record workflows.
let activeBuilderPreviewContext = null;
function builderPreviewContext() {
  return activeBuilderPreviewContext || {root:elements.builderCategories, schema:state.draftSchema, cache:builderPreviewCache, schemaId:state.activeSchemaId};
}

// Schema layout preview. Only schema actions are interactive; no record controls
// or related-profile workflows are connected to this surface.
function builderPreviewCategoryPeers(category) {
  return builderPreviewContext().schema.categories.filter((item) =>
    item.kind === category.kind &&
    (item.parent_category_id || '') === (category.parent_category_id || '') &&
    (item.parent_field_id || '') === (category.parent_field_id || '') &&
    (item.anchor_field_id || '') === (category.anchor_field_id || ''));
}

function selectBuilderPreviewItem(kind, id, toggle = true, root = elements.builderCategories) {
  appHoverCards.hide();
  const key = `${kind}:${id}`;
  const selected = !kind || (toggle && root.dataset.selectedItem === key) ? '' : key;
  root.dataset.selectedItem = selected;
  root.querySelectorAll('[data-preview-actions]').forEach((actions) => {
    actions.hidden = actions.dataset.previewActions !== selected;
  });
  root.querySelectorAll('[data-preview-select]').forEach((name) => {
    name.setAttribute('aria-expanded', String(name.dataset.previewSelect === selected));
  });
  root.querySelectorAll('.builder-preview-selected').forEach((item) => item.classList.remove('builder-preview-selected'));
  if (selected) {
    const actions = [...root.querySelectorAll('[data-preview-actions]')].find((item) => item.dataset.previewActions === selected);
    actions?.parentElement.classList.add('builder-preview-selected');
    const name = [...root.querySelectorAll('[data-preview-select]')].find((item) => item.dataset.previewSelect === selected);
    if (actions && name) positionBuilderPreviewActions(actions, name);
  }
}

function positionBuilderPreviewActions(actions, name) {
  const parent = actions.offsetParent || actions.parentElement;
  const bounds = parent.getBoundingClientRect();
  const label = name.getBoundingClientRect();
  const width = actions.getBoundingClientRect().width;
  actions.style.insetInlineStart = 'auto';
  actions.style.insetInlineEnd = 'auto';
  actions.style.left = `${Math.max(0, Math.min(label.right - bounds.left - width, bounds.width - width))}px`;
  actions.style.top = `${label.bottom - bounds.top + parent.scrollTop + 5}px`;
}

function builderPreviewDetails(kind, id) {
  const schema = builderPreviewContext().schema;
  const item = kind === 'field' ? fieldById(id, schema) : categoryById(id, schema);
  if (!item) return '';
  if (kind === 'category') {
    const parent = categoryById(item.parent_category_id, schema);
    return [item.kind === 'repeatable' ? 'فئة متكررة' : 'فئة رئيسية', parent ? `ضمن ${parent.label}` : 'بلا فئة أم', `${item.fields.length} حقول`, item.auto_start ? "بطاقة تلقائية" : "", item.related_person_enabled ? "ربط بالأشخاص" : "", item.description].filter(Boolean).join(' · ');
  }
  return [FIELD_TYPE_LABELS[item.type] || item.type, item.width === 'full' ? 'العرض الكامل' : `العرض: ${item.width || 1}`, item.required ? 'مطلوب' : 'غير مطلوب', item.searchable ? 'قابل للبحث' : 'غير قابل للبحث', item.show_in_results ? 'يظهر في النتائج' : '', item.unique ? 'قيمة فريدة' : '', item.image_display ? 'صورة شخصية' : '', item.option_filter ? 'قائمة مترابطة' : '', item.start_new_line ? 'بداية سطر جديد' : '', item.type === 'checkbox' ? `التحديد: ${checkboxDisplayMeaning(item, true)} · عدم التحديد: ${checkboxDisplayMeaning(item, false)}` : '', item.placeholder].filter(Boolean).join(' · ');
}

function builderCategoryHoverCard(id) {
  if (id === 'global-standalone-preview') return null;
  const category = categoryById(id, builderPreviewContext().schema);
  const details = builderPreviewDetails('category', id);
  return () => ({name:category.label, details, fields:category.fields.map(field => field.type === 'spacer' ? 'مساحة فارغة' : field.label)});
}

function builderFieldHoverCard(id) {
  const field = fieldById(id, builderPreviewContext().schema);
  const details = builderPreviewDetails('field', id);
  return () => ({name:field.type === 'spacer' ? 'مساحة فارغة' : field.label, details});
}

function builderPreviewActions(kind, item, category) {
  const context = builderPreviewContext();
  if (context.actions) return context.actions(kind, item, category);
  const actions = document.createElement('div');
  actions.className = 'builder-actions builder-preview-actions';
  actions.dataset.previewActions = `${kind}:${item.id}`;
  actions.id = `builder-preview-actions-${item.id}`;
  actions.setAttribute('role', 'group');
  actions.setAttribute('aria-label', `إجراءات ${item.label}`);
  actions.hidden = true;
  const peers = kind === 'field' ? category.fields : builderPreviewCategoryPeers(item);
  const index = peers.findIndex((peer) => peer.id === item.id);
  const remove = builderActionButton(`حذف ${item.label}`, `delete-${kind}`, item.id, 'button-danger-quiet');
  const edit = builderActionButton(`تعديل ${item.label}`, `edit-${kind}`, item.id);
  const later = builderActionButton('نقل لليسار — التالي في الترتيب', `move-${kind}-down`, item.id, '', 'left');
  const earlier = builderActionButton('نقل لليمين — السابق في الترتيب', `move-${kind}-up`, item.id, '', 'right');
  earlier.disabled = index <= 0;
  later.disabled = index === peers.length - 1;
  [remove, edit, earlier, later].forEach((button) => {
    if (category) button.dataset.categoryId = category.id;
    actions.append(button);
  });
  return actions;
}

function builderPreviewName(label, kind, id) {
  const root = builderPreviewContext().root;
  const name = document.createElement('button');
  name.type = 'button';
  name.className = 'builder-preview-name';
  name.textContent = label;
  name.dataset.hoverLabel = label;
  name.title = label;
  if (kind === 'category') name._categoryHoverCard = builderCategoryHoverCard(id);
  // Field details belong to the input preview, never its name.
  name.dataset.previewSelect = `${kind}:${id}`;
  name.setAttribute('aria-expanded', 'false');
  name.setAttribute('aria-controls', `builder-preview-actions-${id}`);
  name.addEventListener('click', (event) => {
    event.preventDefault();
    selectBuilderPreviewItem(kind, id, true, root);
  });
  return name;
}

const builderPreviewCache = {schemaId:null, fields:new Map(), sections:new Map(), signature:null};

function createBuilderPreviewField(field, scope, categoryId) {
  const context = builderPreviewContext();
  const cache = context.cache;
  const signature = JSON.stringify([categoryId, field]);
  const cached = cache.fields.get(field.id);
  const category = categoryById(categoryId, context.schema);
  if (cached?.signature === signature) {
    // Boundary buttons change when siblings are inserted, deleted or reordered.
    cached.row.querySelector('[data-builder-action="move-field-up"]').disabled = category.fields[0]?.id === field.id;
    cached.row.querySelector('[data-builder-action="move-field-down"]').disabled = category.fields.at(-1)?.id === field.id;
    return cached.row;
  }
  const row = buildBuilderPreviewField(field, scope, categoryId);
  cache.fields.set(field.id, {signature, row});
  return row;
}

function buildBuilderPreviewField(field, scope, categoryId) {
  const category = categoryById(categoryId, builderPreviewContext().schema);
  // Clone the shared renderer to keep its exact geometry without its listeners.
  const row = createFieldElement(field, 'builder-preview', categoryId).cloneNode(true);
  row.classList.add('builder-field-row', 'builder-preview-field');
  row.dataset.fieldId = field.id;
  row._fieldHoverCard = builderFieldHoverCard(field.id);
  delete row.dataset.fieldWrapper;
  row.removeAttribute('aria-hidden');
  row.querySelectorAll('*').forEach((node) => {
    for (const attribute of [...node.attributes]) {
      if (attribute.name.startsWith('data-')) node.removeAttribute(attribute.name);
    }
    if (node.matches('input:not([type="checkbox"]), textarea')) node.value = '';
  });
  const name = builderPreviewName(field.type === 'spacer' ? 'مساحة فارغة' : field.label, 'field', field.id);
  if (field.required) {
    const required = document.createElement('span');
    required.className = 'required-mark';
    required.textContent = '*';
    name.append(required);
  }
  const label = row.querySelector(':scope > label:not(.standalone-check)');
  if (field.type === 'spacer') row.append(name);
  else if (label) label.replaceWith(name);
  else {
    // Checkbox names sit beside their checkbox, at input level.
    const check = row.querySelector(':scope > .standalone-check');
    const line = document.createElement('div');
    line.className = check.className;
    const input = check.querySelector('input');
    input.setAttribute('inert', '');
    line.append(input, name);

    check.replaceWith(line);
  }
  row.querySelectorAll('input, textarea, select').forEach(control => control.setAttribute('inert', ''));
  for (const child of row.children) {
    if (child !== name && !child.contains(name)) child.setAttribute('inert', '');
  }
  row.querySelectorAll('input:not([type="hidden"]):not([type="file"]):not([type="checkbox"]), textarea').forEach((control) => {
    control.placeholder = field.placeholder || '';
  });
  row.querySelectorAll('select').forEach(control => {
    control.replaceChildren(new Option(field.placeholder || '', ''));
    control.value = '';
  });
  row.querySelectorAll('.file-name').forEach(control => {
    if (!control.matches('input')) control.textContent = field.placeholder || '';
  });
  row.append(builderPreviewActions('field', field, category));
  builderPreviewContext().decorateField?.(row, field);
  return row;
}

function createBuilderPreviewRelated(category, anchors, rendered, options) {
  const section = document.createElement('section');
  section.className = 'related-section field-full';
  section.dataset.categoryId = category.id;
  section.append(createSectionHeading(category));
  const browser = document.createElement('div');
  browser.className = 'home-tabbed-workspace home-schema-browser related-tab-workspace';
  const rail = document.createElement('div');
  rail.className = 'related-add-row home-schema-browser-tabs';
  rail.setAttribute('role', 'tablist');
  rail.setAttribute('aria-label', category.label);
  const tab = document.createElement('button');
  tab.type = 'button';
  tab.className = 'home-schema-browser-tab is-active';
  tab.setAttribute('role', 'tab');
  tab.setAttribute('aria-selected', 'true');
  tab.id = `builder-preview-card-tab-${category.id}`;
  const label = document.createElement('span');
  const titleField = fieldById(category.card_title_field_id, builderPreviewContext().schema);
  label.textContent = titleField?.label || `${category.card_name_prefix || 'بطاقة'} 1`;
  if (titleField) tab.setAttribute('aria-label', `اسم البطاقة من الحقل: ${titleField.label}`);
  tab.append(label);
  rail.append(tab);
  const panels = document.createElement('div');
  panels.className = 'related-records home-schema-browser-panels';
  const card = document.createElement('div');
  card.className = 'related-card is-active';
  card.id = `builder-preview-card-${category.id}`;
  card.setAttribute('role', 'tabpanel');
  card.setAttribute('aria-labelledby', tab.id);
  tab.setAttribute('aria-controls', card.id);
  if (category.related_person_enabled) {
    const heading = document.createElement('div');
    heading.className = 'related-card-heading';
    heading.setAttribute('inert', '');
    const workflow = document.createElement('div');
    workflow.className = 'related-person-workflow';
    const question = document.createElement('span');
    question.className = 'related-person-question';
    question.textContent = 'هل لديه سجل؟';
    const modes = document.createElement('div');
    modes.className = 'related-person-modes';
    ['لديه سجل', 'ليس لديه سجل'].forEach((label) => {
      const button = document.createElement('button');
      button.type = 'button'; button.className = 'related-person-mode'; button.textContent = label;
      modes.append(button);
    });
    workflow.append(question, modes);
    heading.append(workflow);
    card.append(heading);
  }
  const grid = document.createElement('div');
  grid.className = 'field-grid';
  const children = categoryChildren(category.id, options.schema).filter((child) => child.kind === 'repeatable');
  const addChild = (child, destination) => {
    const nested = createEntryCategorySection(child, anchors, rendered, options);
    if (nested) destination.append(nested);
  };
  category.fields.forEach((field) => {
    grid.append(createBuilderPreviewField(field, 'related', category.id));
    children.filter((child) => child.parent_field_id === field.id).forEach((child) => addChild(child, grid));
  });
  card.append(grid);
  const nested = document.createElement('div');
  nested.className = 'related-card-nested-categories';
  children.filter((child) => !rendered.has(child.id)).forEach((child) => addChild(child, nested));
  if (nested.children.length) card.append(nested);
  panels.append(card);
  browser.append(rail, panels);
  section.append(browser);
  return section;
}

function renderBuilderPreview(context = builderPreviewContext()) {
  const previous = activeBuilderPreviewContext;
  activeBuilderPreviewContext = context;
  try { return withSchemaRenderIndex(context.schema, renderBuilderPreviewContents); }
  finally { activeBuilderPreviewContext = previous; }
}

function renderBuilderPreviewContents() {
  const context = builderPreviewContext();
  const {root, schema, cache, schemaId} = context;
  const signature = JSON.stringify([schemaId, schema.app, schema.categories, schema.conditions]);
  if (cache.signature === signature && root.childElementCount) return;
  if (cache.schemaId !== schemaId) {
    cache.fields.clear();
    cache.sections.clear();
    cache.schemaId = schemaId;
  }
  const fieldIds = new Set(allFields(schema, true).map(({field}) => field.id));
  for (const id of cache.fields.keys()) {
    if (!fieldIds.has(id)) cache.fields.delete(id);
  }
  const activeCategory = root.dataset.activeMainCategory;
  const selected = root.dataset.selectedItem;
  const focusedAction = root.contains(document.activeElement) ? document.activeElement.dataset.builderAction : null;
  root.classList.add('builder-layout-preview');
  if (root === elements.builderCategories) elements.noCategoriesMessage.hidden = schema.categories.length > 0;
  const anchors = new Map([...anchoredRelatedCategories(schema)].map(([id, categories]) => [id, categories.filter(category => category.parent_category_id)]));
  const anchored = new Set([...anchors.values()].flat().map((item) => item.id));
  const rendered = new Set();
  const options = {schema, fieldFactory:createBuilderPreviewField, relatedFactory:createBuilderPreviewRelated};
  const ids = new Set(schema.categories.map((category) => category.id));
  const roots = schema.categories.filter((category) => !category.parent_category_id || !ids.has(category.parent_category_id));
  const main = [], related = [];
  const sectionsUsed = new Set();
  const categorySignatures = new Map(schema.categories.map(category => [category.id, JSON.stringify(category)]));
  const dependencies = (category, seen = new Set()) => {
    if (seen.has(category.id)) return seen;
    seen.add(category.id);
    categoryChildren(category.id, schema).forEach(child => dependencies(child, seen));
    category.fields.forEach(field => (anchors.get(field.id) || []).forEach(child => dependencies(child, seen)));
    return seen;
  };
  const append = (category) => {
    if (rendered.has(category.id)) return;
    const peers = builderPreviewCategoryPeers(category);
    const signature = JSON.stringify([
      [...dependencies(category)].map(id => categorySignatures.get(id)),
      schema.conditions, schema.app, peers[0]?.id === category.id, peers.at(-1)?.id === category.id,
    ]);
    const cached = cache.sections.get(category.id);
    let section;
    if (cached?.signature === signature && cached.ids.every(id => !rendered.has(id))) {
      section = cached.section;
      cached.ids.forEach(id => rendered.add(id));
    } else {
      section = createEntryCategorySection(category, anchors, rendered, options);
      if (!section) return;
      const sections = [section, ...section.querySelectorAll('.form-section, .related-section')];
      sections.forEach(section => {
        const item = categoryById(section.dataset.categoryId, schema);
        section.classList.add('builder-category');
        section.id = context.categoryDomId?.(item) || `builder-category-${item.id}`;
        section.dataset.navigationCategory = item.id;
        section.tabIndex = -1;
        delete section.dataset.entryCategory;
        const heading = section.querySelector(':scope > .section-heading');
        heading.removeAttribute('data-toggle-entry-category');
        heading.removeAttribute('aria-expanded');
        heading.querySelector('h2').replaceChildren(builderPreviewName(item.label, 'category', item.id));
        section.insertBefore(builderPreviewActions('category', item), heading.nextSibling);
      });
      cache.sections.set(category.id, {signature, section, ids:sections.map(item => item.dataset.categoryId)});
    }
    sectionsUsed.add(category.id);
    if (category.kind === 'main' || !category.parent_category_id) section.dataset.mainCategory = category.id;
    (category.kind === 'main' || !category.parent_category_id ? main : related).push(section);
  };
  roots.filter((category) => !anchored.has(category.id)).forEach(append);
  schema.categories.filter((category) => !rendered.has(category.id)).forEach(append);
  for (const id of cache.sections.keys()) {
    if (!sectionsUsed.has(id)) cache.sections.delete(id);
  }
  const panels = main.filter(section => !categoryById(section.dataset.categoryId, schema).parent_category_id);
  const browser = renderMainCategoryTabs(activeCategory, root, schema, panels);
  const children = [];
  main.forEach(section => {
    if (panels.includes(section)) {
      if (!children.includes(browser)) children.push(browser);
    } else children.push(section);
  });
  reconcileChildElements(root, [...children, ...related]);
  root.querySelectorAll('[data-main-category]').forEach((section) => delete section.dataset.mainCategory);
  root.querySelectorAll('[data-main-category-tab]').forEach((tab) => {
    const id = tab.dataset.mainCategoryTab;
    tab.dataset.previewSelect = `category:${id}`;
    tab.setAttribute('aria-expanded', 'false');
    tab.title = categoryById(id, schema).label;
    tab.dataset.hoverLabel = categoryById(id, schema).label;
    tab._categoryHoverCard = builderCategoryHoverCard(id);
    tab.querySelector('span')?.removeAttribute('title');
    if (!tab._builderPreviewSelection) {
      tab.addEventListener('click', () => selectBuilderPreviewItem('category', id, true, root));
      tab._builderPreviewSelection = true;
    }
  });
  if (selected && [...root.querySelectorAll('[data-preview-actions]')].some((item) => item.dataset.previewActions === selected)) {
    const [kind, id] = selected.split(':');
    selectBuilderPreviewItem(kind, id, false, root);
    if (focusedAction) {
      const actions = [...root.querySelectorAll('[data-preview-actions]')].find((item) => item.dataset.previewActions === selected);
      const button = actions.querySelector(`[data-builder-action="${focusedAction}"]:not(:disabled)`);
      (button || [...root.querySelectorAll('[data-preview-select]')].find((item) => item.dataset.previewSelect === selected))?.focus({preventScroll:true});
    }
  } else root.dataset.selectedItem = '';
  if (state.mode === 'builder' && root === elements.builderCategories) refreshCategoryNavigation();
  cache.signature = signature;
}

/* pages/builder/global-preview.js */
// General definitions use stable preview IDs and their own caches. Dialogs and
// writes still use the original library reference/node keys.
const globalPreviewCaches = {
  categories:{schemaId:null, fields:new Map(), sections:new Map(), signature:null},
  fields:{schemaId:null, fields:new Map(), sections:new Map(), signature:null},
};
let globalDefinitionsRenderSignature = null;

function globalPreviewId(ref, key) {
  return `gp-${ref}-${Array.from(String(key), char => char.codePointAt(0).toString(16)).join('-')}`;
}

function globalPreviewModel() {
  const categories = [], targets = new Map();
  const definitions = Object.values(state.globalDefinitions?.categories || {});
  definitions.forEach((item, index) => {
    const tree = globalCategoryTree(item.definition || {});
    const root = tree.find(node => !node.parent_key) || tree[0];
    const categoryIds = new Map(tree.map(node => [node.key, globalPreviewId(item.id, `category:${node.key}`)]));
    const fieldIds = new Map(tree.flatMap(node => (node.fields || []).map(entry => [entry.key, globalPreviewId(item.id, `field:${entry.key}`)])));
    tree.forEach(node => {
      const id = categoryIds.get(node.key);
      const siblings = node === root ? definitions : tree.filter(peer => (peer.parent_key || '') === (node.parent_key || ''));
      const position = node === root ? index : siblings.indexOf(node);
      const category = {...node.definition, id, label:node.definition?.label || item.definition?.label || 'فئة عامة', kind:node.definition?.kind || 'main',
        parent_category_id:categoryIds.get(node.parent_key) || null,
        parent_field_id:fieldIds.get(node.parent_field_key || node.definition?.parent_field_key) || null,
        anchor_field_id:fieldIds.get(node.anchor_field_key) || null,
        _globalFirst:position === 0, _globalLast:position === siblings.length - 1,
        fields:(node.fields || []).map(entry => {
          const fieldId = fieldIds.get(entry.key);
          targets.set(fieldId, {kind:'field', ref:item.id, nodeKey:node.key, fieldKey:entry.key, domId:globalEmbeddedFieldTargetId(item.id, entry.key)});
          return {...(entry.definition || entry), id:fieldId};
        }),
      };
      targets.set(id, {kind:'category', ref:item.id, nodeKey:node.key, root:node === root,
        domId:node === root ? `global-definition-category-${item.id}` : `global-category-node-${item.id}-${node.key}`});
      categories.push(category);
    });
  });
  const standalone = {id:'global-standalone-preview', label:'الحقول العامة المنفصلة', kind:'main', fields:Object.values(state.globalDefinitions?.fields || {}).map(item => {
    const id = globalPreviewId(item.id, 'field');
    targets.set(id, {kind:'field', ref:item.id, standalone:true, domId:`global-definition-field-${item.id}`});
    return {...item.definition, id};
  })};
  targets.set(standalone.id, {virtual:true, domId:'global-standalone-panel'});
  return {categories, standalone, targets};
}

function globalPreviewActions(targets, kind, item, category) {
  const target = targets.get(item.id);
  const actions = document.createElement('div');
  actions.className = 'builder-actions builder-preview-actions';
  actions.dataset.previewActions = `${kind}:${item.id}`;
  actions.id = `builder-preview-actions-${item.id}`;
  actions.setAttribute('role', 'group');
  actions.setAttribute('aria-label', `إجراءات ${item.label || 'مساحة فارغة'}`);
  actions.hidden = true;
  if (!target || target.virtual) return actions;
  const remove = () => target.standalone || target.root
    ? deleteGlobalDefinition(kind, target.ref)
    : kind === 'field' ? updateEmbeddedGlobalField(target.ref, target.nodeKey, target.fieldKey, 'delete')
      : updateGlobalCategoryNode(target.ref, target.nodeKey, 'delete');
  const edit = () => target.standalone
    ? openGlobalDefinitionEditor('field', target.ref)
    : openGlobalCategoryPackageEditor(kind, target.ref, {nodeKey:target.nodeKey, fieldKey:target.fieldKey});
  const move = direction => target.standalone || target.root
    ? reorderGlobalDefinition(kind, target.ref, direction)
    : kind === 'field' ? updateEmbeddedGlobalField(target.ref, target.nodeKey, target.fieldKey, direction)
      : updateGlobalCategoryNode(target.ref, target.nodeKey, direction);
  const first = kind === 'field' ? category.fields[0]?.id === item.id : item._globalFirst;
  const last = kind === 'field' ? category.fields.at(-1)?.id === item.id : item._globalLast;
  [
    ['حذف', 'trash', remove, 'delete', false],
    ['تعديل', 'edit', edit, 'edit', false],
    ['نقل لليمين — السابق في الترتيب', 'right', () => move('up'), 'move', first, 'up'],
    ['نقل لليسار — التالي في الترتيب', 'left', () => move('down'), 'move', last, 'down'],
  ].forEach(([label, icon, handler, action, disabled, direction]) => {
    const button = globalDefinitionActionButton(label, icon, () => void handler(), action === 'delete');
    button.dataset.builderAction = `${action}-${kind}${direction ? `-${direction}` : ''}`;
    button.disabled = Boolean(disabled);
    actions.append(button);
  });
  if (target.root || target.standalone) actions.append(globalDefinitionActionButton('إضافة للتصميم', 'plus', () => void addGlobalDefinitionToSchema(kind, target.ref)));
  return actions;
}

function renderGlobalDefinitionPreviews() {
  const model = globalPreviewModel();
  const render = (root, categories, cache, suffix) => renderBuilderPreview({
    root, schema:{categories, conditions:[], app:{}}, cache, schemaId:`general-${suffix}`,
    actions:(kind, item, category) => globalPreviewActions(model.targets, kind, item, category),
    categoryDomId:item => model.targets.get(item.id)?.domId,
    decorateField:(row, field) => {
      const target = model.targets.get(field.id);
      row.id = target.domId;
      row.tabIndex = -1;
      row.dataset.globalDefinitionKind = 'field';
      row.dataset.globalDefinitionId = target.ref;
      if (target.fieldKey) row.dataset.globalFieldKey = target.fieldKey;
    },
  });
  render(elements.globalCategoryList, [...model.categories, model.standalone], globalPreviewCaches.categories, 'categories');
  elements.globalFieldList.replaceChildren();
  elements.globalFieldList.closest('.builder-panel').hidden = true;
}

/* pages/builder/general-draft.js */
// General-definition edits are a draft until the explicit Save action.
function generalDraftDirty() { return Boolean(state.generalDraftBaseline); }
function updateGeneralSaveState() {
  const dirty = generalDraftDirty();
  if (elements.builderGlobalSaveState) elements.builderGlobalSaveState.textContent = state.savingGeneralDefinitions
    ? 'جارٍ حفظ التعريفات العامة…' : dirty ? 'توجد تغييرات عامة غير محفوظة.' : 'كل التعريفات العامة محفوظة.';
  const save = document.getElementById('save-general-definitions');
  const discard = document.getElementById('discard-general-definitions');
  if (save) save.disabled = !dirty || Boolean(state.savingGeneralDefinitions || state.globalEditor);
  if (discard) discard.disabled = !dirty || Boolean(state.savingGeneralDefinitions || state.globalEditor);
}

async function requestGlobalDefinitionMutation(payload) {
  if (state.savingGeneralDefinitions) throw new Error('انتظر اكتمال حفظ التعريفات العامة.');
  if (state.mode !== 'builder' || state.builderScope !== 'global') {
    if (generalDraftDirty()) throw new Error('احفظ تغييرات التعريفات العامة أو تجاهلها أولًا.');
    const response = await fetch('/api/global-definitions', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({...payload, expected_revision:state.globalDefinitions?.revision})});
    return responseJson(response);
  }
  const collectionName = payload.kind === 'category' ? 'categories' : 'fields';
  const collection = state.globalDefinitions[collectionName];
  const ref = payload.global_ref;
  if (payload.action === 'reorder') {
    const keys = Object.keys(collection), index = keys.indexOf(ref);
    const target = index + (payload.direction === 'up' ? -1 : 1);
    if (index < 0 || target < 0 || target >= keys.length) return {global_definitions:state.globalDefinitions,moved:false};
  }
  state.generalDraftBaseline ||= deepClone(state.globalDefinitions);
  if (payload.action === 'save') {
    collection[ref] = {...collection[ref], id:ref, definition:deepClone(payload.definition)};
  } else if (payload.action === 'delete') {
    delete collection[ref];
  } else if (payload.action === 'reorder_all') {
    const keys = payload.order;
    if (!Array.isArray(keys) || keys.length !== Object.keys(collection).length || new Set(keys).size !== keys.length || keys.some(key => !Object.hasOwn(collection, key))) throw new Error('ترتيب التعريفات غير صالح.');
    state.globalDefinitions[collectionName] = Object.fromEntries(keys.map(key => [key, collection[key]]));
  } else if (payload.action === 'reorder') {
    const keys = Object.keys(collection), index = keys.indexOf(ref);
    const target = index + (payload.direction === 'up' ? -1 : 1);
    [keys[index],keys[target]] = [keys[target],keys[index]];
    state.globalDefinitions[collectionName] = Object.fromEntries(keys.map(key => [key,collection[key]]));
  }
  updateGeneralSaveState();
  return {ok:true, staged:true, moved:payload.action === 'reorder', definition:collection[ref], global_definitions:state.globalDefinitions, updated_schema_ids:[]};
}

async function saveGeneralDefinitions() {
  if (!generalDraftDirty() || state.savingGeneralDefinitions || state.globalEditor) return false;
  const target = deepClone(state.globalDefinitions);
  let confirmed = deepClone(state.generalDraftBaseline);
  const affected = new Set();
  state.savingGeneralDefinitions = true;
  updateGeneralSaveState();
  try {
    const send = async payload => {
      const response = await fetch('/api/global-definitions', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({...payload, expected_revision:confirmed.revision})});
      const result = await responseJson(response);
      confirmed = result.global_definitions;
      state.generalDraftBaseline = deepClone(confirmed);
      state.generalLoadedDefinitions = deepClone(confirmed);
      for (const id of [...(result.updated_schema_ids || []), ...(result.detached_schema_ids || [])]) affected.add(id);
    };
    for (const [kind, key] of [['category','categories'],['field','fields']]) {
      for (const [ref, item] of Object.entries(target[key])) {
        if (JSON.stringify(item.definition) !== JSON.stringify(confirmed[key][ref]?.definition)) await send({action:'save',kind,global_ref:ref,definition:item.definition});
      }
      for (const ref of Object.keys(confirmed[key])) {
        if (!target[key][ref]) await send({action:'delete',kind,global_ref:ref});
      }
      const order = Object.keys(target[key]);
      if (JSON.stringify(order) !== JSON.stringify(Object.keys(confirmed[key]))) await send({action:'reorder_all',kind,order});
    }
    const changes = state.generalDraftHistory || [];
    state.generalDraftBaseline = null;
    state.generalDraftHistory = [];
    state.generalLoadedDefinitions = null;
    state.globalDefinitions = confirmed;
    if (affected.size) await refreshAdvancedWorkspace({reloadSchema:affected.has(state.activeSchemaId)});
    renderGlobalDefinitions();
    rememberBuilderHistory('__global__','التعريفات العامة',changes);
    showToast('تم حفظ التعريفات العامة.');
    return true;
  } catch (error) {
    // Successful requests remain committed; retry compares the remaining draft
    // with the last acknowledged revision, so it never repeats a deletion.
    state.globalDefinitions = {...target, revision:confirmed.revision};
    state.generalDraftBaseline = confirmed;
    if (affected.size) await refreshAdvancedWorkspace({reloadSchema:affected.has(state.activeSchemaId)});
    showToast(`تعذّر إكمال الحفظ. التغييرات المتبقية محفوظة كمسودة: ${error.message}`, 'error');
    return false;
  } finally {
    state.savingGeneralDefinitions = false;
    updateGeneralSaveState();
  }
}

async function discardGeneralDefinitions() {
  if (!generalDraftDirty() || state.savingGeneralDefinitions || state.globalEditor) return;
  if (!(await requestConfirmation('تجاهل التغييرات العامة غير المحفوظة؟', {title:'تجاهل التغييرات',confirmLabel:'تجاهل'}))) return;
  state.globalDefinitions = deepClone(state.generalLoadedDefinitions || state.generalDraftBaseline);
  state.generalDraftBaseline = null;
  state.generalLoadedDefinitions = null;
  state.generalDraftHistory = [];
  renderGlobalDefinitions();
  updateGeneralSaveState();
}

document.getElementById('save-general-definitions')?.addEventListener('click', () => void saveGeneralDefinitions());
document.getElementById('discard-general-definitions')?.addEventListener('click', () => void discardGeneralDefinitions());

/* pages/entry/entry.js */
function conditionsFor(targetType, targetId, schema = state.schema) {
  return (schema.conditions || []).filter(
    (condition) =>
      condition.target_type === targetType && condition.target_id === targetId,
  );
}

function conditionValue(condition, mainValues, rowValues = null) {
  const sourceCategory = fieldCategory(condition.source_field_id, state.schema);
  if (
    sourceCategory?.kind === "repeatable" &&
    rowValues &&
    Object.prototype.hasOwnProperty.call(rowValues, condition.source_field_id)
  ) {
    return rowValues[condition.source_field_id];
  }
  return mainValues[condition.source_field_id] ?? "";
}

function normalizedComparison(value) {
  return String(value ?? "")
    .trim()
    .toLocaleLowerCase();
}

function conditionValueIsEmpty(field, value) {
  if (field?.type === "checkbox_group") {
    return !Array.isArray(value) || value.length === 0;
  }

  if (field?.type === "file") {
    if (value && typeof value === "object") {
      return !(value.stored_path || value.upload);
    }

    return String(value || "").trim() === "";
  }

  return value == null || String(value).trim() === "";
}

function conditionMatches(condition, mainValues, rowValues = null) {
  const sourceField = fieldById(condition.source_field_id, state.schema);

  if (!sourceField) {
    return false;
  }

  const rawActual = conditionValue(condition, mainValues, rowValues);

  const operator = condition.operator;
  const expected = String(condition.value ?? "");

  const empty = conditionValueIsEmpty(sourceField, rawActual);

  let result = false;

  if (operator === "empty") {
    result = empty;
  } else if (operator === "not_empty") {
    result = !empty;
  } else if (empty) {
    result = false;
  } else if (sourceField.type === "checkbox") {
    const actual =
      rawActual === true ||
      ["true", "1", "نعم", "yes", "on"].includes(
        String(rawActual).toLocaleLowerCase(),
      )
        ? "true"
        : "false";

    result = operator === "equals" ? actual === expected : actual !== expected;
  } else if (["select", "yes_no"].includes(sourceField.type)) {
    const actual = optionIdForValue(sourceField, rawActual);

    result = operator === "equals" ? actual === expected : actual !== expected;
  } else if (sourceField.type === "checkbox_group") {
    const rawValues = Array.isArray(rawActual)
      ? rawActual
      : String(rawActual || "")
          .split(" | ")
          .map((item) => item.trim())
          .filter(Boolean);

    const actualIds = new Set(
      rawValues.map((item) => optionIdForValue(sourceField, item)),
    );

    result =
      operator === "contains"
        ? actualIds.has(expected)
        : !actualIds.has(expected);
  } else if (sourceField.type === "number") {
    if (workspace.isTextNumber(sourceField)) {
      const actualText = normalizedComparison(workspace.rawNumber(rawActual));
      const expectedText = normalizedComparison(expected);
      result =
        {
          equals: actualText === expectedText,
          not_equals: actualText !== expectedText,
          contains: actualText.includes(expectedText),
          not_contains: !actualText.includes(expectedText),
        }[operator] ?? false;
    } else {
      const actualNumber = Number(workspace.rawNumber(rawActual));
      const expectedNumber = Number(expected);
      if (Number.isFinite(actualNumber) && Number.isFinite(expectedNumber)) {
        result =
          {
            equals: actualNumber === expectedNumber,
            not_equals: actualNumber !== expectedNumber,
            greater_than: actualNumber > expectedNumber,
            greater_or_equal: actualNumber >= expectedNumber,
            less_than: actualNumber < expectedNumber,
            less_or_equal: actualNumber <= expectedNumber,
          }[operator] ?? false;
      }
    }
  } else if (sourceField.type.startsWith("date_")) {
    const actualDate = String(rawActual || "");

    result =
      {
        equals: actualDate === expected,
        not_equals: actualDate !== expected,
        before: actualDate < expected,
        after: actualDate > expected,
        on_or_before: actualDate <= expected,
        on_or_after: actualDate >= expected,
      }[operator] ?? false;
  } else {
    const actualText = normalizedComparison(rawActual);
    const expectedText = normalizedComparison(expected);

    result =
      {
        equals: actualText === expectedText,
        not_equals: actualText !== expectedText,
        contains: actualText.includes(expectedText),
        not_contains: !actualText.includes(expectedText),
      }[operator] ?? false;
  }

  return condition.negate ? !result : result;
}

function targetVisible(targetType, targetId, mainValues, rowValues = null) {
  const conditions = conditionsFor(targetType, targetId);

  if (!conditions.length) {
    return true;
  }

  const groups = new Map();

  conditions.forEach((condition) => {
    const groupId = condition.group_id || `legacy-${targetType}-${targetId}`;

    if (!groups.has(groupId)) {
      groups.set(groupId, []);
    }

    groups.get(groupId).push(condition);
  });

  return [...groups.values()].some((groupConditions) =>
    groupConditions.every((condition) =>
      conditionMatches(condition, mainValues, rowValues),
    ),
  );
}

function isPersianLeapYear(year) {
  return [1, 5, 9, 13, 17, 22, 26, 30].includes(year % 33);
}

function isHijriLeapYear(year) {
  return [2, 5, 7, 10, 13, 16, 18, 21, 24, 26, 29].includes(year % 30);
}

function isGregorianLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function calendarMonthLength(type, year, month) {
  if (type === "date_gregorian") {
    if ([1, 3, 5, 7, 8, 10, 12].includes(month)) {
      return 31;
    }
    if (month === 2) {
      return isGregorianLeapYear(year) ? 29 : 28;
    }
    return 30;
  }
  if (type === "date_hijri") {
    if (month % 2 === 1) {
      return 30;
    }
    return month === 12 && isHijriLeapYear(year) ? 30 : 29;
  }
  if (month <= 6) {
    return 31;
  }
  if (month <= 11) {
    return 30;
  }
  return isPersianLeapYear(year) ? 30 : 29;
}

function appendBlankOption(select, label) {
  const option = document.createElement("option");
  option.value = "";
  option.textContent = label;
  select.append(option);
}

function calendarYearRange(type) {
  if (type === "date_gregorian") {
    return [1800, 2200];
  }
  if (type === "date_hijri") {
    return [1200, 1700];
  }
  return [1200, 1600];
}

function maximumSelectableCalendarDay(type, yearValue, monthValue) {
  const year = Number(yearValue);
  const month = Number(monthValue);

  if (!month) {
    return 31;
  }

  if (year) {
    return calendarMonthLength(type, year, month);
  }

  if (type === "date_gregorian") {
    if (month === 2) {
      return 29;
    }
    return [4, 6, 9, 11].includes(month) ? 30 : 31;
  }

  if (type === "date_hijri") {
    return month % 2 === 1 || month === 12 ? 30 : 29;
  }

  return month <= 6 ? 31 : 30;
}

function populateCalendarDays(daySelect, maximum, previousValue = "") {
  daySelect.replaceChildren();
  appendBlankOption(daySelect, "اليوم");

  for (let value = 1; value <= maximum; value += 1) {
    const option = document.createElement("option");
    const padded = String(value).padStart(2, "0");
    option.value = padded;
    option.textContent = padded;
    daySelect.append(option);
  }

  if (previousValue && Number(previousValue) <= maximum) {
    daySelect.value = String(previousValue).padStart(2, "0");
  }
}

function fillCalendarDays(group) {
  const hidden = group.querySelector("[data-value-control]");
  const type = group.dataset.calendarType;
  const year = Number(group.querySelector("[data-calendar-year]").value);
  const month = Number(group.querySelector("[data-calendar-month]").value);
  const daySelect = group.querySelector("[data-calendar-day]");
  const previous = daySelect.value;
  populateCalendarDays(
    daySelect,
    maximumSelectableCalendarDay(type, year, month),
    previous,
  );
  syncCalendarDate(group, hidden);
}

function syncCalendarDate(
  group,
  hidden = group.querySelector("[data-value-control]"),
) {
  const type = group.dataset.calendarType;
  const year = group.querySelector("[data-calendar-year]").value;
  const month = group.querySelector("[data-calendar-month]").value;
  const day = group.querySelector("[data-calendar-day]").value;
  hidden.value = year && month && day ? `${year}-${month}-${day}` : "";
  const readable = group.parentElement?.querySelector(
    "[data-calendar-readable]",
  );
  if (readable) {
    const monthName = CALENDAR_MONTH_NAMES[type]?.[Number(month) - 1];
    readable.textContent =
      year && monthName && day
        ? `${Number(day)} ${monthName} ${year} ${CALENDAR_SUFFIXES[type]}`
        : "";
  }
  hidden.dispatchEvent(new Event("change", { bubbles: true }));
}

function createCalendarControl(field, scope, categoryId) {
  const group = document.createElement("div");
  group.className = "calendar-control";
  group.dataset.calendarType = field.type;
  const hidden = document.createElement("input");
  hidden.type = "hidden";
  setControlDataset(hidden, field, scope, categoryId);

  const year = document.createElement("select");
  year.className = "control";
  year.dataset.calendarYear = "";
  year.setAttribute("aria-label", `${field.label} — السنة`);
  appendBlankOption(year, "السنة");
  const [firstYear, lastYear] = calendarYearRange(field.type);
  for (let value = firstYear; scope !== "builder-preview" && value <= lastYear; value += 1) {
    const option = document.createElement("option");
    option.value = String(value);
    option.textContent = String(value);
    year.append(option);
  }

  const month = document.createElement("select");
  month.className = "control";
  month.dataset.calendarMonth = "";
  month.setAttribute("aria-label", `${field.label} — الشهر`);
  appendBlankOption(month, "الشهر");
  for (let index = 0; scope !== "builder-preview" && index < 12; index += 1) {
    const option = document.createElement("option");
    option.value = String(index + 1).padStart(2, "0");
    option.textContent = String(index + 1).padStart(2, "0");
    month.append(option);
  }

  const day = document.createElement("select");
  day.className = "control";
  day.dataset.calendarDay = "";
  day.setAttribute("aria-label", `${field.label} — اليوم`);
  if (scope === "builder-preview") appendBlankOption(day, "");
  else populateCalendarDays(day, 31);

  day.addEventListener("change", () => syncCalendarDate(group));
  month.addEventListener("change", () => fillCalendarDays(group));
  year.addEventListener("change", () => fillCalendarDays(group));
  day.addEventListener("keydown", (event) => {
    if (event.key !== "-") return;
    event.preventDefault();
    event.stopPropagation();
    // A separator never moves focus; use Tab or click another date part.
  });
  month.addEventListener("keydown", (event) => {
    if (event.key !== "-") return;
    event.preventDefault();
    event.stopPropagation();
    // A separator never moves focus; use Tab or click another date part.
  });
  year.addEventListener("keydown", (event) => {
    if (event.key === "-" || event.key === "Enter") { event.preventDefault(); event.stopPropagation(); }
  });
  // Value changes never schedule focus. Only explicit keyboard navigation moves it.
  group.append(hidden, day, month, year);
  hidden._focusControl = day;
  return { root: group, control: hidden };
}

function setControlDataset(control, field, scope, categoryId) {
  control.dataset.valueControl = "";
  control.dataset.fieldId = field.id;
  control.dataset.scope = scope;
  control.dataset.categoryId = categoryId;
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.addEventListener("load", () => {
      const result = String(reader.result || "");
      const separator = result.indexOf(",");
      resolve(separator >= 0 ? result.slice(separator + 1) : result);
    });
    reader.addEventListener("error", () => {
      reject(new Error(`تعذّر قراءة الملف: ${file.name}`));
    });
    reader.readAsDataURL(file);
  });
}

function storedFilename(path) {
  return (
    String(path || "")
      .replace(/\\/g, "/")
      .split("/")
      .pop() || ""
  );
}

function refreshProfileImagePreview(hidden) {
  const root = hidden.closest(".attachment-control");
  const image = root?.querySelector("[data-profile-image-preview]");
  const empty = root?.querySelector("[data-profile-image-empty]");
  if (!image || !empty) {
    return;
  }

  if (hidden._profilePreviewUrl) {
    URL.revokeObjectURL(hidden._profilePreviewUrl);
    hidden._profilePreviewUrl = "";
  }

  let source = "";
  if (hidden._selectedFile) {
    source = URL.createObjectURL(hidden._selectedFile);
    hidden._profilePreviewUrl = source;
  } else if (hidden.value && isImageAttachment(hidden.value)) {
    source = attachmentApiUrl(hidden.value);
  }

  image.hidden = !source;
  empty.hidden = Boolean(source);
  image.src = source;
}

function attachmentHoverDetails(control) {
  const file = control._selectedFile;
  const name = control._uploadName || file?.name || storedFilename(control.value);
  if (!name) return null;
  const field = fieldById(control.dataset.fieldId, state.schema);
  const category = categoryById(control.dataset.categoryId, state.schema);
  const cardTitle = control.closest('.related-card')?.querySelector('[data-related-title]')?.textContent?.trim();
  const extension = name.match(/\.([^.]+)$/)?.[1]?.toUpperCase();
  const metadata = [
    ['الحقل', field?.label], ['الفئة', category?.label], ['البطاقة', cardTitle],
    ['النوع', extension || file?.type],
    ['الحالة', file ? 'مرفق جديد — غير محفوظ' : 'مرفق محفوظ'],
  ];
  if (file) metadata.push(['الحجم', `${new Intl.NumberFormat('ar').format(file.size)} بايت`]);
  return {name, details:'', metadata:metadata.filter(([,value]) => value)};
}

function refreshFileSummary(hidden) {
  const root = hidden.closest(".attachment-control");
  const summary = root.querySelector("[data-file-summary]");
  const open = root.querySelector("[data-open-file]");
  const remove = root.querySelector("[data-remove-file]");
  const file = hidden._selectedFile;
  const path = hidden.value;
  const nameInput = root.querySelector("[data-file-name]");
  const browse = root.querySelector("[data-browse-file]");
  if (nameInput) {
    const selected = Boolean(file || path);
    nameInput.readOnly = selected;
    if (selected) nameInput.value = hidden._uploadName || file?.name || storedFilename(path);
    nameInput.title = nameInput.value;
    nameInput.dataset.hoverLabel = nameInput.value || 'اسم المرفق';
    nameInput._attachmentHoverCard = () => attachmentHoverDetails(hidden);
    browse.hidden = selected;
    hidden._focusControl = selected ? nameInput : browse;
    root.dataset.hasFile = String(selected);
  }
  summary.textContent = file
    ? `ملف جديد: ${file.name}`
    : path
      ? `ملف محفوظ: ${storedFilename(path)}`
      : "";
  open.hidden = !path || Boolean(file);
  remove.hidden = !path && !file;
  summary.closest(".attachment-summary").hidden = true;
  root._attachmentHoverCard = () => attachmentHoverDetails(hidden);
  refreshProfileImagePreview(hidden);
}

function createFileControl(field, scope, categoryId) {
  const root = document.createElement("div");
  root.className = "attachment-control";
  const profileImage = ["profile", "card"].includes(field.image_display) && scope !== "search";
  root.classList.toggle("profile-image-control", profileImage);
  const hidden = document.createElement("input");
  hidden.type = "hidden";
  setControlDataset(hidden, field, scope, categoryId);

  const picker = document.createElement("input");
  picker.type = "file";
  picker.className = "control";
  picker.dataset.filePicker = "";
  picker.hidden = true;
  picker.tabIndex = -1;
  const browse = document.createElement("button");
  browse.type = "button";
  browse.className = "button button-secondary";
  browse.dataset.browseFile = "";
  browse.textContent = "تصفح";
  browse.setAttribute("aria-label", `تصفح — ${field.label}`);
  browse.addEventListener("click", () => picker.click());
  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.className = "control";
  nameInput.dataset.fileName = "";
  nameInput.placeholder = "اسم المرفق";
  nameInput.setAttribute("aria-label", `اسم المرفق — ${field.label}`);
  hidden._focusControl = browse;
  if (profileImage) {
    picker.accept = "image/*";
  }

  const preview = document.createElement("div");
  if (profileImage) {
    preview.className = "profile-image-preview-frame";
    const image = document.createElement("img");
    image.dataset.profileImagePreview = "";
    image.alt = field.label;
    image.hidden = true;
    const empty = document.createElement("span");
    empty.dataset.profileImageEmpty = "";
    empty.setAttribute("aria-hidden", "true");
    preview.append(image, empty);
  }
  const summary = document.createElement("div");
  summary.className = "attachment-summary";
  const summaryText = document.createElement("span");
  summaryText.dataset.fileSummary = "";
  const actions = document.createElement("div");
  actions.className = "attachment-actions";
  const open = document.createElement("button");
  open.type = "button";
  open.className = "button button-secondary";
  open.dataset.openFile = "";
  open.append(actionIcon("open"), document.createTextNode("فتح الملف"));
  open.hidden = true;
  const remove = document.createElement("button");
  remove.type = "button";
  remove.className = "button button-icon button-danger-quiet";
  remove.dataset.removeFile = "";
  remove.append(actionIcon("trash"));
  remove.title = "حذف المرفق";
  remove.setAttribute("aria-label", "حذف المرفق");
  remove.hidden = true;
  actions.append(open);
  summary.append(summaryText, actions);

  picker.addEventListener("change", () => {
    const file = picker.files?.[0] || null;
    const validProfileImage =
      !file ||
      !profileImage ||
      file.type.startsWith("image/") ||
      /\.(avif|bmp|gif|jpe?g|png|webp)$/i.test(file.name);
    if (!validProfileImage) {
      picker.value = "";
      hidden._selectedFile = null;
      showToast("اختر ملف صورة صالحًا للمعاينة.", "error");
    } else if (file && file.size > MAX_ATTACHMENT_BYTES) {
      picker.value = "";
      hidden._selectedFile = null;
      showToast("حجم الملف يتجاوز 100 ميغابايت.", "error");
    } else {
      hidden._selectedFile = file;
      const requested = nameInput.value.trim();
      const extension = file?.name.match(/\.[^.]+$/)?.[0] || "";
      hidden._uploadName = file && requested
        ? (requested.toLowerCase().endsWith(extension.toLowerCase()) ? requested : requested + extension)
        : file?.name || "";
    }
    refreshFileSummary(hidden);
    hidden.dispatchEvent(new Event("change", { bubbles: true }));
  });
  open.addEventListener("click", () => {
    if (hidden.value) {
      const url = isImageAttachment(hidden.value)
        ? attachmentViewerUrl(hidden.value)
        : attachmentApiUrl(hidden.value);
      window.open(url, "_blank", "noopener");
    }
  });
  remove.addEventListener("click", async () => {
    if (!(await requestConfirmation("هل تريد حذف المرفق؟", { title: "حذف المرفق", confirmLabel: "حذف" }))) return;
    hidden.value = "";
    hidden._selectedFile = null;
    hidden._uploadName = "";
    nameInput.value = "";
    picker.value = "";
    refreshFileSummary(hidden);
    hidden.dispatchEvent(new Event("change", { bubbles: true }));
  });
  const fileRow = document.createElement("div");
  fileRow.className = "attachment-line";
  fileRow.append(browse, nameInput, remove);
  if (profileImage) {
    root.append(hidden, preview, picker, fileRow, summary);
  } else {
    root.append(hidden, picker, fileRow, summary);
  }
  refreshFileSummary(hidden);
  return { root, control: hidden };
}

function checkboxGroupValues(control) {
  return [
    ...control
      .closest(".checkbox-group-control")
      .querySelectorAll('input[type="checkbox"][data-option-id]:checked'),
  ].map((input) => input.dataset.optionId);
}

function syncCheckboxGroupControl(control) {
  control.value = JSON.stringify(checkboxGroupValues(control));
}

function controlValue(control) {
  const field = fieldById(control.dataset.fieldId, state.schema);
  if (control.dataset.editableList === "true") {
    const typed = String(control.value || "").trim();
    const match = activeOptions(field).find((option) => (
      option.id === typed || normalizedComparison(option.label) === normalizedComparison(typed)
    ));
    return match?.id || typed;
  }
  if (control.multiple) {
    return [...control.selectedOptions].map((option) => option.value).filter(Boolean);
  }
  if (field?.type === "checkbox") {
    return control.tagName === "SELECT" ? control.value : control.checked;
  }
  if (field?.type === "checkbox_group") {
    return checkboxGroupValues(control);
  }
  if (field?.type === "number") {
    return workspace.rawNumber(control.value);
  }
  return control.value;
}

function createCheckboxGroupControl(field, scope, categoryId) {
  const root = document.createElement("div");
  root.className = "checkbox-group-control";
  const control = document.createElement("input");
  control.type = "hidden";
  setControlDataset(control, field, scope, categoryId);
  root.append(control);
  for (const optionValue of activeOptions(field)) {
    const label = document.createElement("label");
    label.className = "check-field checkbox-option";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.dataset.optionId = optionValue.id;
    const text = document.createElement("span");
    text.textContent = optionValue.label;
    label.append(input, text);
    root.append(label);
  }
  root.addEventListener("change", () => syncCheckboxGroupControl(control));
  syncCheckboxGroupControl(control);
  return { root, control };
}

function localDateTimeControlValue(value) {
  if (!value) {
    return "";
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "";
  }
  const pad = (number) => String(number).padStart(2, "0");
  return (
    `${parsed.getFullYear()}-${pad(parsed.getMonth() + 1)}-` +
    `${pad(parsed.getDate())}T${pad(parsed.getHours())}:${pad(parsed.getMinutes())}`
  );
}

function setSystemFieldValue(control, field) {
  const metadata = state.currentRecordMetadata || {};
  if (field.type === "system_record_code") {
    control.value = metadata.record_code || elements.recordCode.value || "";
    return;
  }
  const key = field.type === "system_created_at"
    ? "created_at"
    : "updated_at";
  control.value = localDateTimeControlValue(metadata[key]);
}

function refreshSystemFieldControls() {
  elements.recordForm
    .querySelectorAll("[data-value-control]")
    .forEach((control) => {
      const field = fieldById(control.dataset.fieldId, state.schema);
      if (isSystemField(field)) {
        setSystemFieldValue(control, field);
      }
    });
}

function createControl(field, scope, categoryId) {
  const searchScope = ["search", "full-search"].includes(scope);
  if (isSystemField(field)) {
    const control = document.createElement("input");
    control.className = "control system-field-control";
    control.readOnly = !searchScope;
    setControlDataset(control, field, scope, categoryId);
    if (field.type === "system_record_code") {
      control.type = "text";
      control.dir = "ltr";
      if (!searchScope) {
        control.dataset.copySystemRecordCode = "";
        control.title = "انقر لنسخ ID السجل";
        control.setAttribute("aria-label", `${field.label} — انقر للنسخ`);
      }
    } else {
      control.type = "datetime-local";
      control.dir = "ltr";
    }
    if (!searchScope) setSystemFieldValue(control, field);
    return { root: control, control };
  }
  if (field.type === "user_name") {
    const control = document.createElement("input");
    control.type = "text";
    control.className = "control user-name-field-control";
    setControlDataset(control, field, scope, categoryId);
    if (!searchScope) {
      control.value = ["current_on_save", "current_on_checkbox"].includes(field.user_value_mode)
        ? ""
        : state.auditUsers?.current_user || "";
      control.readOnly =
        field.user_editable === false ||
        ["current_on_save", "current_on_checkbox"].includes(field.user_value_mode);
    }
    return { root: control, control };
  }
  if (["date_gregorian", "date_hijri", "date_persian"].includes(field.type)) {
    return createCalendarControl(field, scope, categoryId);
  }
  if (field.type === "file") {
    return createFileControl(field, scope, categoryId);
  }
  if (field.type === "checkbox_group") {
    return createCheckboxGroupControl(field, scope, categoryId);
  }
  if (field.type === "checkbox") {
    if (searchScope) {
      const control = document.createElement("select");
      control.className = "control";
      setControlDataset(control, field, scope, categoryId);
      appendBlankOption(control, "— الكل —");
      const checked = document.createElement("option");
      checked.value = "true";
      checked.textContent = checkboxDisplayMeaning(field, true);
      const unchecked = document.createElement("option");
      unchecked.value = "false";
      unchecked.textContent = checkboxDisplayMeaning(field, false);
      control.append(checked, unchecked);
      return { root: control, control };
    }
    const root = document.createElement("label");
    root.className = "check-field standalone-check";
    const control = document.createElement("input");
    control.type = "checkbox";
    setControlDataset(control, field, scope, categoryId);
    const text = document.createElement("span");
    text.textContent = field.label;
    text.title = field.label;
    root.append(control, text);
    return { root, control };
  }

  if (["select", "yes_no"].includes(field.type) && !searchScope) {
    const root = document.createElement("div");
    root.className = "editable-list-control";
    const control = document.createElement("input");
    control.type = "text";
    control.className = "control";
    control.placeholder = field.placeholder || "اختر أو اكتب قيمة";
    control.dataset.editableList = "true";
    setControlDataset(control, field, scope, categoryId);
    control.required = field.required === true;
    const menu = document.createElement("div");
    menu.className = "editable-list-menu";
    menu.id = `list-${field.id}-${Math.random().toString(16).slice(2)}`;
    menu.setAttribute("role", "listbox");
    menu.hidden = true;
    control.setAttribute("role", "combobox");
    control.setAttribute("aria-autocomplete", "list");
    control.setAttribute("aria-controls", menu.id);
    control.setAttribute("aria-expanded", "false");

    const closeMenu = () => {
      menu.hidden = true;
      control.setAttribute("aria-expanded", "false");
      control.removeAttribute("aria-activedescendant");
    };
    const chooseOption = (option) => {
      control.value = option.label;
      control.dataset.selectedOptionId = option.id;
      clearFieldValidation(control);
      closeMenu();
      control.dispatchEvent(new Event("change", { bubbles: true }));
    };
    const renderMenu = (open = true) => {
      const typed = String(control.value || "").trim();
      const normalizedTyped = normalizedComparison(typed);
      const options = allowedOptionsForControl(control);
      const matches = options.filter((option) => (
        !normalizedTyped || normalizedComparison(option.label).includes(normalizedTyped)
      ));
      menu.replaceChildren();
      control.dataset.menuIndex = "-1";
      matches.forEach((option, index) => {
        const item = document.createElement("button");
        item.type = "button";
        item.tabIndex = -1;
        item.className = "editable-list-option";
        item.id = `${menu.id}-option-${index}`;
        item.dataset.listOptionId = option.id;
        item.setAttribute("role", "option");
        item.textContent = option.label;
        item.addEventListener("pointerdown", (event) => event.preventDefault());
        item.addEventListener("mousedown", (event) => event.preventDefault());
        item.addEventListener("click", () => chooseOption(option));
        menu.append(item);
      });
      const dependencyReady = !field.option_filter || Boolean(
        dependencyTokenForControl(control),
      );
      if (typed && matches.length === 0 && dependencyReady) {
        const add = document.createElement("button");
        add.type = "button";
        add.tabIndex = -1;
        add.className = "editable-list-option editable-list-create-option";
        add.dataset.addInlineListOption = field.id;
        add.setAttribute("role", "option");
        add.textContent = `إضافة «${typed}» إلى القائمة`;
        add.addEventListener("pointerdown", (event) => event.preventDefault());
        add.addEventListener("mousedown", (event) => event.preventDefault());
        add.addEventListener("click", () => void addRuntimeListOption(control, add));
        menu.append(add);
      }
      const shouldOpen = open && menu.children.length > 0;
      menu.hidden = !shouldOpen;
      control.setAttribute("aria-expanded", String(shouldOpen));
    };
    const moveActive = (direction) => {
      const items = [...menu.querySelectorAll(".editable-list-option")];
      if (!items.length) return;
      let index = Number(control.dataset.menuIndex || -1);
      index = direction > 0
        ? (index + 1) % items.length
        : (index <= 0 ? items.length - 1 : index - 1);
      items.forEach((item, itemIndex) => {
        const active = itemIndex === index;
        item.classList.toggle("is-active", active);
        item.setAttribute("aria-selected", String(active));
      });
      control.dataset.menuIndex = String(index);
      control.setAttribute("aria-activedescendant", items[index].id || "");
      items[index].scrollIntoView({ block: "nearest" });
    };
    control.addEventListener("focus", () => renderMenu(true));
    control.addEventListener("input", () => {
      control.dataset.selectedOptionId = "";
      renderMenu(true);
    });
    control.addEventListener("keydown", (event) => {
      if (["ArrowDown", "ArrowUp"].includes(event.key)) {
        event.preventDefault();
        if (menu.hidden) renderMenu(true);
        moveActive(event.key === "ArrowDown" ? 1 : -1);
        return;
      }
      if (event.key === "Enter" && !menu.hidden) {
        const items = [...menu.querySelectorAll(".editable-list-option")];
        const active = items[Number(control.dataset.menuIndex || -1)];
        if (active) {
          event.preventDefault();
          active.click();
        }
        return;
      }
      if (event.key === "Escape") closeMenu();
    });
    control._renderListMenu = renderMenu;
    control._closeListMenu = closeMenu;
    control._chooseListOption = chooseOption;
    root.append(control, menu);
    return { root, control };
  }

  const control =
    field.type === "textarea"
      ? document.createElement("textarea")
      : field.type === "select" || field.type === "yes_no"
        ? document.createElement("select")
        : document.createElement("input");
  control.className = "control";
  control.placeholder = field.placeholder || "";
  setControlDataset(control, field, scope, categoryId);

  if (control.tagName === "TEXTAREA") {
    control.rows = 3;
  } else if (control.tagName === "SELECT") {
    const multiValueSearch = scope === "full-search" && ["select", "yes_no"].includes(field.type);
    if (multiValueSearch) {
      control.multiple = true;
      control.size = Math.min(8, Math.max(3, activeOptions(field).length));
      control.classList.add("modifier-free-multi-select");
    } else {
      appendBlankOption(control, "— اختر —");
    }
    for (const optionValue of activeOptions(field)) {
      const option = document.createElement("option");
      option.value = optionValue.id;
      option.textContent = optionValue.label;
      control.append(option);
    }
  } else if (field.type === "number") {
    control.type = "text";
    control.dir = "ltr";
    control.inputMode = workspace.isTextNumber(field) ? "text" : "decimal";
    control.dataset.numberControl = "true";
    control.addEventListener("focus", () => {
      control.value = workspace.rawNumber(control.value);
    });
    control.addEventListener("blur", () => {
      control.value = workspace.formatNumber(control.value, field);
    });
  } else {
    control.type = "text";
  }
  if (field.required && control.type !== "hidden") {
    control.required = true;
  }
  return { root: control, control };
}

function checkboxDisplayMeaning(field, value) {
  const checked = value === true || ["true", "1", "نعم", "yes", "on"].includes(String(value ?? "").toLocaleLowerCase());
  return checked ? (field.checkbox_true_label || "نعم") : (field.checkbox_false_label || "لا");
}

function applyFieldLineStart(element, field, width) {
  if (!field.start_new_line) return;
  element.classList.add("field-start-new-line");
  element.style.setProperty("--field-span", width === "full" ? "6" : width);
}

function createFieldElement(field, scope, categoryId) {
  const wrapper = document.createElement("div");
  let width = ({ normal: "1", wide: "4", long: "4" }[field.width] || field.width || "1");
  if (field.type === "file" && width !== "full") width = String(Math.max(2, Number(width) || 2));
  if (["profile", "card"].includes(field.image_display)) width = "1";
  wrapper.className = `field field-${width}`;
  applyFieldLineStart(wrapper, field, width);
  if (["profile", "card"].includes(field.image_display)) {
    wrapper.classList.add("profile-image-field");
  }
  wrapper.dataset.fieldWrapper = field.id;
  if (field.type === 'spacer') {
    wrapper.classList.add('layout-spacer');
    wrapper.setAttribute('aria-hidden', 'true');
    return wrapper;
  }
  const label = document.createElement("label");
  const generatedId = `control-${field.id}-${Math.random().toString(16).slice(2)}`;
  label.htmlFor = generatedId;
  label.textContent = field.label;
  label.title = field.label;
  if (field.required) {
    const required = document.createElement("span");
    required.className = "required-mark";
    required.textContent = "*";
    label.append(required);
  }
  const { root, control } = createControl(field, scope, categoryId);
  const focusControl = control._focusControl || control;
  focusControl.id = generatedId;
  let surface = root;
  if (root.matches("input, select, textarea")) {
    surface = document.createElement("div");
    surface.append(root);
  }
  surface.classList.add("entry-control-surface");
  if (field.type === "checkbox" && !["search", "full-search"].includes(scope)) {
    wrapper.classList.add("checkbox-entry-field");
    control.required = Boolean(field.required);
    const labelSpace = document.createElement('span');
    labelSpace.className = 'checkbox-label-space';
    labelSpace.setAttribute('aria-hidden', 'true');
    labelSpace.textContent = '\u00a0';
    wrapper.append(labelSpace, surface);
  } else wrapper.append(label, surface);
  return wrapper;
}

async function addRuntimeListOption(control, triggerButton = null) {
  const field = fieldById(control?.dataset.fieldId, state.schema);
  const label = String(control?.value || "").trim();
  if (!control || !field || !label) return;
  if (triggerButton) triggerButton.disabled = true;
  try {
    const dependencyToken = dependencyTokenForControl(control);
    const response = await fetch("/api/schema/options", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field_id: field.id, label, dependency_token: dependencyToken }),
    });
    const result = await responseJson(response);
    if (!(field.options || []).some((option) => option.id === result.option.id)) {
      field.options = [...(field.options || []), result.option];
    }
    if (field.option_filter && result.dependency_token) {
      field.option_filter.mappings ||= {};
      const mapping = new Set(field.option_filter.mappings[result.dependency_token] || []);
      mapping.add(result.option.id);
      field.option_filter.mappings[result.dependency_token] = [...mapping];
    }
    state.schema.revision = result.revision;
    control._chooseListOption?.(result.option);
    control._closeListMenu?.();
    showToast("تمت إضافة القيمة إلى خيارات القائمة.");
  } catch (error) {
    showToast(error.message, "error");
  } finally {
    if (triggerButton) triggerButton.disabled = false;
  }
}
function fieldValidationMessage(control) {
  const field = fieldById(control.dataset.fieldId, state.schema);

  if (!field) {
    return "";
  }

  if (control.validity.valueMissing) {
    return `الحقل «${field.label}» مطلوب.`;
  }

  if (control.validity.badInput) {
    return `يجب إدخال رقم صالح في الحقل «${field.label}».`;
  }

  if (control.validity.rangeUnderflow) {
    return `قيمة «${field.label}» يجب ألا تقل عن ${control.min}.`;
  }

  if (control.validity.rangeOverflow) {
    return `قيمة «${field.label}» يجب ألا تزيد على ${control.max}.`;
  }

  if (control.validity.stepMismatch) {
    return field.validation?.integer_only
      ? `يجب إدخال عدد صحيح في الحقل «${field.label}».`
      : `قيمة الحقل «${field.label}» غير صالحة.`;
  }

  if (field.type === "number" && control.value.trim()) {
    const raw = workspace.rawNumber(control.value);
    if (workspace.isTextNumber(field)) {
      const allowed = field.number_behavior?.allowed_special_characters || "";
      const validCharacters = [...raw].every(
        (character) => /[0-9]/.test(character) || allowed.includes(character),
      );
      if (!validCharacters || !/[0-9]/.test(raw)) {
        return `قيمة «${field.label}» تحتوي أحرفًا أو رموزًا غير مسموحة.`;
      }
    } else {
      const number = Number(raw);
      if (!Number.isFinite(number)) {
        return `يجب إدخال رقم صالح في الحقل «${field.label}».`;
      }
      if (field.validation?.integer_only && !Number.isInteger(number)) {
        return `يجب إدخال عدد صحيح في الحقل «${field.label}».`;
      }
      if (field.validation?.min != null && number < field.validation.min) {
        return `قيمة «${field.label}» يجب ألا تقل عن ${field.validation.min}.`;
      }
      if (field.validation?.max != null && number > field.validation.max) {
        return `قيمة «${field.label}» يجب ألا تزيد على ${field.validation.max}.`;
      }
    }
  }

  if (control.dataset.editableList === "true" && control.value.trim()) {
    const normalized = normalizedComparison(control.value);
    const allowed = allowedOptionsForControl(control);
    if (!allowed.some((option) => option.id === control.value || normalizedComparison(option.label) === normalized)) {
      return `اختر قيمة معتمدة للحقل «${field.label}» أو أضف القيمة الجديدة أولًا.`;
    }
  }

  return "";
}

function clearFieldValidation(control) {
  control.setCustomValidity("");
  control.removeAttribute("aria-invalid");

  const wrapper = control.closest("[data-field-wrapper]");
  const error = wrapper?.querySelector("[data-field-error]");
  if (error) {
    const ids = (control.getAttribute("aria-describedby") || "").split(/\s+/).filter(id => id && id !== error.id);
    if (ids.length) control.setAttribute("aria-describedby", ids.join(" "));
    else control.removeAttribute("aria-describedby");
    error.remove();
  }
  wrapper?.querySelector(".entry-control-surface")?.classList.remove("has-required-error");
}

function validateEntryControl(control, showMessage = true) {
  if (
    !control.matches("[data-value-control]") ||
    ["search", "full-search"].includes(control.dataset.scope) ||
    control.type === "hidden"
  ) {
    return true;
  }

  clearFieldValidation(control);

  const message = fieldValidationMessage(control);

  if (!message) {
    return true;
  }

  control.setCustomValidity(message);
  control.setAttribute("aria-invalid", "true");

  if (showMessage) {
    const wrapper = control.closest("[data-field-wrapper]");

    if (wrapper) {
      const surface = wrapper.querySelector(".entry-control-surface");
      const missing = control.validity.valueMissing && Boolean(surface);
      const error = document.createElement(missing ? "span" : "p");
      error.className = missing ? "field-error field-error-inside" : "field-error";
      error.dataset.fieldError = "";
      error.id = `error-${control.id || Math.random().toString(16).slice(2)}`;
      error.textContent = missing ? "هذا الحقل مطلوب" : message;
      error.setAttribute("role", "status");
      control.setAttribute("aria-describedby", [control.getAttribute("aria-describedby"), error.id].filter(Boolean).join(" "));
      if (missing) surface.classList.add("has-required-error");
      (missing ? surface : wrapper).append(error);
    }
  }

  return false;
}
function setControlValue(control, value) {
  const field = fieldById(control.dataset.fieldId, state.schema);
  if (!field) {
    return;
  }
  if (control.dataset.editableList === "true") {
    const option = activeOptions(field).find((candidate) => candidate.id === value);
    control.value = option?.label || String(value || "");
    control.dataset.selectedOptionId = option?.id || "";
    control._renderListMenu?.(false);
    return;
  }
  if (isSystemField(field)) {
    setSystemFieldValue(control, field);
    return;
  }
  if (["date_gregorian", "date_hijri", "date_persian"].includes(field.type)) {
    control.value = value || "";
    const group = control.closest(".calendar-control");
    const [year = "", month = "", day = ""] = String(value || "").split("-");
    group.querySelector("[data-calendar-year]").value = year;
    group.querySelector("[data-calendar-month]").value = month;
    fillCalendarDays(group);
    group.querySelector("[data-calendar-day]").value = day;
    control.value = value || "";
    syncCalendarDate(group, control);
  } else if (field.type === "file") {
    control.value = value || "";
    control._selectedFile = null;
    control._uploadName = "";
    const picker = control
      .closest(".attachment-control")
      .querySelector("[data-file-picker]");
    picker.value = "";
    refreshFileSummary(control);
  } else if (field.type === "checkbox") {
    const checked =
      value === true ||
      ["true", "1", "نعم", "yes", "on"].includes(
        String(value ?? "").toLocaleLowerCase(),
      );
    if (control.tagName === "SELECT") {
      control.value =
        value === "" || value == null ? "" : checked ? "true" : "false";
    } else {
      control.checked = checked;
      control._syncCheckboxMeaning?.();
    }
  } else if (field.type === "checkbox_group") {
    const values = Array.isArray(value)
      ? value
      : String(value || "")
          .split(" | ")
          .map((item) => item.trim())
          .filter(Boolean);
    const selected = new Set(
      values.map((item) => optionIdForValue(field, item)),
    );
    control
      .closest(".checkbox-group-control")
      .querySelectorAll('input[type="checkbox"][data-option-id]')
      .forEach((input) => {
        input.checked = selected.has(input.dataset.optionId);
      });
    syncCheckboxGroupControl(control);
  } else if (["select", "yes_no"].includes(field.type)) {
    if (control.multiple) {
      const values = new Set((Array.isArray(value) ? value : [value]).map((item) => optionIdForValue(field, item)));
      [...control.options].forEach((option) => { option.selected = values.has(option.value); });
    } else {
      control.value = optionIdForValue(field, value);
      if (!control.value && value) control.value = "";
    }
  } else if (field.type === "number") {
    control.value = workspace.formatNumber(value ?? "", field);
  } else {
    control.value = value ?? "";
  }
}

function sourceControlFor(targetControl, sourceFieldId) {
  const targetCategory = categoryById(
    targetControl.dataset.categoryId,
    state.schema,
  );
  const sourceCategory = fieldCategory(sourceFieldId, state.schema);
  if (
    targetControl.dataset.scope === "related" &&
    targetCategory?.id === sourceCategory?.id
  ) {
    return (
      targetControl
        .closest(".related-card")
        ?.querySelector(
          `[data-value-control][data-field-id="${attributeSafe(sourceFieldId)}"]`,
        ) || null
    );
  }
  return elements.recordForm.querySelector(
    `[data-value-control][data-scope="main"][data-field-id="${attributeSafe(sourceFieldId)}"]`,
  );
}

function optionFilterToken(sourceField, sourceControl) {
  const value = controlValue(sourceControl);
  if (sourceField.type === "checkbox") {
    return value ? "true" : "false";
  }
  return optionIdForValue(sourceField, value);
}

function dependencyTokenForControl(control) {
  const field = fieldById(control?.dataset.fieldId, state.schema);
  if (!field?.option_filter) return "";
  const sourceField = fieldById(field.option_filter.source_field_id, state.schema);
  const sourceControl = sourceField
    ? sourceControlFor(control, sourceField.id)
    : null;
  return sourceField && sourceControl
    ? optionFilterToken(sourceField, sourceControl)
    : "";
}

function allowedOptionsForControl(control) {
  const field = fieldById(control.dataset.fieldId, state.schema);
  const all = activeOptions(field);
  if (!field?.option_filter || control.dataset.scope === "search") {
    return all;
  }
  const source = fieldById(field.option_filter.source_field_id, state.schema);
  const sourceControl = sourceControlFor(
    control,
    field.option_filter.source_field_id,
  );
  if (!source || !sourceControl) {
    return all;
  }
  const token = optionFilterToken(source, sourceControl);
  const mapping = field.option_filter.mappings?.[token];
  if (!mapping) {
    return field.option_filter.unmatched === "none" ? [] : all;
  }
  const allowed = new Set(mapping);
  return all.filter((option) => allowed.has(option.id));
}

function refreshDependentControl(control, notify = false) {
  const field = fieldById(control.dataset.fieldId, state.schema);
  if (
    !field?.option_filter ||
    !["select", "checkbox_group"].includes(field.type)
  ) {
    return false;
  }
  const allowed = allowedOptionsForControl(control);
  const allowedIds = new Set(allowed.map((option) => option.id));
  let cleared = false;
  if (field.type === "select") {
    const activelyTyping = (
      control.dataset.editableList === "true" &&
      document.activeElement === control &&
      !control.dataset.selectedOptionId &&
      Boolean(control.value.trim())
    );
    if (activelyTyping) {
      control._renderListMenu?.(true);
      return false;
    }
    const previous = controlValue(control);
    if (control.dataset.editableList === "true") {
      control._renderListMenu?.(false);
    } else {
      control.replaceChildren();
      appendBlankOption(control, "— اختر —");
      for (const item of allowed) {
        const option = document.createElement("option");
        option.value = item.id;
        option.textContent = item.label;
        control.append(option);
      }
    }
    if (previous && allowedIds.has(previous)) {
      setControlValue(control, previous);
    } else {
      control.value = "";
      control.dataset.selectedOptionId = "";
      control._renderListMenu?.(false);
      cleared = Boolean(previous);
    }
  } else {
    control
      .closest(".checkbox-group-control")
      .querySelectorAll('input[type="checkbox"][data-option-id]')
      .forEach((input) => {
        const label = input.closest("label");
        const available = allowedIds.has(input.dataset.optionId);
        label.hidden = !available;
        input.disabled = !available;
        if (!available && input.checked) {
          input.checked = false;
          cleared = true;
        }
      });
    syncCheckboxGroupControl(control);
  }
  if (cleared && notify) {
    showToast(`تم مسح قيمة «${field.label}» لأنها لم تعد متاحة.`, "info");
  }
  return cleared;
}

function refreshAllDependentOptions(notify = false) {
  elements.recordForm
    .querySelectorAll("[data-value-control]")
    .forEach((control) => {
      refreshDependentControl(control, notify);
    });
}

function anchoredRelatedCategories(schema = state.schema) {
  const mapping = new Map();
  for (const category of schema.categories.filter(
    (candidate) =>
      candidate.kind === "repeatable" && !candidate.parent_category_id,
  )) {
    let anchor = category.anchor_field_id;
    if (!anchor) {
      const condition = conditionsFor("category", category.id, schema).find(
        (candidate) =>
          fieldCategory(candidate.source_field_id, schema)?.kind === "main",
      );
      anchor = condition?.source_field_id || null;
    }
    if (anchor) {
      if (!mapping.has(anchor)) {
        mapping.set(anchor, []);
      }
      mapping.get(anchor).push(category);
    }
  }
  return mapping;
}

function createSectionHeading(category) {
  const heading = document.createElement("div");
  heading.className = "section-heading collapsible-title-space";
  heading.dataset.toggleEntryCategory = "";
  heading.setAttribute("aria-expanded", "true");
  const content = document.createElement("div");
  const title = document.createElement("h2");
  title.textContent = category.label;
  const description = document.createElement("p");
  description.textContent = category.description || "";
  content.append(title);
  if (category.description) {
    content.append(description);
  }
  heading.append(content);
  return heading;
}

function setEntryCategoryCollapsed(section, collapsed) {
  if (!section) return;
  if (section.matches('[data-main-category-panel]')) return;
  section.classList.toggle("entry-category-collapsed", collapsed);
  const heading = section.querySelector(":scope > .section-heading[data-toggle-entry-category]");
  heading?.setAttribute("aria-expanded", String(!collapsed));
}

function expandEntryCategoryForControl(control) {
  const mainPanel = control?.closest('[data-main-category-panel]');
  if (mainPanel) selectMainCategoryTab(mainPanel.dataset.mainCategoryPanel);
  let card = control?.closest(".related-card");
  while (card) {
    selectRelatedCard(card.parentElement, card.dataset.childId);
    card = card.parentElement.closest(".related-card");
  }
  let section = control?.closest("[data-entry-category]");
  while (section) {
    setEntryCategoryCollapsed(section, false);
    section = section.parentElement?.closest("[data-entry-category]") || null;
  }
}

function activateEntryCategoryForControl(control) {
  const section = control?.closest("[data-entry-category]");
  if (!section) return;
  state.activeEntryCategorySection = section;
}

function createRelatedSection(category, parentChildId = "") {
  const section = document.createElement("section");
  section.className = "related-section field-full";
  section.dataset.relatedCategory = category.id;
  section.dataset.entryCategory = category.id;
  section.dataset.categoryId = category.id;
  section.dataset.parentChildId = parentChildId;
  section.id = parentChildId
    ? `entry-category-${category.id}-${parentChildId}`
    : `entry-category-${category.id}`;
  const heading = createSectionHeading(category);
  const records = document.createElement("div");
  records.className = "related-records home-schema-browser-panels";
  records.dataset.relatedRecords = category.id;
  records.dataset.parentChildId = parentChildId;

  const addRow = document.createElement("div");
  addRow.className = "related-add-row home-schema-browser-tabs";
  addRow.setAttribute("role", "tablist");
  const add = document.createElement("button");
  add.type = "button";
  add.className = "button button-secondary related-tab-add";
  add.dataset.addRelated = category.id;
  add.dataset.parentChildId = parentChildId;
  add.append(actionIcon("plus"));
  add.title = category.add_label || "إضافة بطاقة";
  add.setAttribute("aria-label", add.title);
  addRow.append(add);

  // Keep the add button after every card in both visual and keyboard order.
  const browser = document.createElement("div");
  browser.className = "home-tabbed-workspace home-schema-browser related-tab-workspace";
  browser.append(addRow, records);
  section.append(heading, browser);
  if (category.auto_start) {
    window.setTimeout(() => {
      if (records.isConnected && !directRelatedCards(records).length) {
        addRelatedCard(category.id, null, {
          markDirty: false,
          parentChildId,
        });
      }
    }, 0);
  }
  return section;
}

function createEntryCategorySection(category, anchors, rendered, options = {}) {
  const schema = options.schema || state.schema;
  const fieldFactory = options.fieldFactory || createFieldElement;
  if (!category || rendered.has(category.id)) {
    return null;
  }
  rendered.add(category.id);

  let section;
  if (category.kind === "repeatable") {
    section = options.relatedFactory ? options.relatedFactory(category, anchors, rendered, options) : createRelatedSection(category);
  } else {
    section = document.createElement("section");
    section.className = "form-section";
    section.dataset.mainCategory = category.id;
    section.dataset.entryCategory = category.id;
    section.dataset.categoryId = category.id;
    section.id = `entry-category-${category.id}`;
    section.append(createSectionHeading(category));

    const grid = document.createElement("div");
    grid.className = "field-grid main-category-fields";


    const nestedChildren = categoryChildren(category.id, schema);
    for (const field of category.fields) {
      const fieldElement = fieldFactory(field, "main", category.id);
      grid.append(fieldElement);
      nestedChildren
        .filter((child) => child.parent_field_id === field.id)
        .forEach((child) => {
          const childSection = createEntryCategorySection(
            child,
            anchors,
            rendered,
            options,
          );
          if (childSection) grid.append(childSection);
        });
      for (const related of anchors.get(field.id) || []) {
        const relatedSection = createEntryCategorySection(
          related,
          anchors,
          rendered,
          options,
        );
        if (relatedSection) {
          grid.append(relatedSection);
        }
      }
    }

    section.append(grid);
  }

  const children = categoryChildren(category.id, schema).filter(
    (child) => !rendered.has(child.id) && (
      category.kind !== "repeatable" || child.kind === "main"
    ),
  );
  if (children.length) {
    const childContainer = document.createElement("div");
    childContainer.className = "entry-category-children";
    for (const child of children) {
      const childSection = createEntryCategorySection(
        child,
        anchors,
        rendered,
        options,
      );
      if (childSection) {
        childContainer.append(childSection);
      }
    }
    if (childContainer.children.length) {
      section.append(childContainer);
    }
  }

  return section;
}

function renderEntryForm() {
  if (!state.schema) {
    return;
  }
  const configured = hasConfiguredFields();
  elements.emptySchemaPanel.hidden = configured;
  elements.recordForm.hidden = !configured;
  elements.entryRecordActions.hidden = !configured;
  if (!configured) {
    elements.searchPanel.hidden = true;
    if (state.mode === "entry") {
      refreshCategoryNavigation();
    }
    return;
  }

  const previousMainCategory = elements.mainSections.dataset.activeMainCategory;
  elements.mainSections.replaceChildren();
  elements.unanchoredRelatedSections.replaceChildren();
  state.activeEntryCategorySection = null;
  const anchors = anchoredRelatedCategories();
  const anchoredIds = new Set(
    [...anchors.values()].flat().map((category) => category.id),
  );

  const categoryIds = new Set(
    state.schema.categories.map((category) => category.id),
  );
  const roots = state.schema.categories.filter(
    (category) =>
      !category.parent_category_id ||
      !categoryIds.has(category.parent_category_id),
  );
  const rendered = new Set();

  for (const category of roots) {
    if (category.kind === "repeatable" && anchoredIds.has(category.id)) {
      continue;
    }
    const section = createEntryCategorySection(category, anchors, rendered);
    if (!section) {
      continue;
    }
    if (category.kind === "main") {
      elements.mainSections.append(section);
    } else {
      elements.unanchoredRelatedSections.append(section);
    }
  }

  for (const category of state.schema.categories) {
    const parent = categoryById(category.parent_category_id, state.schema);
    if (
      rendered.has(category.id) ||
      anchoredIds.has(category.id) ||
      parent?.kind === "repeatable"
    ) {
      continue;
    }
    const section = createEntryCategorySection(category, anchors, rendered);
    if (section) {
      (category.kind === "main"
        ? elements.mainSections
        : elements.unanchoredRelatedSections
      ).append(section);
    }
  }
  renderMainCategoryTabs(previousMainCategory);
  elements.unanchoredRelatedArea.hidden =
    elements.unanchoredRelatedSections.children.length === 0;
  elements.recordCode.value =
    state.selectedRecordCode ||
    elements.recordCode.value ||
    generateRecordCode();
  updateRecordButtonLabels();
  if (state.mode === "entry") {
    refreshCategoryNavigation();
  }
  updateConditionalVisibility();
  renderEntryRecentRecords();
}

function selectMainCategoryTab(categoryId, container = elements.mainSections) {
  const panels = [...container.querySelectorAll('[data-main-category-panel]')];
  const active = panels.find((panel) => panel.dataset.mainCategoryPanel === categoryId && !panel.hidden)
    || panels.find((panel) => !panel.hidden);
  container.dataset.activeMainCategory = active?.dataset.mainCategoryPanel || '';
  panels.forEach((panel) => {
    const selected = panel === active;
    panel.classList.toggle('main-category-panel-inactive', !selected);
    panel.toggleAttribute('inert', !selected);
    panel.setAttribute('aria-hidden', String(!selected));
  });
  container.querySelectorAll('[data-main-category-tab]').forEach((tab) => {
    const panel = panels.find((item) => item.dataset.mainCategoryPanel === tab.dataset.mainCategoryTab);
    const selected = panel === active;
    tab.hidden = !panel || panel.hidden;
    tab.classList.toggle('is-active', selected);
    tab.setAttribute('aria-selected', String(selected));
  });
  if (active && ((container === elements.mainSections && state.mode === 'entry') || (container === elements.builderCategories && state.mode === 'builder'))) setActiveBuilderCategory(active.dataset.mainCategoryPanel);
}

function reconcileChildElements(parent, children) {
  // Leave unchanged subtrees mounted: detaching a calendar/large select also
  // wakes layout observers and discards native focus/scroll state.
  children.forEach((child, index) => {
    if (parent.children[index] !== child) parent.insertBefore(child, parent.children[index] || null);
  });
  while (parent.children.length > children.length) parent.lastElementChild.remove();
}

function renderMainCategoryTabs(preferredCategoryId, container = elements.mainSections, schema = state.schema, suppliedPanels = null) {
  const panels = suppliedPanels || [...container.children].filter((section) => {
    const category = categoryById(section.dataset.mainCategory, schema);
    return category?.kind === 'main' && !category.parent_category_id;
  });
  if (!panels.length) {
    container.querySelector(':scope > .main-category-tab-workspace')?.remove();
    return;
  }
  let browser = container.querySelector(':scope > .main-category-tab-workspace');
  const existing = Boolean(browser);
  browser ||= document.createElement('div');
  browser.className = 'home-tabbed-workspace home-schema-browser main-category-tab-workspace';
  const rail = browser.firstElementChild || document.createElement('div');
  rail.className = 'home-schema-browser-tabs';
  rail.setAttribute('role', 'tablist');
  rail.setAttribute('aria-label', 'الفئات الرئيسية');
  const content = browser.lastElementChild || document.createElement('div');
  content.className = 'home-schema-browser-panels';
  if (!existing) {
    container.insertBefore(browser, panels[0].parentElement === container ? panels[0] : null);
    browser.append(rail, content);
  }
  const previousTabs = new Map([...rail.children].map(tab => [tab.dataset.mainCategoryTab, tab]));
  const nextTabs = [];
  panels.forEach((panel) => {
    const category = categoryById(panel.dataset.mainCategory, schema);
    const tabId = `${container.id}-category-tab-${category.id}`;
    panel.dataset.mainCategoryPanel = category.id;
    panel.setAttribute('role', 'tabpanel');
    panel.setAttribute('aria-labelledby', tabId);
    panel.querySelector(':scope > .section-heading')?.remove();
    panel.classList.remove('entry-category-collapsed');
    const oldTab = previousTabs.get(category.id);
    const tab = oldTab || document.createElement('button');
    tab.type = 'button';
    tab.classList.add('home-schema-browser-tab');
    tab.dataset.mainCategoryTab = category.id;
    tab.id = tabId;
    tab.setAttribute('role', 'tab');
    tab.setAttribute('aria-controls', panel.id);
    const label = tab.firstElementChild || document.createElement('span');
    if (label.textContent !== category.label) label.textContent = category.label;
    label.title = category.label;
    if (!oldTab) {
      tab.append(label);
      tab.addEventListener('click', () => selectMainCategoryTab(category.id, container));
      tab.addEventListener('keydown', (event) => {
        if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
        event.preventDefault();
        const tabs = [...rail.children].filter((item) => !item.hidden);
        const index = tabs.indexOf(tab);
        const target = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1
          : (index + (event.key === 'ArrowLeft' ? 1 : tabs.length - 1)) % tabs.length;
        tabs[target]?.click();
        tabs[target]?.focus();
      });
    }
    nextTabs.push(tab);
  });
  reconcileChildElements(rail, nextTabs);
  reconcileChildElements(content, panels);
  selectMainCategoryTab(preferredCategoryId, container);
  return browser;
}

function entryFieldTabStops(includeInactiveMainPanels = false) {
  if (!elements.recordForm) return [];
  const selector = [
    '[data-linked-record-code]:not([disabled])',
    '[data-file-picker]:not([disabled])',
    '[data-file-name]:not([disabled])',
    '[data-related-tab]',
    '[data-calendar-day]:not([disabled])',
    '[data-calendar-month]:not([disabled])',
    '[data-calendar-year]:not([disabled])',
    'select[data-value-control]:not([disabled])',
    'textarea[data-value-control]:not([disabled]):not([readonly])',
    'input[data-value-control]:not([type="hidden"]):not([disabled]):not([readonly])',
    '.checkbox-group-control input[type="checkbox"]:not([disabled])',
    'button:not([disabled])',
    'a[href]',
  ].join(", ");
  const ordered = [];
  const walk = (root) => {
    for (const child of root.children) {
      if (child.hidden || child.classList.contains("entry-category-collapsed") || child.classList.contains('main-category-panel-inactive')) continue;
      if (child.classList.contains('main-category-tab-workspace')) {
        const rail = child.querySelector(':scope > .home-schema-browser-tabs');
        const panels = child.querySelector(':scope > .home-schema-browser-panels');
        for (const tab of rail.querySelectorAll(':scope > [data-main-category-tab]')) {
          if (tab.hidden) continue;
          ordered.push(tab);
          const panel = [...panels.children].find((item) => item.dataset.mainCategoryPanel === tab.dataset.mainCategoryTab);
          if (panel && !panel.hidden && (includeInactiveMainPanels || !panel.classList.contains('main-category-panel-inactive'))) {
            walk(panel);
          }
        }
      } else if (child.classList.contains("related-tab-workspace")) {
        const rail = child.querySelector(":scope > .related-add-row");
        const records = child.querySelector(":scope > .related-records");
        for (const tab of rail.querySelectorAll(":scope > [data-related-tab]")) {
          ordered.push(tab);
          const card = directRelatedCards(records).find((item) => item.dataset.childId === tab.dataset.relatedTab);
          if (card && !card.hidden) {
            ordered.push(tab.querySelector(".related-tab-close"));
            walk(card);
          }
        }
        ordered.push(rail.querySelector("[data-add-related]"));
      } else {
        if (child.matches(selector)) ordered.push(child);
        walk(child);
      }
    }
  };
  walk(elements.recordForm);
  return ordered.filter((control) => control && !control.disabled).filter((control) => (
    control.tabIndex >= 0 &&
    !control.closest("[hidden]") &&
    !control.closest(".entry-category-collapsed")
  ));
}

function focusAdjacentEntryField(current, reverse = false) {
  // Build the logical label → fields → next label order, including destination
  // panels. Only an explicit Tab reveals a destination; value edits never do.
  const controls = entryFieldTabStops(true);
  const index = controls.indexOf(current);
  if (index < 0 || controls.length === 0) return false;
  const nextIndex = (index + (reverse ? -1 : 1) + controls.length) % controls.length;
  const next = controls[nextIndex];
  const mainCategoryId = next.dataset.mainCategoryTab
    || next.closest('[data-main-category-panel]')?.dataset.mainCategoryPanel;
  if (mainCategoryId) selectMainCategoryTab(mainCategoryId);
  next.focus({ preventScroll: true });
  next.scrollIntoView({ block: "nearest", inline: "nearest" });
  return true;
}

function mappedRelatedPersonValue(sourceField, targetField, value) {
  if (!["select", "yes_no", "checkbox_group"].includes(sourceField.type)) {
    return value;
  }
  const sourceOptions = new Map(
    (sourceField.options || []).map((option) => [option.id, option.label]),
  );
  const targetOptions = new Map(
    (targetField.options || []).map((option) => [
      normalizedComparison(option.label),
      option.id,
    ]),
  );
  const mapOne = (optionId) =>
    targetOptions.get(
      normalizedComparison(sourceOptions.get(optionId) || optionId),
    ) || "";
  if (sourceField.type === "checkbox_group") {
    return (Array.isArray(value) ? value : []).map(mapOne).filter(Boolean);
  }
  return mapOne(value);
}

async function fillRelatedPersonCard(card, category, code) {
  const normalizedCode = String(code || "").trim();
  const input = card.querySelector("[data-linked-record-code]");
  const status = card.querySelector("[data-related-person-status]");
  if (!normalizedCode) {
    showToast("أدخل ID الشخص المرتبط أولًا.", "error");
    input?.setCustomValidity("أدخل ID الشخص المرتبط أولًا.");
    return false;
  }
  if (normalizedCode === elements.recordCode.value) {
    showToast("لا يمكن ربط السجل بنفسه.", "error");
    input?.setCustomValidity("لا يمكن ربط السجل بنفسه.");
    return false;
  }

  if (input?._relatedPersonLoadPromise) {
    return input._relatedPersonLoadPromise;
  }

  const loadOperation = (async () => {
    input.disabled = true;
    card.classList.add("related-person-loading");
    if (status) {
      status.hidden = false;
      status.textContent = "جاري التحقق…";
    }

    try {
      const response = await fetch(
        `/api/records/${encodeURIComponent(normalizedCode)}`,
        { cache: "no-store" },
      );
      const linkedRecord = await responseJson(response);
      if (
        card.dataset.relatedPersonMode !== "existing" ||
        input.value.trim() !== normalizedCode
      ) {
        return false;
      }
      const values = {};
      directCardControls(card).forEach((control) => {
        values[control.dataset.fieldId] = controlValue(control);
      });
      let mappedCount = 0;
      for (const targetField of category.fields) {
        const sourceId = targetField.related_person_source_field_id;
        const sourceField = fieldById(sourceId, state.schema);
        if (!sourceField || !sourceId) {
          continue;
        }
        const sourceCategory = fieldCategory(sourceId, state.schema);
        let sourceValue = linkedRecord.main[sourceId];
        if (sourceCategory?.kind === "repeatable") {
          const checkboxId = targetField.related_person_source_checkbox_id;
          const sourceRow = (linkedRecord.related?.[sourceCategory.id] || []).find(
            (candidate) => Boolean(candidate.values?.[checkboxId]),
          );
          sourceValue = sourceRow?.values?.[sourceId] ?? "";
        }
        values[targetField.id] = mappedRelatedPersonValue(
          sourceField,
          targetField,
          sourceValue,
        );
        mappedCount += 1;
      }
      populateControlsInDependencyOrder(
        directCardControls(card),
        values,
      );
      card.dataset.linkedRecordCode = linkedRecord.record_code;
      input.value = linkedRecord.record_code;
      input.setCustomValidity("");
      if (status) {
        status.hidden = false;
        status.textContent = `تم الربط بـ ${linkedRecord.record_code}`;
      }
      updateConditionalVisibility();
      scheduleDraftSave();
      showToast(
        mappedCount
          ? `تم جلب بيانات الشخص المرتبط: ${linkedRecord.record_code}`
          : "تم التحقق من ID، لكن لم تُحدَّد حقول للنسخ في المصمّم.",
      );
      return true;
    } catch (error) {
      card.dataset.linkedRecordCode = "";
      input.setCustomValidity(error.message);
      if (status) {
        status.hidden = false;
        status.textContent = "لم يُعثر على سجل مطابق";
      }
      showToast(error.message, "error");
      return false;
    } finally {
      input.disabled = false;
      card.classList.remove("related-person-loading");
    }
  })();

  input._relatedPersonLoadPromise = loadOperation;
  try {
    return await loadOperation;
  } finally {
    input._relatedPersonLoadPromise = null;
  }
}

async function saveAndOpenRelatedRecord(card, category) {
  const input = card.querySelector("[data-linked-record-code]");
  const code = input?.value.trim() || "";
  if (!code) {
    return;
  }
  if (card.dataset.linkedRecordCode !== code) {
    const linked = await fillRelatedPersonCard(card, category, code);
    if (!linked) {
      return;
    }
  }
  if (await saveCurrentRecord()) {
    await loadRecord(code);
  }
}

function setRelatedPersonMode(card, mode, focusInput = false) {
  const existing = mode === "existing";
  const link = card.querySelector("[data-related-person-link]");
  const input = card.querySelector("[data-linked-record-code]");
  const status = card.querySelector("[data-related-person-status]");

  card.dataset.relatedPersonMode = existing ? "existing" : "manual";
  if (link) {
    link.hidden = !existing;
  }
  if (input) {
    input.required = existing;
  }

  card.querySelectorAll("[data-related-person-mode]").forEach((button) => {
    const selected =
      button.dataset.relatedPersonMode === card.dataset.relatedPersonMode;
    button.classList.toggle("related-person-mode-selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });

  if (!existing) {
    card.dataset.linkedRecordCode = "";
    if (input) {
      input.value = "";
      input.setCustomValidity("");
    }
    if (status) {
      status.hidden = true;
      status.textContent = "";
    }
  } else if (focusInput && input) {
    // Mode changes leave keyboard focus where the user placed it.
  }

  if (card.isConnected) {
    updateConditionalVisibility();
    scheduleDraftSave();
  }
}

async function validateRelatedPersonCardsBeforeSave() {
  const cards = [
    ...elements.recordForm.querySelectorAll(
      '.related-card[data-related-person-mode="existing"]',
    ),
  ];

  for (const card of cards) {
    const input = card.querySelector("[data-linked-record-code]");
    const category = categoryById(card.dataset.categoryId, state.schema);
    const code = input?.value.trim() || "";

    if (!code) {
      expandEntryCategoryForControl(input);
      input.setCustomValidity("أدخل ID الشخص المرتبط.");
      input.scrollIntoView({ behavior: "smooth", block: "center" });
      return false;
    }

    if (card.dataset.linkedRecordCode !== code) {
      const loaded = await fillRelatedPersonCard(card, category, code);
      if (!loaded) {
        input.scrollIntoView({ behavior: "smooth", block: "center" });
        return false;
      }
    }
  }

  return true;
}

function newRelatedChildId() {
  if (window.crypto?.randomUUID) {
    return window.crypto.randomUUID().replaceAll("-", "");
  }
  const bytes = new Uint8Array(16);
  window.crypto?.getRandomValues?.(bytes);
  return [...bytes].map((value) => value.toString(16).padStart(2, "0")).join("")
    || `${Date.now().toString(16).padStart(16, "0")}${Math.random().toString(16).slice(2).padEnd(16, "0")}`.slice(0, 32);
}

function directRelatedCards(records) {
  return [...records.children].filter((child) => child.classList.contains("related-card"));
}

function selectRelatedCard(records, childId) {
  records.dataset.activeChildId = childId;
  directRelatedCards(records).forEach((card) => {
    const active = card.dataset.childId === childId;
    card.hidden = !active;
    card.classList.toggle("is-active", active);
  });
  records.parentElement.querySelectorAll(":scope > .related-add-row [data-related-tab]").forEach((tab) => {
    const active = tab.dataset.relatedTab === childId;
    tab.classList.toggle("is-active", active);
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = 0;
    tab.querySelector(".related-tab-close").hidden = !active;
  });
}

function renderRelatedTabs(records) {
  const rail = records.parentElement.querySelector(":scope > .related-add-row");
  if (!rail) return;
  const cards = directRelatedCards(records);
  const existingTabs = [...rail.querySelectorAll(":scope > [data-related-tab]")];
  if (existingTabs.length === cards.length && existingTabs.every((tab, index) => tab.dataset.relatedTab === cards[index].dataset.childId)) {
    // Editing a value must not replace focused tab labels or affect the active card.
    existingTabs.forEach((tab, index) => {
      const name = cards[index].querySelector("[data-related-title]").textContent;
      const label = tab.querySelector(":scope > span");
      if (label.textContent !== name) label.textContent = name;
      label.title = name;
      const close = tab.querySelector(".related-tab-close");
      close.title = `حذف ${name}`;
      close.setAttribute("aria-label", close.title);
    });
    return;
  }
  existingTabs.forEach((tab) => tab.remove());
  const add = rail.querySelector("[data-add-related]");
  cards.forEach((card, index) => {
    const tab = document.createElement("div");
    tab.className = "home-schema-browser-tab";
    tab.setAttribute("role", "tab");
    tab.dataset.relatedTab = card.dataset.childId;
    tab.id = `related-tab-${card.dataset.childId}`;
    card.id = `related-panel-${card.dataset.childId}`;
    tab.setAttribute("aria-controls", card.id);
    card.setAttribute("role", "tabpanel");
    card.setAttribute("aria-labelledby", tab.id);
    const label = document.createElement("span");
    label.textContent = card.querySelector("[data-related-title]").textContent;
    label.title = label.textContent;
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "related-tab-close";
    remove.textContent = "×";
    remove.title = `حذف ${label.textContent}`;
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", (event) => {
      event.stopPropagation();
      card.querySelector(":scope > .related-card-heading [data-remove-related-card]").click();
    });
    tab.append(label, remove);
    tab.addEventListener("click", () => selectRelatedCard(records, card.dataset.childId));
    tab.addEventListener("keydown", (event) => {
      if (event.target !== tab) return;
      if (["Enter", " ", "ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) {
        event.preventDefault();
        let target = index;
        if (event.key === "ArrowLeft") target = (index + 1) % cards.length;
        if (event.key === "ArrowRight") target = (index + cards.length - 1) % cards.length;
        if (event.key === "Home") target = 0;
        if (event.key === "End") target = cards.length - 1;
        selectRelatedCard(records, cards[target].dataset.childId);
        rail.querySelector(`[data-related-tab="${cards[target].dataset.childId}"]`).focus();
      }
    });
    rail.insertBefore(tab, add);
  });
  const active = cards.find((card) => card.dataset.childId === records.dataset.activeChildId) || cards[0];
  if (active) selectRelatedCard(records, active.dataset.childId);
}

function relatedRecordsContainer(categoryId, parentChildId = "") {
  return [...document.querySelectorAll(
    `[data-related-records="${attributeSafe(categoryId)}"]`,
  )].find((records) => (records.dataset.parentChildId || "") === parentChildId) || null;
}

function directCardControls(card, selector = "[data-value-control]") {
  return [...card.querySelectorAll(selector)].filter(
    (control) => control.closest(".related-card") === card,
  );
}

function addRelatedCard(
  categoryId,
  row = null,
  {
    focusFirst = false,
    markDirty = row === null,
    parentChildId = row?.parent_child_id || "",
  } = {},
) {
  const category = categoryById(categoryId, state.schema);
  const records = relatedRecordsContainer(categoryId, parentChildId);
  if (!category || !records || !category.fields.length) {
    return;
  }
  const card = document.createElement("div");
  card.className = "related-card";
  card.dataset.childId = row?._child_id || newRelatedChildId();
  card.dataset.clientGenerated = row?._client_generated || !row?._child_id ? "true" : "false";
  card.dataset.parentChildId = parentChildId;
  card.dataset.categoryId = category.id;
  const heading = document.createElement("div");
  heading.className = "related-card-heading";
  const identity = document.createElement("div");
  const title = document.createElement("strong");
  title.dataset.relatedTitle = "";
  identity.append(title);
  let initialRelatedPersonMode = null;

  if (category.related_person_enabled) {
    const workflow = document.createElement("div");
    workflow.className = "related-person-workflow";
    const question = document.createElement("span");
    question.className = "related-person-question";
    question.textContent = "هل لديه سجل؟";
    const modes = document.createElement("div");
    modes.className = "related-person-modes";
    modes.setAttribute("role", "group");
    modes.setAttribute("aria-label", "هل لدى الشخص المرتبط سجل؟");
    for (const [mode, label] of [
      ["existing", "لديه سجل"],
      ["manual", "ليس لديه سجل"],
    ]) {
      const modeButton = document.createElement("button");
      modeButton.type = "button";
      modeButton.className = "related-person-mode";
      modeButton.dataset.relatedPersonMode = mode;
      modeButton.textContent = label;
      modeButton.addEventListener("click", () => {
        setRelatedPersonMode(card, mode, mode === "existing");
      });
      modes.append(modeButton);
    }
    workflow.append(question, modes);

    const link = document.createElement("div");
    link.className = "related-person-link";
    link.dataset.relatedPersonLink = "";
    const input = document.createElement("input");
    input.type = "text";
    input.className = "control";
    input.dir = "ltr";
    input.placeholder = "ID الشخص المرتبط";
    input.dataset.linkedRecordCode = "";
    input.value = row?.linked_record_code || "";
    card.dataset.linkedRecordCode = row?.related_person_mode
      ? ""
      : input.value;
    input.addEventListener("input", () => {
      input.setCustomValidity("");
      if (input.value.trim() !== card.dataset.linkedRecordCode) {
        card.dataset.linkedRecordCode = "";
      }
      const status = card.querySelector("[data-related-person-status]");
      if (status) {
        status.hidden = true;
        status.textContent = "";
      }
      scheduleDraftSave();
    });
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        input.blur();
      }
    });
    input.addEventListener("blur", () => {
      if (
        card.dataset.relatedPersonMode === "existing" &&
        input.value.trim() &&
        input.value.trim() !== card.dataset.linkedRecordCode
      ) {
        void fillRelatedPersonCard(card, category, input.value);
      }
    });
    const status = document.createElement("small");
    status.className = "related-person-status";
    status.dataset.relatedPersonStatus = "";
    status.hidden = true;
    const saveAndOpen = document.createElement("button");
    saveAndOpen.type = "button";
    saveAndOpen.className =
      "button button-secondary related-person-save-open";
    saveAndOpen.title = "حفظ التعديلات وفتح سجل الشخص المرتبط";
    saveAndOpen.setAttribute("aria-label", saveAndOpen.title);
    saveAndOpen.append(actionIcon("open"));
    saveAndOpen.addEventListener("click", () => {
      void saveAndOpenRelatedRecord(card, category);
    });
    link.append(input, saveAndOpen, status);
    identity.append(workflow, link);

    initialRelatedPersonMode =
      row?.related_person_mode ||
      (row?.linked_record_code ? "existing" : "manual");
  }

  const headingTools = document.createElement("div");
  headingTools.className = "related-card-tools";
  headingTools.hidden = true;

  const remove = document.createElement("button");
  remove.type = "button";
  remove.className = "button button-danger-quiet icon-text-button";
  remove.dataset.removeRelatedCard = "";
  remove.append(actionIcon("trash"), document.createTextNode("حذف البطاقة"));
  remove.addEventListener("click", async () => {
    if (!(await requestConfirmation("هل تريد حذف هذه البطاقة وكل حقولها؟", { title: "حذف البطاقة", confirmLabel: "حذف" }))) return;
    card.remove();
    renumberRelatedCards(records);
    scheduleDraftSave();
  });
  headingTools.append(remove);
  heading.append(identity, headingTools);

  const grid = document.createElement("div");
  grid.className = "field-grid";
  const nestedCategories = categoryChildren(category.id, state.schema)
    .filter((child) => child.kind === "repeatable");
  const positionedChildIds = new Set();
  category.fields.forEach((field) => {
    const wrapper = createFieldElement(field, "related", category.id);
    const targetColumn = grid;
    targetColumn.append(wrapper);
    nestedCategories
      .filter((child) => child.parent_field_id === field.id)
      .forEach((child) => {
        targetColumn.append(createRelatedSection(child, card.dataset.childId));
        positionedChildIds.add(child.id);
      });
  });

  card.append(heading);
  title.hidden = true;
  heading.hidden = !category.related_person_enabled;
  card.append(grid);
  const nested = document.createElement("div");
  nested.className = "related-card-nested-categories";
  nestedCategories
    .filter((child) => !positionedChildIds.has(child.id))
    .forEach((child) => nested.append(createRelatedSection(child, card.dataset.childId)));
  if (nested.children.length) card.append(nested);
  records.append(card);
  if (!row || !records.dataset.activeChildId) records.dataset.activeChildId = card.dataset.childId;

  if (initialRelatedPersonMode) {
    setRelatedPersonMode(card, initialRelatedPersonMode);
    if (row?.linked_record_code && !row?.related_person_mode) {
      const status = card.querySelector("[data-related-person-status]");
      status.hidden = false;
      status.textContent = `تم الربط بـ ${row.linked_record_code}`;
    }
  }

  const cardControls = directCardControls(card);

  populateControlsInDependencyOrder(cardControls, row?.values || {});
  renumberRelatedCards(records);
  refreshAllDependentOptions(false);
  updateConditionalVisibility();

  if (markDirty && !state.restoringDraft && row === null) {
    scheduleDraftSave();
  }


  return card;
}

function renumberRelatedCards(records, preserveOrder = false) {
  const category = categoryById(records.dataset.relatedRecords, state.schema);
  const cards = directRelatedCards(records);
  const directFieldControl = (card, fieldId) => directCardControls(
    card,
    `[data-value-control][data-field-id="${attributeSafe(fieldId)}"]`,
  )[0];
  const displayValue = (card, fieldId) => {
    const control = directFieldControl(card, fieldId);
    if (!control) return "";
    const field = fieldById(fieldId, state.schema);
    const value = controlValue(control);
    if (field?.type === "checkbox") return checkboxDisplayMeaning(field, value);
    if (["select", "yes_no"].includes(field?.type)) {
      return optionLabelForValue(field, value);
    }
    return Array.isArray(value) ? value.join("، ") : String(value ?? "");
  };
  const sort = category?.card_sort || { mode: "manual", direction: "asc" };
  if (sort.mode !== "manual" && !preserveOrder) {
    const collator = new Intl.Collator("ar", { numeric: true, sensitivity: "base" });
    cards.sort((first, second) => {
      let firstValue = "";
      let secondValue = "";
      const fieldId = sort.mode === "title"
        ? category.card_title_field_id
        : sort.field_id;
      firstValue = displayValue(first, fieldId);
      secondValue = displayValue(second, fieldId);
      const result = collator.compare(firstValue, secondValue);
      return sort.direction === "desc" ? -result : result;
    });
    cards.forEach((card, index) => {
      if (records.children[index] !== card) records.insertBefore(card, records.children[index] || null);
    });
  }
  cards.forEach((card, index) => {
    const sequence = index + 1;
    card.dataset.minorId = String(sequence);
    const custom = category?.card_title_field_id
      ? displayValue(card, category.card_title_field_id).trim()
      : "";
    const prefix = category?.card_name_prefix?.trim() || "بطاقة";
    card.querySelector("[data-related-title]").textContent =
      custom || `${prefix} ${sequence}`;
  });
  renderRelatedTabs(records);
}

function mainValues() {
  const values = {};
  elements.recordForm
    .querySelectorAll('[data-value-control][data-scope="main"]')
    .forEach((control) => {
      values[control.dataset.fieldId] = controlValue(control);
    });
  return values;
}

function autoUpdateResult(rule, targetField, main, sourceRowValues) {
  if (rule.action === "clear") {
    return targetField.type === "checkbox" ? false : "";
  }
  if (rule.action === "current_user") {
    return state.auditUsers?.current_user || "";
  }
  if (rule.action === "copy_source") {
    return conditionValue(rule, main, sourceRowValues);
  }
  return rule.result_value ?? "";
}

function matchingAutoUpdateSource(rule, main, targetCategory, targetCard) {
  const sourceCategory = fieldCategory(rule.source_field_id, state.schema);
  if (sourceCategory?.kind !== "repeatable") {
    return {
      matched: conditionMatches(rule, main, null),
      rowValues: null,
    };
  }
  if (sourceCategory.id === targetCategory.id) {
    const rowValues = targetCard ? cardValues(targetCard) : null;
    return {
      matched: Boolean(rowValues) && conditionMatches(rule, main, rowValues),
      rowValues,
    };
  }
  const sourceCards = [...elements.recordForm.querySelectorAll(
    `.related-card[data-category-id="${attributeSafe(sourceCategory.id)}"]`,
  )];
  for (const sourceCard of sourceCards) {
    const rowValues = cardValues(sourceCard);
    if (conditionMatches(rule, main, rowValues)) {
      return { matched: true, rowValues };
    }
  }
  return { matched: false, rowValues: null };
}

function applyAutoUpdateRules() {
  if (state.applyingAutoUpdates || !state.schema) return;
  state.applyingAutoUpdates = true;
  try {
    const main = mainValues();
    for (let pass = 0; pass < 10; pass += 1) {
      let changed = false;
      for (const category of state.schema.categories) {
        for (const field of category.fields) {
          const rule = field.auto_update;
          if (!rule) continue;
          const controls = category.kind === "main"
            ? [...elements.recordForm.querySelectorAll(
                `[data-value-control][data-scope="main"][data-field-id="${attributeSafe(field.id)}"]`,
              )]
            : [...elements.recordForm.querySelectorAll(
                `.related-card[data-category-id="${attributeSafe(category.id)}"] [data-value-control][data-field-id="${attributeSafe(field.id)}"]`,
              )].filter((control) => control.closest(".related-card")?.dataset.categoryId === category.id);
          controls.forEach((control) => {
            const card = control.closest(".related-card");
            const source = matchingAutoUpdateSource(rule, main, category, card);
            if (!source.matched) return;
            const next = autoUpdateResult(
              rule,
              field,
              main,
              source.rowValues,
            );
            if (JSON.stringify(controlValue(control)) === JSON.stringify(next)) return;
            setControlValue(control, next);
            if (!card) main[field.id] = next;
            changed = true;
          });
        }
      }
      if (!changed) break;
    }
  } finally {
    state.applyingAutoUpdates = false;
  }
}

function cardValues(card) {
  const values = {};
  directCardControls(card).forEach((control) => {
    values[control.dataset.fieldId] = controlValue(control);
  });
  const category = categoryById(card.dataset.categoryId, state.schema);
  const modeField = relatedPersonModeField(category);
  if (modeField) {
    values[modeField.id] =
      card.dataset.relatedPersonMode === "existing" ? "existing" : "manual";
  }
  return values;
}

function updateConditionalVisibility() {
  if (!state.schema || elements.recordForm.hidden) {
    return;
  }
  refreshAllDependentOptions(true);
  const values = mainValues();
  elements.recordForm
    .querySelectorAll("[data-main-category]")
    .forEach((section) => {
      section.hidden = !targetVisible(
        "category",
        section.dataset.mainCategory,
        values,
      );
    });
  elements.recordForm
    .querySelectorAll("[data-related-category]")
    .forEach((section) => {
      section.hidden = !targetVisible(
        "category",
        section.dataset.relatedCategory,
        values,
      );
    });
  elements.recordForm
    .querySelectorAll("[data-field-wrapper]")
    .forEach((wrapper) => {
      const control = wrapper.querySelector("[data-value-control]");
      const card = wrapper.closest(".related-card");
      wrapper.hidden = !targetVisible(
        "field",
        wrapper.dataset.fieldWrapper,
        values,
        card ? cardValues(card) : null,
      );
      if (control?.dataset.scope === "related" && card) {
        wrapper.hidden =
          wrapper.hidden || card.closest("[data-related-category]").hidden;
      }
    });

  selectMainCategoryTab(elements.mainSections.dataset.activeMainCategory);
  syncEntryCategoryNavigatorVisibility();
  scheduleCategoryObservation();
}

function eligibleSearchFields(schema = state.schema) {
  return allFields(schema).filter(
    ({ field }) => field.type !== "file",
  );
}

function defaultSearchFieldIds(schema = state.schema) {
  return eligibleSearchFields(schema)
    .filter(({ field }) => field.searchable)
    .map(({ field }) => field.id);
}

function sameFieldSelection(first, second) {
  if (first.length !== second.length) {
    return false;
  }
  const expected = new Set(second);
  return first.every((fieldId) => expected.has(fieldId));
}

function activeSearchFieldIds(schema = state.schema) {
  const eligible = new Set(
    eligibleSearchFields(schema).map(({ field }) => field.id),
  );
  const selected = Array.isArray(state.searchFieldIds)
    ? state.searchFieldIds
    : defaultSearchFieldIds(schema);
  return selected.filter((fieldId) => eligible.has(fieldId));
}

function updateSearchFieldChooserLabel() {
  const count = activeSearchFieldIds().length;
  const description = Array.isArray(
    state.searchFieldIds,
  )
    ? `حقول البحث: مخصصة (${count})`
    : count
      ? `حقول البحث: الافتراضية (${count})`
      : "حقول البحث: لا يوجد افتراضي";
  elements.chooseSearchFieldsText.textContent = description;
  elements.chooseSearchFieldsButton.title = description;
  elements.chooseSearchFieldsButton.setAttribute("aria-label", description);
}

function toggleSearchPanel() {
  const collapsed = elements.searchPanel.dataset.collapsed !== "true";
  elements.searchPanel.dataset.collapsed = String(collapsed);
  elements.searchPanel
    .querySelector("[data-collapse-search-panel]")
    ?.setAttribute("aria-expanded", String(!collapsed));
}

function currentSearchControlValues() {
  const values = {};
  elements.searchFields
    .querySelectorAll("[data-value-control]")
    .forEach((control) => {
      values[control.dataset.fieldId] = controlValue(control);
    });
  return values;
}

function resetSearchResultDisplay() {
  state.searchMatches = [];
  state.searchResultIndex = 0;
  state.searchResultsTruncated = false;
  elements.searchResults.replaceChildren();
  elements.searchResultPager.hidden = true;
  elements.searchSummary.textContent =
    "أدخل معيارًا واحدًا أو أكثر ثم اضغط بحث.";
}

function renderSearchFields(options = {}) {
  const previousValues =
    options.preserveValues === false ? {} : currentSearchControlValues();
  elements.searchFields.replaceChildren();
  const eligible = eligibleSearchFields();
  const selectedIds = activeSearchFieldIds();
  const selected = new Set(selectedIds);
  elements.searchPanel.hidden = !hasConfiguredFields();
  elements.searchFieldsEmpty.hidden = selectedIds.length !== 0;
  elements.entrySearchRecordId.closest(".field").hidden = !state.entrySearchRecordIdEnabled;
  for (const { category, field } of eligible) {
    if (!selected.has(field.id)) {
      continue;
    }
    const wrapper = createFieldElement(field, "search", category.id);
    const label = wrapper.querySelector("label");
    label.textContent = field.label;
    elements.searchFields.append(wrapper);
    if (Object.prototype.hasOwnProperty.call(previousValues, field.id)) {
      setControlValue(
        wrapper.querySelector("[data-value-control]"),
        previousValues[field.id],
      );
    }
  }
  updateSearchFieldChooserLabel();
  elements.searchButton.disabled =
    state.searching ||
    state.savingRecord ||
    state.loadingRecord;
}

function renderSearchFieldOptions() {
  elements.searchFieldOptions.replaceChildren();
  const selectedFields = new Set(activeSearchFieldIds());
  const systemGroup = document.createElement("details");
  systemGroup.className = "search-field-option-group tree-option-group";
  systemGroup.open = false;
  const systemTitle = document.createElement("summary");
  const systemTitleLabel = document.createElement("label");
  systemTitleLabel.className = "check-field";
  const systemMaster = document.createElement("input");
  systemMaster.type = "checkbox";
  systemMaster.dataset.entrySearchCategory = "system";
  systemTitleLabel.append(systemMaster, document.createTextNode("بيانات السجل"));
  systemTitle.append(systemTitleLabel);
  const systemGrid = document.createElement("div");
  systemGrid.className = "search-field-option-grid";
  [["record_id", "ID"]].forEach(([id, text]) => {
    const label = document.createElement("label");
    label.className = "check-field";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.dataset.systemSearchOption = id;
    input.checked = state.entrySearchRecordIdEnabled !== false;
    label.append(input, document.createTextNode(text));
    systemGrid.append(label);
  });
  systemGroup.append(systemTitle, systemGrid);
  elements.searchFieldOptions.append(systemGroup);
  for (const category of allCategories(state.schema)) {
    const fields = category.fields.filter(
      (field) =>
        field.type !== "file" &&
        field.type !== "system_record_code",
    );
    if (!fields.length) {
      continue;
    }
    const group = document.createElement("details");
    group.className = "search-field-option-group tree-option-group";
    group.open = false;
    const title = document.createElement("summary");
    const titleLabel = document.createElement("label");
    titleLabel.className = "check-field";
    const master = document.createElement("input");
    master.type = "checkbox";
    master.dataset.entrySearchCategory = category.id;
    titleLabel.append(master, document.createTextNode(category.label));
    title.append(titleLabel);
    const grid = document.createElement("div");
    grid.className = "search-field-option-grid";
    for (const field of fields) {
      const option = document.createElement("label");
      option.className = "check-field";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.dataset.searchFieldOption = field.id;
      checkbox.checked = selectedFields.has(field.id);
      const label = document.createElement("span");
      label.textContent = field.searchable
        ? `${field.label} — افتراضي`
        : field.label;
      option.append(checkbox, label);
      grid.append(option);
    }
    group.append(title, grid);
    elements.searchFieldOptions.append(group);
  }
  elements.searchFieldOptions.querySelectorAll(".search-field-option-group").forEach((group) => {
    const master = group.querySelector("[data-entry-search-category]");
    const choices = [...group.querySelectorAll('.search-field-option-grid input[type="checkbox"]')];
    const checked = choices.filter((choice) => choice.checked).length;
    if (master) {
      master.checked = choices.length > 0 && checked === choices.length;
      master.indeterminate = checked > 0 && checked < choices.length;
    }
  });
}

function handleEntrySearchCategorySelection(event) {
  const group = event.target.closest(".search-field-option-group");
  if (!group) return;
  const master = group.querySelector("[data-entry-search-category]");
  const fields = [...group.querySelectorAll('.search-field-option-grid input[type="checkbox"]')];
  if (event.target === master) {
    fields.forEach((field) => { field.checked = master.checked; });
    master.indeterminate = false;
    return;
  }
  if (!fields.includes(event.target)) return;
  const selected = fields.filter((field) => field.checked).length;
  master.checked = selected === fields.length;
  master.indeterminate = selected > 0 && selected < fields.length;
}

function openSearchFieldsDialog() {
  renderSearchFieldOptions();
  elements.searchFieldsDialog.showModal();
}

elements.searchFieldOptions?.addEventListener("change", handleEntrySearchCategorySelection);

function applyTemporarySearchFields() {
  const selected = [
    ...elements.searchFieldOptions.querySelectorAll(
      "[data-search-field-option]:checked",
    ),
  ].map((checkbox) => checkbox.dataset.searchFieldOption);
  const recordIdEnabled = Boolean(elements.searchFieldOptions.querySelector('[data-system-search-option="record_id"]')?.checked);
  if (!selected.length && !recordIdEnabled) {
    showToast("اختر حقل بحث واحدًا على الأقل.", "error");
    return;
  }
  const defaults = defaultSearchFieldIds();
  state.searchFieldIds = sameFieldSelection(selected, defaults)
    ? null
    : selected;
  state.entrySearchRecordIdEnabled = recordIdEnabled;
  renderSearchFields();
  resetSearchResultDisplay();
  elements.searchFieldsDialog.close();
}

function resetTemporarySearchFields() {
  state.searchFieldIds = null;
  state.entrySearchRecordIdEnabled = true;
  renderSearchFields();
  resetSearchResultDisplay();
  elements.searchFieldsDialog.close();
}

function searchValues() {
  const criteria = {
    _include_archived: elements.includeArchivedSearch.checked,
    _search_field_ids: activeSearchFieldIds(),
    _record_code: state.entrySearchRecordIdEnabled ? elements.entrySearchRecordId.value.trim() : "",
  };
  elements.searchFields
    .querySelectorAll("[data-value-control]")
    .forEach((control) => {
      criteria[control.dataset.fieldId] = controlValue(control);
    });
  return criteria;
}

function clearSearch() {
  elements.searchFields
    .querySelectorAll("[data-value-control]")
    .forEach((control) => {
      setControlValue(control, "");
    });
  elements.includeArchivedSearch.checked = false;
  elements.entrySearchRecordId.value = "";
  resetSearchResultDisplay();
}

function setSearching(searching) {
  state.searching = searching;
  elements.searchButton.disabled =
    searching ||
    state.savingRecord ||
    state.loadingRecord;
  elements.clearSearchButton.disabled = searching;
  elements.searchSpinner.hidden = !searching;
  elements.searchButton.querySelector("svg").hidden = searching;
  elements.searchButtonText.textContent = searching ? "جاري البحث…" : "بحث";
  const label = searching ? "جاري البحث…" : "بحث";
  elements.searchButton.title = label;
  elements.searchButton.setAttribute("aria-label", label);
}

function renderCurrentSearchResult() {
  elements.searchResults.replaceChildren();
  const matches = state.searchMatches;
  if (!matches.length) {
    const empty = document.createElement("p");
    empty.className = "search-empty";
    empty.textContent = `لم يُعثر على ${entityName()} يطابق معايير البحث.`;
    elements.searchResults.append(empty);
    elements.searchSummary.textContent = "لا توجد نتائج";
    elements.searchResultPager.hidden = true;
    return;
  }
  state.searchResultIndex = Math.max(
    0,
    Math.min(state.searchResultIndex, matches.length - 1),
  );
  elements.searchSummary.textContent = state.searchResultsTruncated
    ? `ظهرت أول ${matches.length} نتيجة. أضف معيارًا آخر لتضييق البحث.`
    : `عدد النتائج: ${matches.length}`;
  const match = matches[state.searchResultIndex];
  const card = document.createElement("article");
  card.className = "search-result-card";
  card.dataset.searchRecordCode = match.record_code;
  const open = document.createElement("button");
  open.type = "button";
  open.className = "search-result-open";
  open.dataset.openSearchRecord = match.record_code;
  const title = document.createElement("span");
  title.className = "search-result-name";
  title.textContent = match.title || match.record_code;
  open.append(title);
  if (match.archived) {
    const archivedBadge = document.createElement("span");
    archivedBadge.className = "archived-badge";
    archivedBadge.textContent = "مؤرشف";
    open.append(archivedBadge);
  }
  (match.details || []).forEach((detail) => {
    if (String(detail.value ?? "").trim() === "") {
      return;
    }
    const line = document.createElement("span");
    line.className = "search-result-detail";
    line.textContent = `${detail.label}: ${detail.value}`;
    open.append(line);
  });
  const copyId = document.createElement("button");
  copyId.type = "button";
  copyId.className = "search-result-id";
  copyId.dataset.copyRecordCode = match.record_code;
  copyId.dir = "ltr";
  copyId.title = "نسخ ID";
  copyId.textContent = match.record_code;
  const readonly = document.createElement("button");
  readonly.type = "button";
  readonly.className = "search-result-readonly";
  readonly.dataset.readonlyRecord = match.record_code;
  readonly.title = "فتح للقراءة فقط";
  readonly.setAttribute("aria-label", "فتح السجل للقراءة فقط");
  const readonlyIcon = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "svg",
  );
  readonlyIcon.setAttribute("aria-hidden", "true");
  readonlyIcon.setAttribute("class", "action-icon");
  const readonlyUse = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "use",
  );
  readonlyUse.setAttribute("href", "#icon-open");
  readonlyIcon.append(readonlyUse);
  readonly.append(readonlyIcon);
  const footer = document.createElement("div");
  footer.className = "search-result-footer";
  footer.append(copyId, readonly);
  card.append(open, footer);
  if (match.record_code === state.selectedRecordCode) {
    card.classList.add("search-result-card-selected");
  }
  elements.searchResults.append(card);
  elements.searchResultPager.hidden = matches.length <= 1;
  elements.searchResultPosition.textContent = `${state.searchResultIndex + 1} / ${matches.length}`;
  elements.previousSearchResult.disabled = state.searchResultIndex === 0;
  elements.nextSearchResult.disabled =
    state.searchResultIndex === matches.length - 1;
}

function renderSearchResults(result) {
  state.searchMatches = Array.isArray(result.matches) ? result.matches : [];
  state.searchResultIndex = 0;
  state.searchResultsTruncated = Boolean(result.truncated);
  renderCurrentSearchResult();
}

function moveSearchResult(offset) {
  state.searchResultIndex += offset;
  renderCurrentSearchResult();
}

async function copyRecordCode(code) {
  try {
    await navigator.clipboard.writeText(code);
  } catch (_error) {
    const helper = document.createElement("textarea");
    helper.value = code;
    helper.style.position = "fixed";
    helper.style.opacity = "0";
    document.body.append(helper);
    helper.select();
    document.execCommand("copy");
    helper.remove();
  }
  showToast(`تم نسخ ID: ${code}`);
}

async function searchRecords() {
  if (state.searching || state.savingRecord || state.loadingRecord) {
    return;
  }
  const criteria = searchValues();
  const hasCriteria = Object.entries(criteria).some(
    ([key, value]) =>
      ![
        "_include_archived",
        "_search_field_ids",
      ].includes(key) &&
      (Array.isArray(value)
        ? value.length > 0
        : String(value ?? "").trim() !== ""),
  );
  if (!hasCriteria) {
    showToast("أدخل معيار بحث واحدًا على الأقل.", "error");
    return;
  }
  setSearching(true);
  try {
    const response = await fetch("/api/search", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(criteria),
    });
    renderSearchResults(await responseJson(response));
  } catch (error) {
    reportClientError("record-search", error);

    showToast(error.message, "error");
  } finally {
    setSearching(false);
  }
}

function clearSelectedSearchCard() {
  elements.searchResults
    .querySelectorAll(".search-result-card-selected")
    .forEach((card) => card.classList.remove("search-result-card-selected"));
}

function markSelectedSearchCard(code) {
  clearSelectedSearchCard();
  elements.searchResults
    .querySelector(`[data-search-record-code="${attributeSafe(code)}"]`)
    ?.classList.add("search-result-card-selected");
}
function populateControlsInDependencyOrder(controls, values) {
  const ordinaryControls = [];
  const dependentControls = [];

  controls.forEach((control) => {
    const field = fieldById(control.dataset.fieldId, state.schema);

    if (field?.option_filter) {
      dependentControls.push(control);
    } else {
      ordinaryControls.push(control);
    }
  });

  ordinaryControls.forEach((control) => {
    setControlValue(control, values[control.dataset.fieldId] ?? "");
  });

  refreshAllDependentOptions(false);

  dependentControls.forEach((control) => {
    refreshDependentControl(control, false);
    setControlValue(control, values[control.dataset.fieldId] ?? "");
  });
}
function populateMain(values) {
  const controls = [
    ...elements.recordForm.querySelectorAll(
      '[data-value-control][data-scope="main"]',
    ),
  ];

  populateControlsInDependencyOrder(controls, values);
}

function populateRelated(related) {
  [...document.querySelectorAll('[data-related-records][data-parent-child-id=""]')]
    .forEach((records) => records.replaceChildren());
  const repeatable = state.schema.categories
    .filter((candidate) => candidate.kind === "repeatable")
    .sort((first, second) => {
      const depth = (category) => {
        let result = 0;
        let current = category;
        const seen = new Set();
        while (current?.parent_category_id && !seen.has(current.id)) {
          seen.add(current.id);
          current = categoryById(current.parent_category_id, state.schema);
          result += 1;
        }
        return result;
      };
      return depth(first) - depth(second);
    });
  for (const category of repeatable) {
    const rows = Array.isArray(related[category.id])
      ? related[category.id]
      : [];
    rows.forEach((row) => addRelatedCard(category.id, row, {
      parentChildId: row.parent_child_id || "",
    }));
    if (category.auto_start) {
      [...document.querySelectorAll(
        `[data-related-records="${attributeSafe(category.id)}"]`,
      )].forEach((records) => {
        if (!directRelatedCards(records).length) {
          addRelatedCard(category.id, null, {
            markDirty: false,
            parentChildId: records.dataset.parentChildId || "",
          });
        }
      });
    }
  }
}

function attachmentApiUrl(path) {
  const url = new URL(
    `/api/${encodeURI(String(path || "")).replace(/%2F/gi, "/")}`,
    window.location.href,
  );
  if (state.activeSchemaId) {
    url.searchParams.set("schema_id", state.activeSchemaId);
  }
  return `${url.pathname}${url.search}`;
}

function attachmentViewerUrl(path) {
  const source = attachmentApiUrl(path);
  return `/attachment-viewer.html?source=${encodeURIComponent(source)}`;
}

function isImageAttachment(path) {
  return /\.(avif|bmp|gif|jpe?g|png|webp)$/i.test(storedFilename(path));
}

function renderAttachmentGallery() {
  elements.attachmentGalleryGrid.replaceChildren();
  if (!state.selectedRecordCode) {
    elements.attachmentGallery.hidden = true;
    return;
  }
  const controls = [
    ...elements.recordForm.querySelectorAll("[data-value-control]"),
  ].filter((control) => {
    const field = fieldById(control.dataset.fieldId, state.schema);
    return field?.type === "file" && control.value;
  });
  elements.attachmentGallery.hidden = controls.length === 0;

  for (const control of controls) {
    const field = fieldById(control.dataset.fieldId, state.schema);
    const category = categoryById(control.dataset.categoryId, state.schema);
    const card = control.closest(".related-card");
    const link = document.createElement("a");
    link.className = "gallery-card";
    link._attachmentHoverCard = () => attachmentHoverDetails(control);
    link.href = isImageAttachment(control.value)
      ? attachmentViewerUrl(control.value)
      : attachmentApiUrl(control.value);
    link.target = "_blank";
    link.rel = "noopener";

    if (isImageAttachment(control.value)) {
      const image = document.createElement("img");
      image.className = "gallery-preview";
      image.src = attachmentApiUrl(control.value);
      image.alt = `${category?.label || ""} — ${field?.label || ""}`;
      image.loading = "lazy";
      link.append(image);
    } else {
      const icon = document.createElement("div");
      icon.className = "gallery-file-icon";
      icon.textContent = /\.pdf$/i.test(control.value) ? "PDF" : "FILE";
      link.append(icon);
    }
    const body = document.createElement("div");
    body.className = "gallery-card-body";
    const title = document.createElement("strong");
    title.textContent = field?.label || storedFilename(control.value);
    const detail = document.createElement("span");
    detail.textContent = category?.label || "";
    const filename = document.createElement("span");
    filename.textContent = storedFilename(control.value);
    body.append(title, detail, filename);
    link.append(body);
    elements.attachmentGalleryGrid.append(link);
  }
}
function formatRecordTimestamp(value) {
  if (!value) {
    return "—";
  }

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return String(value);
  }

  return new Intl.DateTimeFormat("ar", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(parsed);
}

function displayRecordMetadata(record = null) {
  state.currentRecordMetadata = {
    record_code:
      record?.record_code || elements.recordCode.value || "",
    created_at: record?.created_at || "",
    updated_at: record?.updated_at || "",
  };
  refreshSystemFieldControls();
  if (state.mode === "entry" || state.mode === "readonly") {
    updateHeaderContext(state.mode);
  }
}
function loadRecord(code, options = {}) {
  if (state.recordDirty && !options.force && !options.skipNavigationGuard) {
    queueRecordNavigation(() => {
      void performLoadRecord(code, {
        ...options,
        skipNavigationGuard: true,
      });
    });
    return Promise.resolve(false);
  }
  return performLoadRecord(code, options);
}

function recentRecordTitle(record) {
  const mainFields = (state.schema?.categories || [])
    .filter((category) => category.kind === "main")
    .flatMap((category) => category.fields || []);
  const titleFields = mainFields.filter(
    (field) => field.result_title && String(record.main?.[field.id] ?? "").trim(),
  );
  const fallbackField = mainFields.find(
    (field) =>
      !isSystemField(field) &&
      field.type !== "file" &&
      String(record.main?.[field.id] ?? "").trim(),
  );
  const fields = titleFields.length ? titleFields : (fallbackField ? [fallbackField] : []);
  return fields.map((field) => {
    const raw = record.main?.[field.id];
    return ["select", "yes_no"].includes(field.type)
      ? optionLabelForValue(field, raw)
      : String(raw ?? "").trim();
  }).filter(Boolean).join(" ");
}

async function performLoadRecord(code, options = {}) {
  if (state.loadingRecord || (state.savingRecord && !options.force)) {
    return false;
  }
  state.loadingRecord = true;
  try {
    const response = await fetch(`/api/records/${encodeURIComponent(code)}`, {
      cache: "no-store",
    });
    const record = await responseJson(response);
    state.suppressReset = true;
    elements.recordForm.reset();
    state.suppressReset = false;
    state.selectedRecordCode = record.record_code;
    state.currentRecordArchived = Boolean(record.archived);
    elements.recordCode.value = record.record_code;
    displayRecordMetadata(record);
    renderEntryForm();
    populateMain(record.main);
    state.loadedMainValues = deepClone(record.main || {});
    populateRelated(record.related);
    updateConditionalVisibility();
    renderAttachmentGallery();
    updateRecordButtonLabels();
    markSelectedSearchCard(record.record_code);
    rememberRecentRecord({
      record_code: record.record_code,
      title: options.title || recentRecordTitle(record),
    });
    if (!options.silent) {
      showToast(`تم اختيار ${entityName()}: ${record.record_code}`);
    }
    if (options.scroll !== false) {
      resetPageScroll(false);
    }
    clearLocalDraft();
    state.recordDirty = false;
    renderAllSchemaTabs();
    if (state.mode === "entry") {
      updateHeaderContext("entry");
    }
    return true;
  } catch (error) {
    reportClientError("record-load", error, `record_code=${code}`);

    showToast(error.message, "error");
    return false;
  } finally {
    state.loadingRecord = false;
  }
}

async function controlPayloadValue(control) {
  const field = fieldById(control.dataset.fieldId, state.schema);
  if (field?.type !== "file") {
    return controlValue(control);
  }
  const payload = { stored_path: control.value || "" };
  if (control._selectedFile) {
    payload.upload = {
      name: control._uploadName || control._selectedFile.name,
      data: await readFileAsBase64(control._selectedFile),
    };
  }
  return payload;
}

async function collectMainPayload() {
  const values = {};
  for (const control of elements.recordForm.querySelectorAll(
    '[data-value-control][data-scope="main"]',
  )) {
    if (isSystemField(fieldById(control.dataset.fieldId, state.schema))) {
      continue;
    }
    values[control.dataset.fieldId] = await controlPayloadValue(control);
  }
  return values;
}

async function collectRelatedPayload() {
  const related = {};
  for (const category of state.schema.categories.filter(
    (candidate) => candidate.kind === "repeatable",
  )) {
    const rows = [];
    for (const records of document.querySelectorAll(
      `[data-related-records="${attributeSafe(category.id)}"]`,
    )) {
      for (const card of directRelatedCards(records)) {
        const values = {};
        for (const control of directCardControls(card)) {
          values[control.dataset.fieldId] = await controlPayloadValue(control);
        }
        rows.push({
          _child_id: card.dataset.childId || "",
          _client_generated: card.dataset.clientGenerated === "true",
          parent_child_id: card.dataset.parentChildId || "",
          linked_record_code: card.dataset.linkedRecordCode || "",
          values,
        });
      }
    }
    related[category.id] = rows;
  }
  return related;
}

function setRecordSaving(saving) {
  state.savingRecord = saving;
  elements.saveRecordButton.disabled = saving;
  elements.resetFormButton.disabled = saving;
  elements.deleteRecordButton.disabled = saving;
  elements.archiveRecordButton.disabled = saving;
  elements.searchButton.disabled =
    saving || state.searching || state.loadingRecord;
  elements.saveSpinner.hidden = !saving;
  updateRecordButtonLabels();
}

function updateRecordButtonLabels() {
  const singular = entityName();
  const hasRecord = Boolean(state.selectedRecordCode);
  const builderUnlocked = Boolean(
    state.schema?.builder_access?.unlocked || state.schema?.developer_mode,
  );
  if (state.savingRecord) {
    elements.saveButtonText.textContent = "جاري الحفظ…";
  } else if (hasRecord) {
    elements.saveButtonText.textContent = "حفظ التعديلات";
  } else {
    elements.saveButtonText.textContent = `حفظ ${singular}`;
  }
  elements.archiveRecordButton.hidden = !hasRecord;
  elements.archiveButtonText.textContent = state.currentRecordArchived
    ? `استعادة ${singular}`
    : `أرشفة ${singular}`;
  elements.archiveRecordButton.classList.toggle(
    "button-restore",
    state.currentRecordArchived,
  );
  elements.deleteRecordButton.hidden = !hasRecord || !builderUnlocked;
  elements.deleteButtonText.textContent = `حذف ${singular} نهائيًا`;
  elements.resetButtonText.textContent = `${singular} جديد`;
  elements.saveNote.hidden = !state.currentRecordArchived;
  elements.saveNote.textContent = state.currentRecordArchived
    ? "هذا السجل مؤرشف، ويمكن تعديله أو استعادته."
    : "يمكن الحفظ في أي وقت ما لم تُعرَّف حقول مطلوبة.";
}

function draftValue(control) {
  const field = fieldById(control.dataset.fieldId, state.schema);

  if (field?.type === "file") {
    // Preserve only an already-saved attachment path.
    // Browser security does not permit restoring a newly selected file.
    return control.value || "";
  }

  return controlValue(control);
}

function valueHasDraftContent(value) {
  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (typeof value === "boolean") {
    return value;
  }

  return String(value ?? "").trim() !== "";
}

function collectDraftSnapshot() {
  const main = {};

  elements.recordForm
    .querySelectorAll('[data-value-control][data-scope="main"]')
    .forEach((control) => {
      if (isSystemField(fieldById(control.dataset.fieldId, state.schema))) {
        return;
      }
      main[control.dataset.fieldId] = draftValue(control);
    });

  const related = {};

  for (const category of state.schema.categories.filter(
    (candidate) => candidate.kind === "repeatable",
  )) {
    const rows = [];

    for (const records of document.querySelectorAll(
      `[data-related-records="${attributeSafe(category.id)}"]`,
    )) {
      for (const card of directRelatedCards(records)) {
        const values = {};

        directCardControls(card).forEach((control) => {
          values[control.dataset.fieldId] = draftValue(control);
        });

        rows.push({
          _child_id: card.dataset.childId || "",
          _client_generated: card.dataset.clientGenerated === "true",
          parent_child_id: card.dataset.parentChildId || "",
          linked_record_code:
            directCardControls(card, "[data-linked-record-code]")[0]?.value.trim() || "",
          related_person_mode: card.dataset.relatedPersonMode || "manual",
          values,
        });
      }
    }

    related[category.id] = rows;
  }

  return {
    version: 1,
    schema_revision: state.schema?.revision ?? null,
    saved_at: new Date().toISOString(),
    selected_record_code: state.selectedRecordCode,
    current_record_archived: state.currentRecordArchived,
    current_record_metadata: deepClone(state.currentRecordMetadata),
    record_code: elements.recordCode.value,
    main,
    related,
  };
}

function draftHasContent(draft) {
  const mainHasContent = Object.entries(draft.main || {}).some(([fieldId, value]) => {
    const field = fieldById(fieldId, state.schema);
    if (
      field?.type === "user_name" &&
      String(value || "").trim() === String(state.auditUsers?.current_user || "").trim()
    ) {
      return false;
    }
    return valueHasDraftContent(value);
  });

  if (mainHasContent) {
    return true;
  }

  return Object.values(draft.related || {}).some(
    (rows) =>
      Array.isArray(rows) &&
      rows.some((row) => {
        const hasValue = Object.values(row.values || {}).some(
          valueHasDraftContent,
        );

        return hasValue || Boolean(row.linked_record_code);
      }),
  );
}

function updateDraftStatus(message) {
  if (elements.draftStatus) {
    elements.draftStatus.textContent = message;
  }
}

function clearLocalDraft() {
  try {
    localStorage.removeItem(schemaStorageKey(DRAFT_STORAGE_KEY));
  } catch (_error) {
    // Ignore unavailable browser storage.
  }

  window.clearTimeout(state.draftDebounceTimer);
  state.draftDebounceTimer = null;
  state.recordDirty = false;
  renderAllSchemaTabs();

  updateDraftStatus("لا توجد مسودة محلية.");
  if (state.mode === "entry") {
    updateHeaderContext("entry");
  }
}

function saveDraftLocally() {
  if (
    state.pendingSchemaViews ||
    !state.schema ||
    !state.recordDirty ||
    state.restoringDraft ||
    state.schema.app?.draft_autosave === false
  ) {
    return;
  }

  const draft = collectDraftSnapshot();

  if (!draftHasContent(draft)) {
    clearLocalDraft();
    return;
  }

  try {
    localStorage.setItem(schemaStorageKey(DRAFT_STORAGE_KEY), JSON.stringify(draft));

    const time = new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });

    updateDraftStatus(`حُفظت المسودة محليًا عند ${time}.`);
  } catch (_error) {
    updateDraftStatus("تعذّر حفظ المسودة محليًا.");
  }
}

function scheduleDraftSave() {
  if (state.restoringDraft) {
    return;
  }

  if (!state.selectedRecordCode && !draftHasContent(collectDraftSnapshot())) {
    state.recordDirty = false;
    updateDraftStatus("لا توجد مسودة محلية.");
    renderAllSchemaTabs();
    if (state.mode === "entry") updateHeaderContext("entry");
    return;
  }

  state.recordDirty = true;
  renderAllSchemaTabs();
  if (state.mode === "entry") {
    updateHeaderContext("entry");
  }

  if (state.schema?.app?.draft_autosave === false) {
    updateDraftStatus("توجد تغييرات غير محفوظة.");
    return;
  }

  window.clearTimeout(state.draftDebounceTimer);

  state.draftDebounceTimer = window.setTimeout(
    saveDraftLocally,
    DRAFT_INPUT_DELAY_MS,
  );

  updateDraftStatus("توجد تغييرات غير محفوظة.");
}

function readLocalDraft() {
  try {
    const raw = localStorage.getItem(schemaStorageKey(DRAFT_STORAGE_KEY));

    if (!raw) {
      return null;
    }

    const draft = JSON.parse(raw);

    if (!draft || draft.version !== 1) {
      return null;
    }

    return draft;
  } catch (_error) {
    return null;
  }
}

function restoreDraftSnapshot(draft, options = {}) {
  if (!draft || !state.schema) {
    return;
  }

  if (
    draft.schema_revision !== null &&
    state.schema.revision !== undefined &&
    draft.schema_revision !== state.schema.revision
  ) {
    updateDraftStatus("توجد مسودة قديمة لا تطابق تصميم التطبيق الحالي.");
    return;
  }

  state.restoringDraft = true;

  try {
    state.selectedRecordCode = draft.selected_record_code || null;

    state.currentRecordArchived = Boolean(draft.current_record_archived);

    elements.recordCode.value = draft.record_code || generateRecordCode();
    displayRecordMetadata(draft.current_record_metadata || null);

    renderEntryForm();
    populateMain(draft.main || {});
    populateRelated(draft.related || {});
    updateConditionalVisibility();
    renderAttachmentGallery();
    updateRecordButtonLabels();

    state.recordDirty = true;
    renderAllSchemaTabs();

    const savedTime = draft.saved_at
      ? new Date(draft.saved_at).toLocaleString()
      : "";

    updateDraftStatus(
      savedTime
        ? `تمت استعادة مسودة محفوظة في ${savedTime}.`
        : "تمت استعادة مسودة غير محفوظة.",
    );

    if (options.notify !== false) {
      showToast("تمت استعادة آخر مسودة غير محفوظة.");
    }
  } finally {
    state.restoringDraft = false;
  }
}

function restoreLocalDraft() {
  if (state.skipNextLocalDraftRestore) {
    state.skipNextLocalDraftRestore = false;
    return;
  }
  restoreDraftSnapshot(readLocalDraft());
}
async function saveCurrentRecord() {
  if (state.savingRecord || !state.schema || !hasConfiguredFields()) {
    return false;
  }
  if (!(await validateRelatedPersonCardsBeforeSave())) {
    return false;
  }
  const invalidControl = [
    ...elements.recordForm.querySelectorAll("[data-value-control]"),
  ].find((control) => !validateEntryControl(control, false));

  if (invalidControl) {
    expandEntryCategoryForControl(invalidControl);
    validateEntryControl(invalidControl, true);
    invalidControl.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
    // Inline errors identify invalid fields without moving focus.
    return false;
  }
  const creatingRecord = !state.selectedRecordCode;
  const submittedMain = await collectMainPayload();
  const changedGlobalRefs = [];
  if (!creatingRecord) {
    for (const category of state.schema.categories.filter((item) => item.kind === "main")) {
      for (const field of category.fields) {
        if (field.global_ref && JSON.stringify(submittedMain[field.id]) !== JSON.stringify(state.loadedMainValues[field.id])) {
          changedGlobalRefs.push(field.global_ref);
        }
      }
    }
  }
  const propagateGlobalValues = changedGlobalRefs.length
    ? await requestConfirmation(
        "تغيّرت قيمة حقل ذي تعريف عام. هل تريد نسخ القيمة الجديدة إلى ملفات الشخص نفسه في التصاميم الأخرى؟",
        { title: "تحديث القيم العامة", confirmLabel: "نسخ القيمة", danger: false },
      )
    : false;
  setRecordSaving(true);
  try {
    const response = await fetch("/api/records", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        mode: state.selectedRecordCode ? "update" : "create",
        record_code: elements.recordCode.value,
        client_generated_code: creatingRecord,
        expected_updated_at: state.selectedRecordCode
          ? state.currentRecordMetadata.updated_at
          : "",
        main: submittedMain,
        related: await collectRelatedPayload(),
        propagate_global_values: propagateGlobalValues,
        propagate_global_refs: changedGlobalRefs,
      }),
    });
    const result = await responseJson(response);
    if (creatingRecord && result.action === "created" && state.schema?.stats) {
      state.schema.stats.record_count =
        Number(state.schema.stats.record_count || 0) + 1;
    }
    state.selectedRecordCode = result.record_code;
    elements.recordCode.value = result.record_code;
    await loadRecord(result.record_code, {
      silent: true,
      scroll: false,
      force: true,
    });
    clearLocalDraft();
    updateRecordButtonLabels();
    showToast(
      result.action === "updated"
        ? `تم حفظ التعديلات. ID: ${result.record_code}`
        : `تم حفظ ${entityName()}. يمكنك تعديله مباشرةً. ID: ${result.record_code}`,
    );
    return true;
  } catch (error) {
    reportClientError("record-save", error);

    showToast(error.message, "error");
    return false;
  } finally {
    setRecordSaving(false);
  }
}

async function archiveCurrentRecord() {
  if (!state.selectedRecordCode || state.savingRecord) {
    return;
  }
  const wasArchived = state.currentRecordArchived;
  const archived = !wasArchived;
  const action = archived ? "أرشفة" : "استعادة";
  if (
    !(await requestConfirmation(
      `هل تريد ${action} ${entityName()} ${state.selectedRecordCode}؟`,
      { title: `${action} السجل`, confirmLabel: action },
    ))
  ) {
    return;
  }
  setRecordSaving(true);
  try {
    const response = await fetch("/api/archive", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        record_code: state.selectedRecordCode,
        archived,
        expected_updated_at: state.currentRecordMetadata.updated_at,
      }),
    });
    const result = await responseJson(response);
    state.currentRecordArchived = Boolean(result.archived);
    state.currentRecordMetadata.updated_at = result.updated_at || "";
    if (state.schema?.archive_stats && wasArchived !== state.currentRecordArchived) {
      state.schema.archive_stats.archived_record_count = Math.max(
        0,
        Number(state.schema.archive_stats.archived_record_count || 0) +
          (state.currentRecordArchived ? 1 : -1),
      );
    }
    updateRecordButtonLabels();
    if (archived && !elements.includeArchivedSearch.checked) {
      state.searchMatches = state.searchMatches.filter(
        (match) => match.record_code !== state.selectedRecordCode,
      );
      renderCurrentSearchResult();
    } else {
      const match = state.searchMatches.find(
        (candidate) => candidate.record_code === state.selectedRecordCode,
      );
      if (match) {
        match.archived = archived;
        renderCurrentSearchResult();
      }
    }
    showToast(
      archived ? `تمت أرشفة ${entityName()}.` : `تمت استعادة ${entityName()}.`,
    );
  } catch (error) {
    showToast(error.message, "error");
  } finally {
    setRecordSaving(false);
  }
}

async function deleteCurrentRecord() {
  if (!state.selectedRecordCode || state.savingRecord) {
    return;
  }
  const code = state.selectedRecordCode;
  const wasArchived = state.currentRecordArchived;
  if (
    !(await requestConfirmation(
      `هل تريد حذف ${entityName()} ${code} نهائيًا من جميع الجداول والملفات؟`,
      { title: "حذف السجل نهائيًا", confirmLabel: "حذف السجل" },
    ))
  ) {
    return;
  }
  setRecordSaving(true);
  try {
    const response = await fetch(`/api/records/${encodeURIComponent(code)}`, {
      method: "DELETE",
    });
    const result = await responseJson(response);
    if (state.schema?.stats) {
      state.schema.stats.record_count = Math.max(
        0,
        Number(state.schema.stats.record_count || 0) - 1,
      );
    }
    if (wasArchived && state.schema?.archive_stats) {
      state.schema.archive_stats.archived_record_count = Math.max(
        0,
        Number(state.schema.archive_stats.archived_record_count || 0) - 1,
      );
    }
    state.searchMatches = state.searchMatches.filter(
      (match) => match.record_code !== code,
    );
    state.fullSearchMatches = state.fullSearchMatches.filter(
      (match) => match.record_code !== code,
    );
    removeRecentRecordHistory(code, state.activeSchemaId || "legacy");
    try { localStorage.removeItem(SEARCH_HISTORY_STORAGE_KEY); } catch (_error) { /* authoritative history is on disk */ }
    await loadSearchHistory().catch(() => {});
    renderCurrentSearchResult();
    renderFullSearchResults();
    newRecord();
    showToast(
      `تم حذف ${entityName()} و${result.deleted_related_rows} سجل مرتبط.`,
    );
  } catch (error) {
    showToast(error.message, "error");
  } finally {
    setRecordSaving(false);
  }
}

function newRecord() {
  state.suppressReset = true;
  elements.recordForm.reset();
  state.suppressReset = false;
  state.selectedRecordCode = null;
  state.currentRecordArchived = false;
  elements.recordCode.value = generateRecordCode();
  displayRecordMetadata();
  state.loadedMainValues = {};
  renderEntryForm();
  renderAttachmentGallery();
  clearSelectedSearchCard();
  clearLocalDraft();
  updateRecordButtonLabels();
  resetPageScroll(false);
}

function requestNewRecord() {
  const open = () => {
    newRecord();
    showToast(`تم فتح ${entityName()} جديد.`);
  };
  const choose = () => {
    if (activeWorkspaceSchemas().length > 1) {
      elements.newProfileChoiceDialog.showModal();
    } else {
      open();
    }
  };
  if (state.recordDirty) queueRecordNavigation(choose);
  else choose();
}

function handleFormReset(event) {
  event?.preventDefault();
  if (state.suppressReset) {
    return;
  }
  requestNewRecord();
}

/* core/filters.js */
const SHARED_FILTER_DATE_TYPES = new Set([
  "date_gregorian",
  "date_hijri",
  "date_persian",
  "system_created_at",
  "system_updated_at",
]);

function sharedFilterField(schema, fieldId) {
  for (const category of schema?.categories || []) {
    const field = (category.fields || []).find((candidate) => candidate.id === fieldId);
    if (field) return { category, field };
  }
  return null;
}

function sharedFilterActiveOptions(field) {
  if (field.type === "checkbox") {
    return [{ id: "true", label: checkboxDisplayMeaning(field, true) }, { id: "false", label: checkboxDisplayMeaning(field, false) }];
  }
  return (field.options || []).filter((option) => option.active !== false);
}

function sharedFilterSourceToken(sourceField, sourceControl) {
  if (!sourceField || !sourceControl) return "";
  const value = sourceControl.value;
  if (sourceField.type === "checkbox") return value;
  return value || "";
}

function sharedAllowedFilterOptions(field, schema, container) {
  const all = sharedFilterActiveOptions(field);
  const dependency = field.option_filter;
  if (!dependency?.source_field_id) return all;
  const sourceEntry = sharedFilterField(schema, dependency.source_field_id);
  const sourceControl = container.querySelector(
    `[data-shared-filter][data-field-id="${attributeSafe(dependency.source_field_id)}"] [data-filter-value]`,
  );
  if (!sourceEntry || !sourceControl) return all;
  const token = sharedFilterSourceToken(sourceEntry.field, sourceControl);
  if (!token) return all;
  const mapping = dependency.mappings?.[token];
  if (!mapping) return dependency.unmatched === "none" ? [] : all;
  const allowed = new Set(mapping);
  return all.filter((option) => allowed.has(option.id));
}

function sharedFilterValueControl(field) {
  if (["select", "yes_no", "checkbox", "checkbox_group"].includes(field.type)) {
    const select = document.createElement("select");
    select.className = "control shared-filter-value";
    select.dataset.filterValue = "true";
    if (field.type === "checkbox_group") {
      select.multiple = true;
      select.size = Math.min(6, Math.max(2, sharedFilterActiveOptions(field).length));
    } else {
      select.append(new Option("— الكل —", ""));
    }
    return select;
  }
  const input = document.createElement("input");
  input.className = "control shared-filter-value";
  input.dataset.filterValue = "true";
  input.autocomplete = "off";
  if (field.type === "number" && field.number_behavior?.storage !== "text") {
    input.type = "number";
    input.step = "any";
  } else if (field.type === "date_gregorian") {
    input.type = "date";
  } else {
    input.type = "text";
    if (SHARED_FILTER_DATE_TYPES.has(field.type)) input.placeholder = "YYYY-MM-DD";
  }
  return input;
}

function sharedFilterOperator(field) {
  if (field.type !== "number" && !SHARED_FILTER_DATE_TYPES.has(field.type)) return null;
  const select = document.createElement("select");
  select.className = "control shared-filter-operator";
  select.dataset.filterOperator = "true";
  const options = field.type === "number"
    ? [["equals", "="], ["greater_than", ">"], ["less_than", "<"], ["greater_or_equal", "≥"], ["less_or_equal", "≤"], ["between", "بين"]]
    : [["equals", "="], ["before", "قبل"], ["after", "بعد"], ["between", "بين"]];
  options.forEach(([value, label]) => select.append(new Option(label, value)));
  return select;
}

function populateSharedFilterOptions(wrapper, schema, container) {
  const entry = sharedFilterField(schema, wrapper.dataset.fieldId);
  const control = wrapper.querySelector("[data-filter-value]");
  if (!entry || !control || control.tagName !== "SELECT") return;
  const previous = new Set([...control.selectedOptions].map((option) => option.value));
  const multiple = control.multiple;
  control.replaceChildren();
  if (!multiple) control.append(new Option("— الكل —", ""));
  sharedAllowedFilterOptions(entry.field, schema, container).forEach((option) => {
    const item = new Option(option.label, option.id);
    item.selected = previous.has(option.id);
    control.append(item);
  });
  if (!multiple && previous.size) control.value = [...previous][0];
}

function refreshSharedDependentFilters(container, schema) {
  container.querySelectorAll("[data-shared-filter]").forEach((wrapper) => {
    const entry = sharedFilterField(schema, wrapper.dataset.fieldId);
    if (entry?.field.option_filter) populateSharedFilterOptions(wrapper, schema, container);
  });
}

function sharedFilterSuggestions(wrapper, schemaId, query = "") {
  const control = wrapper.querySelector("[data-filter-value]");
  const suggestions = wrapper.querySelector("[data-filter-suggestions]");
  if (!control || !suggestions || control.tagName === "SELECT") return;
  const requestId = String(Number(wrapper.dataset.suggestionRequest || 0) + 1);
  wrapper.dataset.suggestionRequest = requestId;
  const parameters = new URLSearchParams({
    field_id: wrapper.dataset.fieldId,
    query,
    limit: "30",
  });
  const headers = schemaId ? { "X-Schema-ID": schemaId } : {};
  void fetch(`/api/search/field-values?${parameters}`, { cache: "no-store", headers })
    .then(responseJson)
    .then((result) => {
      if (wrapper.dataset.suggestionRequest !== requestId) return;
      suggestions.replaceChildren();
      (result.values || []).forEach((item) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "shared-filter-suggestion";
        button.dataset.filterSuggestionValue = String(item.value ?? "");
        const label = document.createElement("span");
        label.textContent = item.label;
        const count = document.createElement("small");
        count.textContent = String(item.count || 0);
        button.append(label, count);
        suggestions.append(button);
      });
      if (!suggestions.childElementCount) {
        const empty = document.createElement("span");
        empty.className = "shared-filter-suggestions-empty";
        empty.textContent = "لا توجد قيم مطابقة.";
        suggestions.append(empty);
      }
      suggestions.hidden = false;
    })
    .catch(() => { suggestions.hidden = true; });
}

function applySharedFilterCriterion(wrapper, criterion) {
  if (criterion == null || criterion === "") return;
  const empty = wrapper.querySelector("[data-filter-empty]");
  const notEmpty = wrapper.querySelector("[data-filter-not-empty]");
  const operator = wrapper.querySelector("[data-filter-operator]");
  const control = wrapper.querySelector("[data-filter-value]");
  const upper = wrapper.querySelector("[data-filter-upper]");
  if (criterion && typeof criterion === "object" && !Array.isArray(criterion)) {
    const selectedOperator = criterion.empty === true ? "empty" : criterion.operator || "";
    empty.checked = selectedOperator === "empty";
    notEmpty.checked = selectedOperator === "not_empty";
    if (operator && !["empty", "not_empty"].includes(selectedOperator)) operator.value = selectedOperator || "equals";
    if (Object.prototype.hasOwnProperty.call(criterion, "value")) control.value = criterion.value ?? "";
    if (upper && Object.prototype.hasOwnProperty.call(criterion, "to")) upper.value = criterion.to ?? "";
    const values = Array.isArray(criterion.values) ? criterion.values : [];
    if (control.multiple) [...control.options].forEach((option) => { option.selected = values.includes(option.value); });
  } else if (Array.isArray(criterion) && control.multiple) {
    [...control.options].forEach((option) => { option.selected = criterion.includes(option.value); });
  } else {
    control.value = criterion;
  }
  const disabled = empty.checked || notEmpty.checked;
  [operator, control, upper].filter(Boolean).forEach((item) => { item.disabled = disabled; });
  if (upper) upper.hidden = operator?.value !== "between";
}

function createSharedFilterControl(field, schema, container, criterion, options) {
  const wrapper = document.createElement("section");
  wrapper.className = "field categorized-filter-control shared-filter-control";
  wrapper.dataset.sharedFilter = options.context || "shared";
  wrapper.dataset.fieldId = field.id;
  const heading = document.createElement("button");
  heading.type = "button";
  heading.className = "shared-filter-label";
  heading.dataset.removeSharedFilter = field.id;
  heading.title = "انقر لإزالة هذا المرشح";
  heading.textContent = field.label;
  wrapper.append(heading);

  const row = document.createElement("div");
  row.className = "shared-filter-input-row";
  const operator = sharedFilterOperator(field);
  const control = sharedFilterValueControl(field);
  if (operator) row.append(operator);
  row.append(control);
  const upper = control.cloneNode(true);
  upper.removeAttribute("data-filter-value");
  upper.dataset.filterUpper = "true";
  upper.placeholder = "إلى";
  upper.hidden = true;
  if (operator) row.append(upper);
  wrapper.append(row);

  const flags = document.createElement("div");
  flags.className = "shared-filter-flags";
  [["empty", "حقول فارغة"], ["notEmpty", "حقول غير فارغة"]].forEach(([kind, labelText]) => {
    const label = document.createElement("label");
    label.className = "check-field";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.dataset[kind === "empty" ? "filterEmpty" : "filterNotEmpty"] = field.id;
    label.append(input, document.createTextNode(labelText));
    flags.append(label);
  });
  wrapper.append(flags);

  const suggestions = document.createElement("div");
  suggestions.className = "shared-filter-suggestions";
  suggestions.dataset.filterSuggestions = field.id;
  suggestions.hidden = true;
  wrapper.append(suggestions);
  container.append(wrapper);
  if (control.tagName === "SELECT") populateSharedFilterOptions(wrapper, schema, options.rootContainer);
  applySharedFilterCriterion(wrapper, criterion);
  return wrapper;
}

function renderSharedFilterControls(options) {
  const { container, schema, fieldIds } = options;
  const previous = options.criteria || sharedFilterCriteria(container);
  container.replaceChildren();
  const selected = new Set(fieldIds || []);
  for (const category of schema?.categories || []) {
    const fields = (category.fields || []).filter((field) => selected.has(field.id));
    if (!fields.length) continue;
    const { group, grid } = createSchemaSearchFilterCategory(category.label, category.id, options.context || "shared");
    group.classList.add("shared-filter-category");
    container.append(group);
    fields.forEach((field) => createSharedFilterControl(field, schema, grid, previous[field.id], { ...options, rootContainer: container }));
  }
  container.querySelectorAll("[data-filter-operator]").forEach((operator) => {
    operator.addEventListener("change", () => {
      const wrapper = operator.closest("[data-shared-filter]");
      const upper = wrapper.querySelector("[data-filter-upper]");
      upper.hidden = operator.value !== "between";
      if (upper.hidden) upper.value = "";
    });
  });
  container.querySelectorAll("[data-filter-empty], [data-filter-not-empty]").forEach((flag) => {
    flag.addEventListener("change", () => {
      const wrapper = flag.closest("[data-shared-filter]");
      const other = wrapper.querySelector(flag.matches("[data-filter-empty]") ? "[data-filter-not-empty]" : "[data-filter-empty]");
      if (flag.checked) other.checked = false;
      const disabled = flag.checked || other.checked;
      wrapper.querySelectorAll("[data-filter-operator], [data-filter-value], [data-filter-upper]").forEach((item) => { item.disabled = disabled; });
    });
  });
  refreshSharedDependentFilters(container, schema);
  updateCategorizedFilterScrolling(container);
}

function sharedFilterCriteria(container) {
  const criteria = {};
  container?.querySelectorAll("[data-shared-filter]").forEach((wrapper) => {
    const fieldId = wrapper.dataset.fieldId;
    if (wrapper.querySelector("[data-filter-empty]")?.checked) {
      criteria[fieldId] = { operator: "empty" };
      return;
    }
    if (wrapper.querySelector("[data-filter-not-empty]")?.checked) {
      criteria[fieldId] = { operator: "not_empty" };
      return;
    }
    const control = wrapper.querySelector("[data-filter-value]");
    const operator = wrapper.querySelector("[data-filter-operator]")?.value || "";
    if (control.multiple) {
      const values = [...control.selectedOptions].map((option) => option.value).filter(Boolean);
      if (values.length) criteria[fieldId] = { values };
      return;
    }
    const value = control.value.trim();
    if (!value) return;
    if (operator) {
      const criterion = { operator, value };
      if (operator === "between") {
        const upper = wrapper.querySelector("[data-filter-upper]")?.value.trim() || "";
        if (!upper) return;
        criterion.to = upper;
      }
      criteria[fieldId] = criterion;
    } else {
      criteria[fieldId] = value;
    }
  });
  return criteria;
}

function clearSharedFilterValues(container) {
  container?.querySelectorAll("[data-filter-empty], [data-filter-not-empty]").forEach((input) => { input.checked = false; });
  container?.querySelectorAll("[data-filter-value], [data-filter-upper]").forEach((control) => {
    control.disabled = false;
    if (control.multiple) [...control.options].forEach((option) => { option.selected = false; });
    else control.value = "";
  });
  container?.querySelectorAll("[data-filter-operator]").forEach((control) => { control.disabled = false; control.value = "equals"; });
  container?.querySelectorAll("[data-filter-upper]").forEach((control) => { control.hidden = true; });
}

function installSharedFilterInteractions(container, options) {
  container?.addEventListener("click", async (event) => {
    const remove = event.target.closest("[data-remove-shared-filter]");
    if (remove) {
      if (!(await requestConfirmation(`إزالة المرشح «${remove.textContent}»؟`, {
        title: "إزالة مرشح",
        confirmLabel: "إزالة المرشح",
      }))) return;
      options.onRemove?.(remove.dataset.removeSharedFilter);
      return;
    }
    const suggestion = event.target.closest("[data-filter-suggestion-value]");
    if (suggestion) {
      const wrapper = suggestion.closest("[data-shared-filter]");
      wrapper.querySelector("[data-filter-value]").value = suggestion.dataset.filterSuggestionValue;
      wrapper.querySelector("[data-filter-suggestions]").hidden = true;
      wrapper.querySelector("[data-filter-value]").dispatchEvent(new Event("change", { bubbles: true }));
    }
  });
  container?.addEventListener("focusin", (event) => {
    const control = event.target.closest("[data-filter-value]");
    const schemaId = typeof options.schemaId === "function" ? options.schemaId() : options.schemaId;
    if (control && control.tagName !== "SELECT") sharedFilterSuggestions(control.closest("[data-shared-filter]"), schemaId, control.value);
  });
  let timer = null;
  container?.addEventListener("input", (event) => {
    const control = event.target.closest("[data-filter-value]");
    if (!control || control.tagName === "SELECT") return;
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      const schemaId = typeof options.schemaId === "function" ? options.schemaId() : options.schemaId;
      sharedFilterSuggestions(control.closest("[data-shared-filter]"), schemaId, control.value);
    }, 120);
  });
  container?.addEventListener("change", () => {
    const schema = typeof options.schema === "function" ? options.schema() : options.schema;
    if (schema) refreshSharedDependentFilters(container, schema);
  });
  container?.addEventListener("focusout", (event) => {
    const wrapper = event.target.closest("[data-shared-filter]");
    if (!wrapper) return;
    window.setTimeout(() => {
      if (!wrapper.contains(document.activeElement)) wrapper.querySelector("[data-filter-suggestions]").hidden = true;
    }, 100);
  });
}

/* core/multischema.js */
function activeWorkspaceSchemas() {
  return (state.workspace?.schemas || []).filter((schema) => !schema.archived);
}

async function loadWorkspaceMetadata() {
  try {
    const response = await nativeFetch("/api/workspace", { cache: "no-store" });
    if (!response.ok) {
      state.workspace = null;
      state.activeSchemaId = "";
      return;
    }
    const workspacePayload = await response.json();
    state.workspace = workspacePayload;
    const requestedSchema = state.startupIntent?.schemaId;
    state.activeSchemaId = workspacePayload.schemas?.some(
      (schema) => schema.id === requestedSchema && !schema.archived,
    )
      ? requestedSchema
      : workspacePayload.active_schema_id || "";
    ["entry", "builder", "search"].forEach((page) => {
      if (!state.pageSchemaIds[page] || !workspacePayload.schemas?.some((schema) => schema.id === state.pageSchemaIds[page] && !schema.archived)) {
        state.pageSchemaIds[page] = state.activeSchemaId;
      }
    });
    state.workspaceDefinitions = workspacePayload.definitions || {};
    const loadedDefinitions = workspacePayload.global_definitions || { categories: {}, fields: {}, revision: 0 };
    if (generalDraftDirty()) state.generalLoadedDefinitions = loadedDefinitions;
    else state.globalDefinitions = loadedDefinitions;
    state.workspaceSettings = workspacePayload.workspace_settings || { shortcuts: {} };
    applyWorkspaceBackgroundSettings();
    state.auditUserFeatureAvailable = Boolean(workspacePayload.audit_users);
    state.auditUsers = workspacePayload.audit_users || { current_user: "", users: [] };
  } catch (_error) {
    // Release 2-compatible test servers expose only the single-schema API.
    state.workspace = null;
    state.activeSchemaId = "";
    state.auditUserFeatureAvailable = false;
  }
}

function enhancePageSchemaTabs(container) {
  if (!container) return;
  container.querySelector("[data-all-schemas]")?.remove();
  const tabs = [...container.querySelectorAll(".schema-tab")];
  tabs.forEach((tab) => { tab.title = tab.textContent.trim(); });
  if (tabs.length <= 5) return;
  const button = document.createElement("button");
  button.type = "button";
  button.className = "button button-secondary all-schemas-button";
  button.dataset.allSchemas = "";
  button.append(actionIcon("search"), document.createTextNode("كل التصاميم"));
  button.addEventListener("click", () => {
    const dialog = document.createElement("dialog");
    dialog.className = "editor-dialog schema-picker-dialog";
    dialog.setAttribute("aria-label", "كل التصاميم");
    const heading = document.createElement("div");
    heading.className = "dialog-heading";
    const title = document.createElement("h2");
    title.textContent = "كل التصاميم";
    const close = document.createElement("button");
    close.type = "button";
    close.className = "dialog-close";
    close.textContent = "×";
    close.setAttribute("aria-label", "إغلاق");
    close.onclick = () => dialog.close();
    heading.append(title, close);
    const content = document.createElement("div");
    content.className = "dialog-content";
    const query = document.createElement("input");
    query.type = "search";
    query.className = "control";
    query.placeholder = "ابحث باسم التصميم";
    query.setAttribute("aria-label", query.placeholder);
    const list = document.createElement("div");
    list.className = "schema-picker-results";
    const render = () => {
      list.replaceChildren();
      tabs.filter((tab) => normalizedComparison(tab.textContent).includes(normalizedComparison(query.value))).forEach((tab) => {
        const choice = document.createElement("button");
        choice.type = "button";
        choice.className = `button ${tab.classList.contains("is-active") ? "button-primary" : "button-secondary"}`;
        choice.textContent = tab.textContent;
        choice.title = tab.title;
        choice.onclick = () => { dialog.close(); tab.click(); };
        list.append(choice);
      });
      if (!list.childElementCount) list.textContent = "لا توجد نتائج";
    };
    query.addEventListener("input", render);
    content.append(query, list);
    dialog.append(heading, content);
    dialog.addEventListener("close", () => { dialog.remove(); if (button.isConnected) button.focus(); }, { once: true });
    document.body.append(dialog);
    render();
    dialog.showModal();
    query.focus();
  });
  container.append(button);
}

function renderSchemaTabs(container, mode) {
  if (!container) return;
  const ownerDocument = container.ownerDocument;
  if (!ownerDocument) return;
  container.replaceChildren();
  if (mode === "builder") {
    const globalButton = ownerDocument.createElement("button");
    globalButton.type = "button";
    globalButton.className = `schema-tab schema-tab-global${state.builderScope === "global" ? " is-active" : ""}`;
    globalButton.dataset.builderGlobalTab = "true";
    globalButton.textContent = "التعريفات العامة";
    globalButton.setAttribute("aria-current", state.builderScope === "global" ? "page" : "false");
    const divider = ownerDocument.createElement("span");
    divider.className = "schema-tab-divider";
    divider.setAttribute("aria-hidden", "true");
    container.append(globalButton, divider);
  }
  activeWorkspaceSchemas().forEach((schema) => {
    const button = ownerDocument.createElement("button");
    button.type = "button";
    button.className = "schema-tab";
    button.dataset.schemaTab = schema.id;
    button.dataset.schemaTabMode = mode;
    button.textContent = schema.name;
    const cached = mode === "builder"
      ? state.builderTabStates.get(schema.id)
      : state.schemaTabStates.get(schema.id);
    const dirty = schema.id === state.activeSchemaId
      ? (mode === "builder" ? state.dirty : state.recordDirty)
      : cached?.dirty;
    if (dirty) button.classList.add("is-dirty");
    const selectedSchemaId = state.pageSchemaIds?.[mode] || state.activeSchemaId;
    if (schema.id === selectedSchemaId && !(mode === "builder" && state.builderScope === "global")) {
      button.classList.add("is-active");
      button.setAttribute("aria-current", "page");
    }
    container.append(button);
  });
  enhancePageSchemaTabs(container);
}

function renderAllSchemaTabs() {
  renderSchemaTabs(elements.entrySchemaTabs, "entry");
  renderSchemaTabs(elements.builderSchemaTabs, "builder");
}

function preserveActiveSchemaState() {
  if (!state.activeSchemaId || !state.schema) return;
  if (state.recordDirty) saveDraftLocally();
  state.schemaTabStates.set(state.activeSchemaId, {
    dirty: state.recordDirty,
    draftSnapshot: state.recordDirty ? collectDraftSnapshot() : null,
    selectedRecordCode: state.selectedRecordCode,
    searchFieldIds: deepClone(state.searchFieldIds),
    searchMatches: deepClone(state.searchMatches),
    searchResultIndex: state.searchResultIndex,
    scrollTop: elements.page?.scrollTop || 0,
    focusId: document.activeElement?.id || "",
  });
  state.builderTabStates.set(state.activeSchemaId, {
    dirty: state.dirty,
    draftSchema: deepClone(state.draftSchema),
    activeBuilderCategoryId: state.activeBuilderCategoryId,
    scrollTop: elements.page?.scrollTop || 0,
  });
}

function restoreActiveSchemaState(mode) {
  const entry = state.schemaTabStates.get(state.activeSchemaId);
  const builder = state.builderTabStates.get(state.activeSchemaId);
  if (builder?.dirty && builder?.draftSchema) {
    state.draftSchema = deepClone(builder.draftSchema);
    state.dirty = Boolean(builder.dirty);
    state.activeBuilderCategoryId = builder.activeBuilderCategoryId || null;
    renderBuilder();
  }
  if (entry) {
    state.searchFieldIds = deepClone(entry.searchFieldIds);
    state.searchMatches = deepClone(entry.searchMatches || []);
    state.searchResultIndex = entry.searchResultIndex || 0;
    if (entry.dirty && entry.draftSnapshot) {
      // Schema tabs must preserve unsaved work even when the user has disabled
      // local draft autosave.  The localStorage draft remains a crash-recovery
      // convenience; this in-memory snapshot is the tab state itself.
      state.skipNextLocalDraftRestore = true;
      restoreDraftSnapshot(entry.draftSnapshot, { notify: false });
    } else if (entry.selectedRecordCode && !entry.dirty) {
      void performLoadRecord(entry.selectedRecordCode, {
        force: true,
        silent: true,
        scroll: false,
        skipNavigationGuard: true,
      });
    }
    window.setTimeout(() => {
      if (elements.page) elements.page.scrollTop = entry.scrollTop || 0;
    }, 0);
  }
  renderAllSchemaTabs();
}

function fillSchemaSelect(select, { includeArchived = false } = {}) {
  if (!select) return;
  select.replaceChildren();
  const schemas = (state.workspace?.schemas || []).filter(
    (schema) => includeArchived || !schema.archived,
  );
  schemas.forEach((schema) => {
    const option = document.createElement("option");
    option.value = schema.id;
    option.textContent = schema.archived
      ? `${schema.name} (مؤرشف)`
      : schema.name;
    select.append(option);
  });
  select.value = state.activeSchemaId;
}

function renderWorkspaceChrome() {
  const schemas = activeWorkspaceSchemas();
  const multiple = schemas.length > 1;
  renderAllSchemaTabs();
  if (elements.builderActiveSchemaName) {
    elements.builderActiveSchemaName.textContent =
      state.schema?.schema_name ||
      schemas.find((schema) => schema.id === state.activeSchemaId)?.name ||
      "التصميم الحالي";
  }
  if (elements.schemaManagementPanel) {
    elements.schemaManagementPanel.hidden = !state.workspace;
    let sourceStatus = elements.schemaManagementPanel.querySelector('.schema-follow-status');
    if (!sourceStatus) {
      sourceStatus = document.createElement('p');
      sourceStatus.className = 'muted-text schema-follow-status';
      elements.schemaManagementPanel.append(sourceStatus);
    }
    const sourceId = (state.workspace?.schemas || []).find((schema) => schema.id === state.activeSchemaId)?.profile_source_schema_id;
    sourceStatus.hidden = !sourceId;
    sourceStatus.textContent = sourceId
      ? `مصدر إنشاء وحذف الملفات: ${(state.workspace?.schemas || []).find((schema) => schema.id === sourceId)?.name || sourceId}`
      : '';
  }
  const archived = (state.workspace?.schemas || []).filter((schema) => schema.archived);
  if (elements.archivedSchemaField) {
    elements.archivedSchemaField.hidden = !archived.length;
    elements.restoreSchemaButton.hidden = !archived.length;
    elements.createFromArchivedSchemaButton.hidden = !archived.length;
    elements.archivedSchemaSelect.replaceChildren();
    archived.forEach((schema) => {
      elements.archivedSchemaSelect.append(new Option(schema.name, schema.id));
    });
  }
  if (elements.linkExistingProfileButton) {
    elements.linkExistingProfileButton.hidden = !multiple;
  }
  renderMultiSchemaSearch();
}

async function switchActiveSchema(schemaId, options = {}) {
  const pageMode = ["entry", "builder", "search"].includes(options.mode)
    ? options.mode
    : "";
  if (!schemaId || schemaId === state.activeSchemaId) {
    if (pageMode) state.pageSchemaIds[pageMode] = schemaId;
    if (options.mode) performSwitchMode(options.mode);
    if (pageMode === "search" && state.searchType === "schema") {
      renderFullSearchFilters();
    }
    renderAllSchemaTabs();
    return true;
  }
  if (state.schemaSwitching) return false;
  state.schemaSwitching = true;
  preserveActiveSchemaState();
  const previousMode = state.mode;
  try {
    if (state.workspace) {
      const response = await nativeFetch("/api/workspace/select", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ schema_id: schemaId }),
      });
      await responseJson(response);
    }
    state.activeSchemaId = schemaId;
    if (pageMode) state.pageSchemaIds[pageMode] = schemaId;
    state.searchFieldIds = null;
    state.fullSearchFieldIds = null;
    state.fullSearchColumnIds = null;
    state.fullSearchCriteria = null;
    state.recordDirty = false;
    state.dirty = false;
    state.settingsDirty = false;
    state.settingsDirtyCategory = "";
    await loadSchema({ preservePage: true, forceResetRecord: true });
    const targetMode = options.mode || previousMode;
    performSwitchMode(targetMode);
    restoreActiveSchemaState(targetMode);
    if (options.openCode) {
      await performLoadRecord(options.openCode, {
        force: true,
        skipNavigationGuard: true,
      });
    }
    return true;
  } catch (error) {
    showToast(error.message, "error");
    renderAllSchemaTabs();
    return false;
  } finally {
    state.schemaSwitching = false;
  }
}

async function refreshWorkspaceAfterManagement(result) {
  await loadWorkspaceMetadata();
  const active = result?.schema?.active_schema_id || state.workspace?.active_schema_id;
  if (active) {
    state.activeSchemaId = active;
    state.pageSchemaIds.builder = active;
  }
  await loadSchema({ preservePage: true, forceResetRecord: true });
  renderWorkspaceChrome();
}

function requestNewSchemaDefinition() {
  const dialog = document.getElementById("create-schema-dialog");
  const form = document.getElementById("create-schema-form");
  const name = document.getElementById("create-schema-name");
  const follow = document.getElementById("create-schema-follow");
  const source = document.getElementById("create-schema-source");
  form.reset();
  source.replaceChildren(...activeWorkspaceSchemas().map((schema) => new Option(schema.name, schema.id)));
  source.value = state.activeSchemaId;
  const toggle = () => {
    document.getElementById("create-schema-source-field").hidden = !follow.checked;
    document.getElementById("create-schema-follow-description").hidden = !follow.checked;
    source.required = follow.checked;
  };
  toggle();
  return new Promise((resolve) => {
    let result = null;
    const submit = (event) => {
      event.preventDefault();
      if (!name.value.trim() || (follow.checked && !source.value)) return;
      result = { name: name.value.trim(), profile_source_schema_id: follow.checked ? source.value : "" };
      dialog.close();
    };
    follow.addEventListener("change", toggle);
    form.addEventListener("submit", submit);
    dialog.addEventListener("close", () => {
      follow.removeEventListener("change", toggle);
      form.removeEventListener("submit", submit);
      resolve(result);
    }, { once: true });
    dialog.showModal();
    name.focus();
  });
}

async function runSchemaManagement(action) {
  if (!builderUnlocked()) {
    showToast("إدارة التصاميم متاحة في وضع الإدارة فقط.", "error");
    return;
  }
  let name = "";
  let profileSourceId = "";
  if (action === "create") {
    const definition = await requestNewSchemaDefinition();
    if (!definition) return;
    name = definition.name;
    profileSourceId = definition.profile_source_schema_id;
  }
  if (["duplicate", "rename"].includes(action)) {
    const currentName = state.schema?.schema_name || "";
    name = await requestText({
      title: action === "rename" ? "إعادة تسمية التصميم" : action === "duplicate" ? "نسخ بنية التصميم" : "تصميم جديد",
      label: action === "rename" ? "الاسم الجديد" : "اسم التصميم",
      value: action === "duplicate" ? `${currentName} - نسخة` : action === "rename" ? currentName : "",
      confirmLabel: action === "rename" ? "حفظ الاسم" : "إنشاء التصميم",
    });
    if (name == null || !name.trim()) return;
  }
  if (action === "archive") {
    if (!(await requestConfirmation("ستُنشأ نسخة احتياطية ثم يُؤرشف التصميم الحالي.", {
      title: "أرشفة التصميم",
      confirmLabel: "إنشاء النسخة والأرشفة",
    }))) {
      return;
    }
  }
  try {
    const response = await nativeFetch("/api/workspace/schemas", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Schema-ID": state.activeSchemaId,
      },
      body: JSON.stringify({
        action,
        name,
        schema_id: state.activeSchemaId,
        template_schema_id: action === "duplicate" ? state.activeSchemaId : "",
        profile_source_schema_id: profileSourceId,
      }),
    });
    const result = await responseJson(response);
    await refreshWorkspaceAfterManagement(result);
    showToast("تم تحديث التصاميم بنجاح.");
  } catch (error) {
    showToast(error.message, "error");
  }
}

async function restoreArchivedSchema() {
  const schemaId = elements.archivedSchemaSelect?.value;
  if (!schemaId || !builderUnlocked()) return;
  try {
    const response = await nativeFetch("/api/workspace/schemas", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Schema-ID": state.activeSchemaId,
      },
      body: JSON.stringify({ action: "restore", schema_id: schemaId }),
    });
    const result = await responseJson(response);
    await refreshWorkspaceAfterManagement(result);
    showToast("تمت استعادة التصميم المؤرشف.");
  } catch (error) {
    showToast(error.message, "error");
  }
}

async function createFromArchivedSchema() {
  const templateId = elements.archivedSchemaSelect?.value;
  if (!templateId || !builderUnlocked()) return;
  const template = (state.workspace?.schemas || []).find((schema) => schema.id === templateId);
  const name = await requestText({
    title: "إنشاء تصميم من بنية مؤرشفة",
    message: "تُنسخ البنية فقط دون البيانات.",
    label: "اسم التصميم الجديد",
    value: `${template?.name || "تصميم"} - جديد`,
    confirmLabel: "إنشاء التصميم",
  });
  if (name == null || !name.trim()) return;
  try {
    const response = await nativeFetch("/api/workspace/schemas", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Schema-ID": state.activeSchemaId },
      body: JSON.stringify({ action: "duplicate", name, template_schema_id: templateId }),
    });
    const result = await responseJson(response);
    await refreshWorkspaceAfterManagement(result);
    showToast("تم إنشاء تصميم جديد بالبنية نفسها وبيانات فارغة.");
  } catch (error) { showToast(error.message, "error"); }
}

async function deleteWorkspaceSchema() {
  if (!builderUnlocked()) return;
  const selectedArchived = elements.archivedSchemaSelect?.value;
  const targetId = selectedArchived || state.activeSchemaId;
  const target = (state.workspace?.schemas || []).find((schema) => schema.id === targetId);
  if (!target) return;
  const confirmationName = await requestText({
    title: "حذف التصميم نهائيًا",
    message: "سيُحذف التصميم مع كل بياناته ومرفقاته، وستُنشأ نسخة احتياطية أولًا.",
    label: `اكتب الاسم كاملًا للتأكيد: ${target.name}`,
    confirmLabel: "حذف التصميم",
  });
  if (confirmationName == null) return;
  try {
    const response = await nativeFetch("/api/workspace/schemas", {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Schema-ID": state.activeSchemaId },
      body: JSON.stringify({ action: "delete", schema_id: targetId, confirmation_name: confirmationName }),
    });
    const result = await responseJson(response);
    await refreshWorkspaceAfterManagement(result);
    showToast("تم حذف التصميم بعد إنشاء النسخة الاحتياطية.");
  } catch (error) { showToast(error.message, "error"); }
}

function multiSearchEligibleFields(schema) {
  return (schema?.categories || []).flatMap((category) =>
    category.fields
      .filter((field) => !isSystemField(field) && field.type !== "file")
      .map((field) => ({ category, field })),
  );
}

function multiSearchConfig(schemaId) {
  if (!state.multiSearchConfigs.has(schemaId)) {
    const schema = state.workspaceDefinitions[schemaId];
    const fields = multiSearchEligibleFields(schema);
    const defaultColumns = fields
      .filter(({ field }) => field.show_in_results)
      .map(({ field }) => field.id);
    state.multiSearchConfigs.set(schemaId, {
      schemaId,
      schema,
      selected: schemaId === state.activeSchemaId,
      offset: 0,
      resultFieldIds: defaultColumns.length
        ? defaultColumns
        : fields.slice(0, 4).map(({ field }) => field.id),
    });
  }
  return state.multiSearchConfigs.get(schemaId);
}

function createMultiFilterControl(field, schemaId) {
  let control;
  if (["select", "yes_no"].includes(field.type)) {
    control = document.createElement("select");
    control.append(new Option("الكل", ""));
    (field.options || []).filter((option) => option.active !== false).forEach((option) => {
      control.append(new Option(option.label, option.id || option.label));
    });
  } else if (field.type === "checkbox") {
    control = document.createElement("select");
    control.append(new Option("الكل", ""), new Option("نعم", "true"), new Option("لا", "false"));
  } else if (field.type === "checkbox_group") {
    control = document.createElement("select");
    control.multiple = true;
    (field.options || []).filter((option) => option.active !== false).forEach((option) => {
      control.append(new Option(option.label, option.id || option.label));
    });
  } else {
    control = document.createElement("input");
    control.type = field.type === "number" ? "text" : "text";
    control.placeholder = field.placeholder || "";
  }
  control.className = "control";
  control.dataset.multiFilterField = field.id;
  control.dataset.multiSchema = schemaId;
  return control;
}

function renderMultiQueryCard(config) {
  const schema = config.schema;
  const card = document.createElement("details");
  card.className = "workspace-panel multi-schema-query-card";
  card.open = true;
  card.dataset.multiQuerySchema = config.schemaId;
  const summary = document.createElement("summary");
  summary.textContent = schema.schema_name || schema.app?.title || "تصميم";
  card.append(summary);

  const systemGrid = document.createElement("div");
  systemGrid.className = "field-grid compact-grid multi-system-filters";
  const idField = document.createElement("label");
  idField.className = "field";
  idField.innerHTML = "<span>ID</span>";
  const idInput = document.createElement("input");
  idInput.className = "control";
  idInput.dir = "ltr";
  idInput.dataset.multiRecordCode = config.schemaId;
  idField.append(idInput);
  const archived = document.createElement("label");
  archived.className = "check-field multi-archive-filter";
  const archivedInput = document.createElement("input");
  archivedInput.type = "checkbox";
  archivedInput.dataset.multiArchived = config.schemaId;
  archived.append(archivedInput, document.createTextNode(" إظهار المؤرشفة"));
  systemGrid.append(idField);
  systemGrid.append(archived);
  card.append(systemGrid);

  const fields = multiSearchEligibleFields(schema);
  const filterDetails = document.createElement("details");
  filterDetails.className = "multi-query-options";
  const filterSummary = document.createElement("summary");
  filterSummary.textContent = "مرشحات الحقول";
  filterDetails.append(filterSummary);
  const filterGrid = document.createElement("div");
  filterGrid.className = "field-grid compact-grid";
  fields.filter(({ field }) => field.searchable).forEach(({ category, field }) => {
    const wrapper = document.createElement("label");
    wrapper.className = "field";
    const label = document.createElement("span");
    label.textContent = `${category.label} — ${field.label}`;
    const control = createMultiFilterControl(field, config.schemaId);
    const emptyLabel = document.createElement("label");
    emptyLabel.className = "check-field empty-value-filter";
    const empty = document.createElement("input");
    empty.type = "checkbox";
    empty.dataset.multiEmptyField = field.id;
    empty.addEventListener("change", () => {
      control.disabled = empty.checked;
      if (empty.checked) setControlValue(control, "");
    });
    emptyLabel.append(empty, document.createTextNode("القيمة فارغة"));
    wrapper.append(label, control, emptyLabel);
    filterGrid.append(wrapper);
  });
  if (!filterGrid.childElementCount) {
    const empty = document.createElement("p");
    empty.className = "muted-text";
    empty.textContent = "لا توجد حقول معلّمة للبحث في هذا التصميم.";
    filterGrid.append(empty);
  }
  filterDetails.append(filterGrid);
  card.append(filterDetails);

  const columnDetails = document.createElement("details");
  columnDetails.className = "multi-query-options";
  const columnSummary = document.createElement("summary");
  columnSummary.textContent = "أعمدة جدول النتائج";
  columnDetails.append(columnSummary);
  const columnGrid = document.createElement("div");
  columnGrid.className = "multi-column-grid";
  fields.forEach(({ category, field }) => {
    const label = document.createElement("label");
    label.className = "check-field";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = config.resultFieldIds.includes(field.id);
    checkbox.dataset.multiResultField = field.id;
    checkbox.dataset.multiSchema = config.schemaId;
    label.append(checkbox, document.createTextNode(`${category.label} — ${field.label}`));
    columnGrid.append(label);
  });
  columnDetails.append(columnGrid);
  card.append(columnDetails);
  return card;
}

function renderGlobalSearchSettings() {
  if (!elements.globalSearchFieldOptions) return;
  const fields = Object.values(state.globalDefinitions?.fields || {});
  elements.globalSearchFieldOptions.replaceChildren();
  fields.forEach((item) => {
    const definition = item.definition || {};
    if (definition.type === "file" || isSystemField(definition)) return;
    const label = document.createElement("label");
    label.className = "check-field";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = state.globalSearchFieldRefs.includes(item.id);
    checkbox.dataset.globalSearchFieldOption = item.id;
    label.append(checkbox, document.createTextNode(definition.label || item.id));
    elements.globalSearchFieldOptions.append(label);
  });
  if (!elements.globalSearchFieldOptions.childElementCount) {
    elements.globalSearchFieldOptions.textContent = "لا توجد حقول عامة قابلة للبحث بعد.";
  }
}

function renderGlobalSearchCriteria() {
  if (!elements.globalSearchFields) return;
  elements.globalSearchFields.replaceChildren();
  state.globalSearchFieldRefs.forEach((globalRef) => {
    const definition = state.globalDefinitions?.fields?.[globalRef]?.definition;
    if (!definition) return;
    const wrapper = document.createElement("label");
    wrapper.className = "field";
    const label = document.createElement("span");
    label.textContent = definition.label;
    const control = createMultiFilterControl(definition, "global");
    control.removeAttribute("data-multi-filter-field");
    control.dataset.globalSearchField = globalRef;
    if (["text", "textarea"].includes(definition.type)) {
      control.placeholder = "يمكن إدخال عدة قيم مفصولة بسطر جديد";
    }
    wrapper.append(label, control);
    elements.globalSearchFields.append(wrapper);
  });
}

function syncGeneralSearchMode() {
  document.querySelectorAll("[data-search-type]").forEach((button) => {
    const active = button.dataset.searchType === state.searchType;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  elements.schemaSearchWorkflow.hidden = state.searchType !== "schema";
  elements.multiSchemaSearch.hidden = state.searchType !== "global";
  elements.searchSchemaChoiceList?.querySelectorAll("[data-search-schema]").forEach((button) => {
    const active = state.searchType === "schema" && button.dataset.searchSchema === (state.pageSchemaIds.search || state.activeSchemaId);
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
}

function applyGeneralSearchSettings(kind) {
  activeWorkspaceSchemas().forEach((schema) => {
    const config = globalQueryConfig(schema.id);
    if (!config.selected) return;
    if (kind === "filter") {
      config.searchFieldIds = [...elements.fullSearchFilterOptions.querySelectorAll(`[data-global-query-search-field="${CSS.escape(schema.id)}"]:checked`)].map((input) => input.value);
    } else {
      config.displayFieldIds = [...elements.fullSearchColumnOptions.querySelectorAll(`[data-global-query-display-field="${CSS.escape(schema.id)}"]:checked`)].map((input) => input.value);
    }
  });
  renderGlobalSearchSelectionSummaries();
  syncGeneralSearchMode();
}

function globalQueryConfig(schemaId) {
  if (!state.globalQueryConfigs.has(schemaId)) {
    const definition = state.workspaceDefinitions?.[schemaId];
    const mainFields = (definition?.categories || []).filter((category) => category.kind === "main").flatMap((category) => category.fields || []).filter((field) => field.type !== "file");
    const defaults = mainFields.filter((field) => field.show_in_results).map((field) => field.id);
    state.globalQueryConfigs.set(schemaId, { schemaId, selected: schemaId === (state.pageSchemaIds.search || state.activeSchemaId), searchFieldIds: [], displayFieldIds: defaults });
  }
  return state.globalQueryConfigs.get(schemaId);
}

function fieldTreeForSchema(schemaId, attribute, selectedIds) {
  const root = document.createElement("div");
  root.className = "tree-field-options";
  const definition = state.workspaceDefinitions?.[schemaId];
  (definition?.categories || []).forEach((category) => {
    const fields = (category.fields || []).filter((field) => field.type !== "file");
    if (!fields.length) return;
    const group = document.createElement("details");
    group.className = "tree-option-group search-field-option-group";
    group.dataset.globalOptionCategory = category.id;
    group.dataset.globalOptionAttribute = attribute;
    group.open = false;
    const summary = document.createElement("summary");
    summary.className = "search-field-option-category";
    const categoryLabel = document.createElement("label");
    categoryLabel.className = "check-field";
    const categoryToggle = document.createElement("input");
    categoryToggle.type = "checkbox";
    categoryToggle.dataset.globalCategoryOption = category.id;
    categoryToggle.dataset.globalCategorySchema = schemaId;
    const categoryText = document.createElement("span");
    categoryText.textContent = category.label;
    categoryLabel.append(categoryToggle, categoryText);
    summary.append(categoryLabel);
    const list = document.createElement("div");
    list.className = "search-field-option-grid";
    fields.forEach((field) => {
      const label = document.createElement("label");
      label.className = "check-field";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.value = field.id;
      input.dataset[attribute] = schemaId;
      input.checked = selectedIds.includes(field.id);
      label.append(input, document.createTextNode(field.label));
      list.append(label);
    });
    group.append(summary, list);
    root.append(group);
    const selectedCount = [...list.querySelectorAll('input[type="checkbox"]')].filter((input) => input.checked).length;
    categoryToggle.checked = selectedCount === fields.length;
    categoryToggle.indeterminate = selectedCount > 0 && selectedCount < fields.length;
  });
  return root;
}

function renderGlobalSchemaFieldSettings(kind, options = {}) {
  const container = kind === "filter" ? elements.fullSearchFilterOptions : elements.fullSearchColumnOptions;
  const attribute = kind === "filter" ? "globalQuerySearchField" : "globalQueryDisplayField";
  container.replaceChildren();
  activeWorkspaceSchemas().filter((schema) => globalQueryConfig(schema.id).selected).forEach((schema) => {
    const config = globalQueryConfig(schema.id);
    const definition = state.workspaceDefinitions?.[schema.id];
    const mainFields = (definition?.categories || []).filter((category) => category.kind === "main").flatMap((category) => category.fields || []).filter((field) => field.type !== "file");
    const defaults = kind === "filter" ? [] : mainFields.filter((field) => field.show_in_results).map((field) => field.id);
    const selectedIds = options.fresh
      ? []
      : (options.reset ? defaults : (kind === "filter" ? config.searchFieldIds : config.displayFieldIds));
    const section = document.createElement("section");
    section.className = "global-schema-config-section";
    const title = document.createElement("h3");
    title.textContent = schema.name;
    section.append(title, fieldTreeForSchema(schema.id, attribute, selectedIds));
    container.append(section);
  });
  if (!container.childElementCount) emptyDashboard(container, "اختر تصميمًا واحدًا على الأقل أولًا.");
}

function renderGlobalSearchSelectionSummaries() {
  const render = (container, kind) => {
    if (!container) return;
    container.replaceChildren();
    const selectedSchemas = activeWorkspaceSchemas().filter((schema) => globalQueryConfig(schema.id).selected);
    let count = 0;
    selectedSchemas.forEach((schema) => {
      const config = globalQueryConfig(schema.id);
      const ids = kind === "filter" ? config.searchFieldIds : config.displayFieldIds;
      const definition = state.workspaceDefinitions?.[schema.id];
      if (!ids.length && kind === "filter") {
        const chip = document.createElement("span");
        chip.className = "selection-chip";
        chip.textContent = `${schema.name}: كل الحقول المناسبة`;
        container.append(chip);
        count += 1;
        return;
      }
      (definition?.categories || []).forEach((category) => {
        const fields = (category.fields || []).filter((field) => ids.includes(field.id));
        if (!fields.length) return;
        const group = document.createElement("section");
        group.className = "selection-category-group";
        const heading = document.createElement("strong");
        heading.textContent = `${schema.name} — ${category.label}`;
        const chips = document.createElement("div");
        chips.className = "selection-chip-list";
        fields.forEach((field) => {
          const chip = document.createElement("button");
          chip.type = "button";
          chip.className = "selection-chip selection-chip-button";
          if (kind === "column") {
            chip.dataset.removeGlobalResultField = field.id;
            chip.dataset.removeGlobalResultSchema = schema.id;
            chip.title = "إزالة من حقول النتائج";
          } else {
            chip.dataset.removeGlobalFilterField = field.id;
            chip.dataset.removeGlobalFilterSchema = schema.id;
            chip.title = "إزالة من حقول المطابقة";
          }
          chip.textContent = field.label;
          chips.append(chip);
          count += 1;
        });
        group.append(heading, chips);
        container.append(group);
      });
    });
    if (!count) {
      const empty = document.createElement("span");
      empty.className = "selection-chip selection-chip-empty";
      empty.textContent = "لا توجد اختيارات";
      container.append(empty);
    }
  };
  render(elements.globalFilterSelectionSummary, "filter");
  render(elements.globalFieldSelectionSummary, "column");
}

function renderMultiSchemaSearch() {
  if (!elements.multiSchemaSearch) return;
  const schemas = activeWorkspaceSchemas();
  elements.searchSchemaChoiceList?.replaceChildren();
  schemas.forEach((schemaInfo) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `schema-tab${state.searchType === "schema" && schemaInfo.id === (state.pageSchemaIds.search || state.activeSchemaId) ? " is-active" : ""}`;
    button.dataset.searchSchema = schemaInfo.id;
    button.setAttribute("role", "tab");
    button.setAttribute("aria-selected", String(state.searchType === "schema" && schemaInfo.id === (state.pageSchemaIds.search || state.activeSchemaId)));
    button.textContent = schemaInfo.name;
    elements.searchSchemaChoiceList?.append(button);
  });
  enhancePageSchemaTabs(elements.searchSchemaChoiceList?.closest(".search-scope-strip"));
  elements.globalQuerySchemaList?.replaceChildren();
  schemas.forEach((schemaInfo) => {
    const config = globalQueryConfig(schemaInfo.id);
    const button = document.createElement("button");
    button.type = "button";
    button.className = `button button-secondary schema-choice-button${config.selected ? " is-active" : ""}`;
    button.dataset.globalQuerySchema = schemaInfo.id;
    button.setAttribute("aria-pressed", String(config.selected));
    button.textContent = schemaInfo.name;
    elements.globalQuerySchemaList?.append(button);
  });
  renderGlobalSearchSelectionSummaries();
  syncGeneralSearchMode();
}

function multiControlValue(control) {
  if (control.multiple) {
    return [...control.selectedOptions].map((option) => option.value);
  }
  return control.value;
}

function collectMultiCriteria(config) {
  const root = elements.multiSchemaQueryList.querySelector(
    `[data-multi-query-schema="${CSS.escape(config.schemaId)}"]`,
  );
  const searchableIds = [];
  const criteria = {
    _record_code: root.querySelector("[data-multi-record-code]")?.value.trim() || "",
    _include_archived: Boolean(root.querySelector("[data-multi-archived]")?.checked),
    _allow_empty: true,
    _offset: config.offset || 0,
    _limit: Number(config.schema.app?.search_page_size || 50),
  };
  root.querySelectorAll("[data-multi-filter-field]").forEach((control) => {
    searchableIds.push(control.dataset.multiFilterField);
    if (root.querySelector(
      `[data-multi-empty-field="${CSS.escape(control.dataset.multiFilterField)}"]`,
    )?.checked) {
      criteria[control.dataset.multiFilterField] = { empty: true };
      return;
    }
    const value = multiControlValue(control);
    if (Array.isArray(value) ? value.length : String(value || "").trim()) {
      criteria[control.dataset.multiFilterField] = value;
    }
  });
  criteria._search_field_ids = searchableIds;
  config.resultFieldIds = [
    ...root.querySelectorAll("[data-multi-result-field]:checked"),
  ].map((control) => control.dataset.multiResultField);
  criteria._result_field_ids = config.resultFieldIds;
  return criteria;
}

function renderMultiResults() {
  elements.multiSchemaResults.replaceChildren();
  const fragment = document.createDocumentFragment();
  for (const [schemaId, result] of state.multiSearchResults) {
    const section = document.createElement("section");
    section.className = "workspace-panel multi-result-section global-result-group";
    const heading = document.createElement("div");
    heading.className = "search-table-summary";
    const title = document.createElement("strong");
    title.textContent = `${result.schema_name} — ${result.total} نتيجة`;
    heading.append(title);
    section.append(heading);
    const columnMap = new Map();
    (result.matches || []).forEach((match) => {
      (match.details || []).forEach((detail) => {
        const key = detail.field_id || detail.label;
        if (!columnMap.has(key)) columnMap.set(key, { id: key, label: detail.label || key });
      });
    });
    const columns = [...columnMap.values()];
    const tableScroll = document.createElement("div");
    tableScroll.className = "table-scroll global-result-table-scroll";
    const table = document.createElement("table");
    table.className = "data-table records-table global-result-table";
    const head = document.createElement("thead");
    const headerRow = document.createElement("tr");
    ["ID", "الحالة", ...columns.map((column) => column.label), "موضع المطابقة", "الإجراءات"].forEach((label) => {
      const cell = document.createElement("th");
      cell.scope = "col";
      cell.textContent = label;
      headerRow.append(cell);
    });
    head.append(headerRow);
    const body = document.createElement("tbody");
    (result.matches || []).forEach((match) => {
      const row = document.createElement("tr");
      const code = document.createElement("td");
      code.dir = "ltr";
      code.textContent = match.record_code;
      const status = document.createElement("td");
      status.textContent = match.archived ? "مؤرشف" : "نشط";
      if (match.archived) {
        const archived = document.createElement("span");
        archived.className = "archived-badge";
        archived.textContent = "مؤرشف";
        status.replaceChildren(archived);
      }
      row.append(code, status);
      const details = new Map((match.details || []).map((detail) => [detail.field_id || detail.label, detail.value ?? ""]));
      columns.forEach((column) => {
        const cell = document.createElement("td");
        cell.textContent = details.get(column.id) ?? "";
        row.append(cell);
      });
      const matched = document.createElement("td");
      matched.className = "global-match-locations";
      matched.textContent = (match.matched_at || []).map((item) => `${item.category} ← ${item.field}: ${item.value}`).join(" · ");
      const actions = document.createElement("td");
      actions.className = "record-row-actions";
      const button = document.createElement("button");
      button.className = "button button-quiet";
      button.type = "button";
      button.textContent = "فتح";
      button.dataset.openMultiRecord = match.record_code;
      button.dataset.openMultiSchema = schemaId;
      const readonly = document.createElement("button");
      readonly.className = "button button-quiet";
      readonly.type = "button";
      readonly.textContent = "قراءة فقط";
      readonly.dataset.readonlyMultiRecord = match.record_code;
      readonly.dataset.openMultiSchema = schemaId;
      actions.append(button, readonly);
      row.append(matched, actions);
      body.append(row);
    });
    if (!(result.matches || []).length) {
      const row = document.createElement("tr");
      const cell = document.createElement("td");
      cell.className = "table-empty";
      cell.colSpan = 4 + columns.length;
      cell.textContent = "لا توجد نتائج مطابقة في هذا التصميم.";
      row.append(cell);
      body.append(row);
    }
    table.append(head, body);
    tableScroll.append(table);
    section.append(tableScroll);
    fragment.append(section);
  }
  elements.multiSchemaResults.append(fragment);
}

async function runMultiSchemaSearch(options = {}) {
  if (!Object.prototype.hasOwnProperty.call(options, "notes")) {
    const notes = await requestSearchNotes();
    if (notes === null) return;
    return runMultiSchemaSearch({ notes });
  }
  const configs = activeWorkspaceSchemas().map((schema) => globalQueryConfig(schema.id)).filter((config) => config.selected);
  if (!configs.length) {
    failPendingSearchResultsWindow("اختر تصميمًا واحدًا على الأقل.");
    showToast("اختر تصميمًا واحدًا على الأقل.", "error");
    return;
  }
  elements.runMultiSchemaSearch.disabled = true;
  try {
    const schemas = configs.map((config) => ({
      schema_id: config.schemaId,
      search_field_ids: config.searchFieldIds,
      display_field_ids: config.displayFieldIds,
      include_archived: elements.fullSearchIncludeArchived.checked,
    }));
    const response = await fetch("/api/search/query", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: elements.globalSearchQuery.value.trim(), schemas }),
    });
    const result = await responseJson(response);
    state.multiSearchResults = new Map(
      result.results.map((schemaResult) => [schemaResult.schema_id, schemaResult]),
    );
    renderMultiResults();
    elements.singleSchemaResultsPanel.hidden = true;
    elements.multiSchemaResults.hidden = false;
    openSearchResultsWindow("نتائج البحث العام", elements.multiSchemaResults);
    rememberSearchHistory({
      mode: "global",
      name: "",
      notes: options.notes || "",
      query: elements.globalSearchQuery.value.trim(),
      schema_ids: schemas.map((item) => item.schema_id),
      filters: { schemas: deepClone(schemas) },
      headers: Object.fromEntries(schemas.map((item) => [item.schema_id, item.display_field_ids])),
      result_total: (result.results || []).reduce((sum, item) => sum + Number(item.total || 0), 0),
      results: { results: deepClone(result.results || []) },
    });
    renderSearchHistory();
  } catch (error) {
    failPendingSearchResultsWindow(error.message);
    showToast(error.message, "error");
  } finally {
    elements.runMultiSchemaSearch.disabled = false;
  }
}

function restoreMultiSchemaSearchHistory(item) {
  if (item.mode === "global") {
    state.generalSearchMode = "global";
    state.globalSearchFieldRefs = Array.isArray(item.global_refs) ? deepClone(item.global_refs) : [];
    renderMultiSchemaSearch();
    elements.globalSearchRecordCode.value = item.criteria?.record_code || "";
    elements.globalSearchFields.querySelectorAll("[data-global-search-field]").forEach((control) => {
      const value = item.criteria?.fields?.[control.dataset.globalSearchField];
      if (value != null) setControlValue(control, value);
    });
    void runMultiSchemaSearch();
    return;
  }
  state.generalSearchMode = "advanced";
  const queries = item.criteria?.queries || [];
  const selected = new Set(queries.map((query) => query.schema_id));
  activeWorkspaceSchemas().forEach((schema) => {
    const config = multiSearchConfig(schema.id);
    config.selected = selected.has(schema.id);
    const query = queries.find((candidate) => candidate.schema_id === schema.id);
    if (query) config.resultFieldIds = deepClone(query.criteria?._result_field_ids || config.resultFieldIds);
  });
  renderMultiSchemaSearch();
  queries.forEach((query) => {
    const root = elements.multiSchemaQueryList.querySelector(`[data-multi-query-schema="${CSS.escape(query.schema_id)}"]`);
    if (!root) return;
    const criteria = query.criteria || {};
    const id = root.querySelector("[data-multi-record-code]");
    const archived = root.querySelector("[data-multi-archived]");
    if (id) id.value = criteria._record_code || "";
    if (archived) archived.checked = Boolean(criteria._include_archived);
    root.querySelectorAll("[data-multi-filter-field]").forEach((control) => {
      if (!Object.prototype.hasOwnProperty.call(criteria, control.dataset.multiFilterField)) return;
      const saved = criteria[control.dataset.multiFilterField];
      const empty = saved && typeof saved === "object" && saved.empty === true;
      const emptyControl = root.querySelector(
        `[data-multi-empty-field="${CSS.escape(control.dataset.multiFilterField)}"]`,
      );
      if (emptyControl) emptyControl.checked = empty;
      control.disabled = empty;
      setControlValue(control, empty ? "" : saved);
    });
  });
  void runMultiSchemaSearch();
}

function openProfileLinkDialog() {
  elements.profileSourceSchema.replaceChildren();
  elements.profileSourceSchema.append(new Option("اكتب ID ثم افحص الملفات", ""));
  elements.profileSourceId.value = "";
  elements.profileMappingList.replaceChildren();
  elements.profileMappingArea.hidden = true;
  elements.profileGlobalConflicts.hidden = true;
  elements.profileGlobalConflicts.replaceChildren();
  elements.profileLinkStatus.textContent = "";
  elements.confirmProfileLinkButton.disabled = true;
  state.profileTransferInspection = null;
  elements.profileLinkDialog.showModal();
}

function profileValueText(source) {
  const values = source.display_values || source.values || [];
  if (!values.length) return "—";
  return values.map((value) => Array.isArray(value) ? value.join("، ") : String(value ?? "")).join(" | ") || "—";
}

function renderProfileGlobalConflicts(conflicts = []) {
  elements.profileGlobalConflicts.replaceChildren();
  elements.profileGlobalConflicts.hidden = !conflicts.length;
  if (!conflicts.length) return;
  const heading = document.createElement("strong");
  heading.textContent = "توجد قيم مختلفة في الحقول العامة — اختر ملف المصدر الذي تريد الاعتماد عليه";
  elements.profileGlobalConflicts.append(heading);
  conflicts.forEach((conflict) => {
    const item = document.createElement("div");
    item.className = "profile-global-conflict-item";
    const label = document.createElement("b");
    label.textContent = conflict.label || conflict.global_ref;
    const values = document.createElement("ul");
    (conflict.sources || []).forEach((source) => {
      const row = document.createElement("li");
      row.textContent = `${source.schema_name}: ${profileValueText(source)}`;
      values.append(row);
    });
    item.append(label, values);
    elements.profileGlobalConflicts.append(item);
  });
}

function renderProfileMappings(inspection) {
  elements.profileMappingList.replaceChildren();
  inspection.source_fields.forEach((source) => {
    const row = document.createElement("div");
    row.className = "profile-mapping-row";
    const sourceCell = document.createElement("div");
    const label = document.createElement("strong");
    label.textContent = `${source.category} — ${source.label}`;
    const value = document.createElement("span");
    value.textContent = profileValueText(source);
    sourceCell.append(label, value);
    const select = document.createElement("select");
    select.className = "control";
    select.dataset.profileSourceField = source.field_id;
    select.append(new Option("لا تنقل هذا الحقل", ""));
    const groups = new Map();
    inspection.target_fields.forEach((target) => {
      if (!groups.has(target.category)) {
        const group = document.createElement("optgroup");
        group.label = target.category;
        groups.set(target.category, group);
        select.append(group);
      }
      groups.get(target.category).append(new Option(`${target.label} (${target.type})`, target.field_id));
    });
    select.value = inspection.suggestions[source.field_id] || "";
    row.append(sourceCell, select);
    elements.profileMappingList.append(row);
  });
  elements.profileMappingArea.hidden = false;
  elements.confirmProfileLinkButton.disabled = false;
}

async function inspectProfileLink() {
  const recordCode = elements.profileSourceId.value.trim().toUpperCase();
  if (!/^[A-Z][A-Z0-9]{7}$/.test(recordCode)) {
    showToast("أدخل ID صالحًا من 8 أحرف.", "error");
    return;
  }
  elements.inspectProfileLinkButton.disabled = true;
  elements.profileLinkStatus.textContent = "جاري تحميل الملف المصدر…";
  try {
    const identityResponse = await fetch("/api/identities/inspect", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ target_schema_id: state.activeSchemaId, record_code: recordCode }),
    });
    const identity = await responseJson(identityResponse);
    if (!identity.profiles.length) throw new Error("لم يُعثر على ملف لهذا الشخص في تصميم آخر.");
    renderProfileGlobalConflicts(identity.global_conflicts || []);
    const previousSource = elements.profileSourceSchema.value;
    elements.profileSourceSchema.replaceChildren();
    identity.profiles.forEach((profile) => {
      elements.profileSourceSchema.append(new Option(profile.schema_name, profile.schema_id));
    });
    if (identity.profiles.some((profile) => profile.schema_id === previousSource)) {
      elements.profileSourceSchema.value = previousSource;
    }
    const response = await fetch("/api/profiles/inspect", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        source_schema_id: elements.profileSourceSchema.value,
        target_schema_id: state.activeSchemaId,
        record_code: recordCode,
      }),
    });
    state.profileTransferInspection = await responseJson(response);
    renderProfileMappings(state.profileTransferInspection);
    elements.profileLinkStatus.textContent = identity.global_conflicts?.length
      ? "اختر ملف المصدر بعد مراجعة اختلاف القيم، ثم راجع المطابقات."
      : "راجع الاقتراحات وعدّل أي مطابقة يدويًا.";
  } catch (error) {
    elements.profileLinkStatus.textContent = error.message;
    showToast(error.message, "error");
  } finally {
    elements.inspectProfileLinkButton.disabled = false;
  }
}

async function confirmProfileLink() {
  const inspection = state.profileTransferInspection;
  if (!inspection) return;
  const mappings = [...elements.profileMappingList.querySelectorAll("[data-profile-source-field]")]
    .filter((select) => select.value)
    .map((select) => ({
      source_field_id: select.dataset.profileSourceField,
      target_field_id: select.value,
    }));
  if (!mappings.length) {
    showToast("اختر مطابقة حقل واحدة على الأقل.", "error");
    return;
  }
  elements.confirmProfileLinkButton.disabled = true;
  try {
    const response = await fetch("/api/profiles/link", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        source_schema_id: inspection.source_schema_id,
        target_schema_id: inspection.target_schema_id,
        record_code: inspection.record_code,
        mappings,
      }),
    });
    const result = await responseJson(response);
    elements.profileLinkDialog.close();
    await loadSchema({ preservePage: true });
    state.pageSchemaIds.entry = state.activeSchemaId;
    performSwitchMode("entry");
    await performLoadRecord(result.record_code, { force: true, skipNavigationGuard: true });
    showToast("تم إنشاء الملف المرتبط باستخدام ID نفسه.");
  } catch (error) {
    elements.profileLinkStatus.textContent = error.message;
    showToast(error.message, "error");
  } finally {
    elements.confirmProfileLinkButton.disabled = false;
  }
}

[
  elements.entrySchemaTabs,
  elements.builderSchemaTabs,
].forEach((container) => container?.addEventListener("click", (event) => {
  const globalTab = event.target.closest("[data-builder-global-tab]");
  if (globalTab) {
    state.builderScope = "global";
    renderBuilderScope();
    renderAllSchemaTabs();
    return;
  }
  const tab = event.target.closest("[data-schema-tab]");
  if (tab) {
    if (tab.dataset.schemaTabMode === "builder") state.builderScope = "schema";
    void switchActiveSchema(tab.dataset.schemaTab, { mode: tab.dataset.schemaTabMode }).then(() => {
      if (tab.dataset.schemaTabMode === "builder") renderBuilderScope();
    });
  }
}));
