// One sprite and action vocabulary for static and dynamically rendered buttons.
function standardizeActionButton(button) {
  if (!(button instanceof HTMLButtonElement)) return;
  // Text navigation and existing glyph buttons do not need a second decorative icon.
  if (button.matches('.schema-tab, .home-schema-browser-tab, .dashboard-history-row, .dialog-close, .related-tab-close, .category-nav-toggle, .builder-preview-name, .home-add-stat, .studio-drop-zone > button')) {
    button.querySelector('svg[data-auto-action-icon]')?.remove();
    return;
  }
  const identity = `${button.id} ${button.getAttribute("aria-label") || ""} ${button.textContent}`;
  const rules = [
    ["backup", "backup", /backup|احتياط/],
    ["close", "exit", /إغلاق/],
    ["restore", "restore", /restore|استعادة/],
    ["delete", "trash", /delete|remove|حذف/],
    ["discard", "clear", /discard|تجاهل/],
    ["save", "save", /save|حفظ/],
    ["cancel", "clear", /cancel|إلغاء/],
    ["archive", "archive", /archive|أرشفة/],
    ["add", "plus", /add|new|إضافة|جديد|إنشاء/],
    ["clear", "clear", /clear|مسح/],
    ["search", "search", /search|بحث/],
    ["edit", "edit", /edit|rename|تعديل|تسمية/],
    ["clear", "clear", /clear|مسح/],
  ];
  const navigation = button.matches('[role="tab"], .schema-tab, .dashboard-history-row, .category-nav-button, .home-schema-browser-tab');
  const matched = navigation ? null : rules.find(([, , pattern]) => pattern.test(identity));
  if (!matched) {
    button.querySelector('svg[data-auto-action-icon]')?.remove();
    return;
  }
  const kind = matched[0];
  const icon = matched?.[1] || (button.matches('[role="tab"], .schema-tab, .selection-chip') ? "tag" : "open");
  button.dataset.actionKind = kind;
  let svg = button.querySelector("svg.action-icon");
  if (!svg && !button.querySelector("svg")) {
    svg = actionIcon(icon);
    svg.dataset.autoActionIcon = "";
    button.prepend(svg);
  }
  const use = svg?.querySelector("use");
  if (matched && use && use.getAttribute("href") !== `#icon-${icon}`) use.setAttribute("href", `#icon-${icon}`);
}
function standardizeActionButtons(root) {
  if (root.nodeType !== 1) return;
  if (root.matches("button")) standardizeActionButton(root);
  root.querySelectorAll("button").forEach(standardizeActionButton);
}
standardizeActionButtons(document.body);
new MutationObserver((mutations) => {
  const roots = new Set();
  mutations.forEach((mutation) => {
    const button = mutation.target.nodeType === 1 ? mutation.target.closest("button") : mutation.target.parentElement?.closest("button");
    if (button) roots.add(button);
    mutation.addedNodes.forEach((node) => { if (node.nodeType === 1) roots.add(node); });
  });
  roots.forEach(standardizeActionButtons);
}).observe(document.body, { childList: true, subtree: true, characterData: true });

document.addEventListener("mouseover", (event) => {
  const target = event.target.closest?.("h1,h2,h3,h4,h5,h6,label,strong,small,span,p,td,th,a,button,input,textarea,select");
  if (!target || target.closest("svg") || target.type === "password" || (["entry", "builder", "readonly"].includes(state.mode) && target.closest("#category-navigator"))) return;
  const text = target.matches("input,textarea") ? target.value
    : target.matches("select") ? target.selectedOptions?.[0]?.textContent
    : target.textContent;
  if (text?.trim() && (!target.title || target.dataset.fullTextTitle)) {
    target.title = text.trim();
    target.dataset.fullTextTitle = "true";
  }
});
