      const text=body.replace(/\{\{(\w+)\}\}/g,(all,key)=>['toc','pagebreak'].includes(key)?all:key==='date'?new Date().toLocaleDateString('ar'):definitions[key]?'⟦ '+(definitions[key].title||key)+' ⟧':'⚠ '+key);
