 const friendly=text=>String(text||'').replace(/\{\{([^}]+)\}\}/g,(_,key)=>'⟦ '+(key.startsWith('value:')?inlineLabel(key):key==='date'?'التاريخ':metricName(key)!==key?metricName(key):fieldOptions(b.dataset,true).find(([id])=>id===key.replace(/^field:/,''))?.[1]||key)+' ⟧');
